function startEliteHardeningSupervisor(){ try { const hard=global.__SBC_ELITE_HARDENING; if(!hard)return; const run=async()=>{ try { await hard.ensureTables(); const worker=await hard.runExperimentWorker(1); if(worker?.winners?.length) jsonLog('info','elite_closer_experiment_worker',worker); if(mysqlPool){ const [rows]=await mysqlPool.query("SELECT * FROM sbc_closer_handshakes_v56121 WHERE status='QUEUED' ORDER BY created_at ASC LIMIT 10"); let sent=0; for(const row of rows){ const c=(db.customers||[]).find(x=>String(x.id)===String(row.lead_id)); if(!c)continue; const out=await hard.processHandshake({...row,payload:row.payload_json?JSON.parse(row.payload_json||'{}'):{}},c); if(out?.status==='SENT')sent++; } if(sent) jsonLog('info','elite_closer_handshake_worker',{sent}); } } catch(e){ jsonLog('error','elite_closer_hardening_supervisor_error',{error:e.message}); } }; run(); sbcBackgroundTimers.push(setInterval(run,Math.max(300000,Number(process.env.SBC_ELITE_HARDENING_INTERVAL_MS||300000)))); } catch(e){ console.warn('[ELITE CLOSER HARDENING] startup:',e.message); } }

function startRevenueAutopilotSupervisor(){ try {
  const run=async()=>{
    try{
      if(db.fantastic4?.autonomous?.paused)return;
      const tenantId=Number(process.env.SBC_AUTOMATION_TENANT_ID);if(!Number.isSafeInteger(tenantId)||tenantId<1)return;
      const scoped={...db,customers:(db.customers||[]).filter(c=>Number(c.tenantId)===tenantId)};
      const out=REVENUE_AUTOPILOT_ENGINE.buildCycle(scoped,{limit:200});
      db.revenueAutopilot=db.revenueAutopilot||{};
      db.revenueAutopilot.lastCycle={...out,tenantId};
      db.revenueAutopilot.lastRunAt=out.generatedAt;
      await saveData();
      const followups=await processRevenueFollowups({tenantId});
      jsonLog('info','revenue_autopilot_cycle_v56131',{version:out.version,customersEvaluated:out.customersEvaluated,actions:out.actions.length,counts:out.counts,financials:out.financials,followupProcessed:followups?.processed||0,followupSent:followups?.sent||0,followupBlocked:followups?.blocked||0});
    }catch(e){jsonLog('error','revenue_autopilot_cycle_v56131_error',{error:e.message});}
  };
  run();
  sbcBackgroundTimers.push(setInterval(run,Math.max(15*60*1000,Number(process.env.SBC_REVENUE_AUTOPILOT_INTELLIGENCE_INTERVAL_MS||60*60*1000))));
 }catch(e){console.warn('[REVENUE AUTOPILOT V56.13.1] startup:',e.message);} }

function startRevenueGrowthSupervisor(){ try { const growth=global.__SBC_REVENUE_GROWTH; if(!growth)return; const run=async()=>{ try { const tenantId=1; const auto=String(process.env.SBC_REVENUE_GROWTH_AUTO_EXECUTE||'false').toLowerCase()==='true' && String(process.env.SBC_REVENUE_AUTOPILOT_ENABLED||'true').toLowerCase()!=='false'; const out=await growth.cycle({tenantId,limit:Math.max(25,Math.min(250,Number(process.env.SBC_REVENUE_GROWTH_BATCH||100))),auto}); if(out?.metrics) jsonLog('info','revenue_growth_engine_cycle',{version:out.version,qualified:out.metrics.qualified,conversations:out.metrics.conversations,sales:out.metrics.sales,revenue:out.metrics.revenue,revenuePerConversation:out.metrics.revenuePerConversation,opportunities:out.metrics.opportunities,auto}); } catch(e){ jsonLog('error','revenue_growth_engine_cycle_error',{error:e.message}); } }; run(); sbcBackgroundTimers.push(setInterval(run,Math.max(300000,Number(process.env.SBC_REVENUE_GROWTH_INTERVAL_MS||300000)))); } catch(e){ console.warn('[REVENUE GROWTH] startup:',e.message); } }

async function runGrowthLedgerSnapshot(){ try { const G=global.__SBC_GROWTH_OPS; if(!G||!mysqlPool)return; await G.ensureTables(mysqlPool); const tenantId=1; const date=new Date(Date.now()-86400000); const out=await G.buildSnapshot({db,pool:mysqlPool,tenantId,date}); jsonLog('info','growth_ledger_nightly',{ledgerDate:out.ledgerDate,leads:out.metrics.leads,qualified:out.metrics.qualified,customers:out.metrics.customers,orders:out.metrics.orders,revenue:out.metrics.revenue,calls:out.metrics.calls,conversionRate:out.metrics.conversionRate}); } catch(e){ jsonLog('error','growth_ledger_nightly_error',{error:e.message}); } }
function startGrowthLedger(){ try { const schedule=()=>{ const now=new Date(),next=new Date(Date.UTC(now.getUTCFullYear(),now.getUTCMonth(),now.getUTCDate()+1,0,10,0)); const wait=Math.max(1000,next.getTime()-now.getTime()); const timer=setTimeout(()=>{runGrowthLedgerSnapshot();schedule();},wait); sbcBackgroundTimers.push(timer); }; schedule(); } catch(e){ console.warn('[GROWTH LEDGER] startup:',e.message); } }
function startEliteCloserSupervisor(){ try { const elite=global.__SBC_ELITE_CLOSER; if(!elite)return; const run=async()=>{ try { const leads=(db.customers||[]).filter(c=>String(c.status||'').toLowerCase()!=='do not contact'); const queue=await elite.buildQueue(leads,c=>REVENUE_CLOSER.eligibility(c,{policy:'strict'}),1); const hard=global.__SBC_ELITE_HARDENING; const ready=queue.filter(x=>x.eligible&&!(hard&&hard.isFrozen(x.leadId))); if(ready.length) jsonLog('info','elite_closer_supervisor',{ready:ready.length,topLead:ready[0]?.leadId||'',topAction:ready[0]?.action||'',topScore:ready[0]?.priorityScore||0}); const auto=String(process.env.SBC_ELITE_CLOSER_AUTO_DISPATCH||'false').toLowerCase()==='true'; if(auto&&typeof global.__SBC_ELITE_CLOSER_DISPATCH_CALL==='function'){ const max=Math.max(1,Math.min(10,Number(process.env.SBC_ELITE_CLOSER_AUTO_BATCH||3))); const active=Array.isArray(db.aiCallSessions)?db.aiCallSessions:[]; let sent=0; for(const q of ready){ if(sent>=max) break; const recent=active.some(x=>String(x.leadId)===String(q.leadId)&&Date.now()-new Date(x.createdAt||0).getTime()<24*60*60*1000); if(recent) continue; try{await global.__SBC_ELITE_CLOSER_DISPATCH_CALL(q.leadId,1); sent++;}catch(e){jsonLog('warn','elite_closer_auto_dispatch_blocked',{leadId:q.leadId,error:e.message,eligibility:e.eligibility||null});}} if(sent) jsonLog('info','elite_closer_auto_dispatch',{sent,batch:max}); } } catch(e){ jsonLog('error','elite_closer_supervisor_error',{error:e.message}); } }; run(); sbcBackgroundTimers.push(setInterval(run,Math.max(300000,Number(process.env.SBC_ELITE_CLOSER_INTERVAL_MS||600000)))); } catch(e){ console.warn('[ELITE CLOSER] startup:',e.message); } }



