// V30.1.3 defensive runtime: log fatal process faults and exit cleanly so the
// host process manager (or PM2 in safe single-instance/fork mode) can restart the app.
// Do not attempt in-process recovery from an unknown state.
let fatalRuntimeFault = false;
process.on('uncaughtException', (err) => {
  fatalRuntimeFault = true;
  console.error('[SBC FATAL] uncaughtException:', err?.stack || err?.message || err); try { SELF_HEAL.observeError(err,{type:'uncaughtException'}); } catch {}
  setTimeout(() => process.exit(1), 100);
});
process.on('unhandledRejection', (reason) => {
  // A persistence attempt rejected because recovery is intentionally locked is a
  // controlled safety outcome, not a process-fatal runtime fault. The global API
  // gate rejects external writes before route handlers; this branch protects
  // internal fire-and-forget jobs during startup/recovery from restarting the app.
  if (isExpectedRecoveryRejection(reason)) {
    console.warn('[SBC RECOVERY GUARD] expected persistence rejection during recovery; no write accepted and process remains available for read-only diagnostics.');
    try { SELF_HEAL.observeError(reason,{type:'recoveryWriteBlocked'}); } catch {}
    return;
  }
  console.error('[SBC FATAL] unhandledRejection:', reason?.stack || reason?.message || reason); try { SELF_HEAL.observeError(reason,{type:'unhandledRejection'}); } catch {}
  setTimeout(() => process.exit(1), 100);
});

