// V32.0.0 — World-Ready Integration Gateway Hub.
// Gateways are provider-neutral and fail closed: unconfigured providers report STANDBY
// instead of crashing the application. Secrets may come from the encrypted vault or approved runtime environment fallback.
const GATEWAY_DEFINITIONS = [
  {id:'square',name:'Square Payments',category:'Payments',env:['SQUARE_ACCESS_TOKEN','SQUARE_LOCATION_ID'],url:'https://developer.squareup.com/',critical:true},
  {id:'twilio',name:'Twilio Voice & SMS',category:'Communications',env:['TWILIO_ACCOUNT_SID','TWILIO_AUTH_TOKEN','TWILIO_PHONE_NUMBER'],url:'https://www.twilio.com/docs',critical:true},
  {id:'godaddy',name:'GoDaddy Domains & Hosting',category:'Domains / Hosting',env:['GODADDY_PAT'],url:'https://developer.godaddy.com/',critical:true},
  {id:'four_over_four',name:'4OVER4 Print',category:'Fulfillment',env:['FOUROVER4_API_URL','FOUROVER4_API_KEY'],url:'https://www.4over4.com/',critical:false},
  {id:'vistaprint',name:'VistaPrint Print',category:'Fulfillment',env:['VISTAPRINT_API_URL','VISTAPRINT_API_KEY'],url:'https://www.vistaprint.com/',critical:false},
  {id:'openai',name:'OpenAI AI',category:'AI / Kim',env:['OPENAI_API_KEY'],url:'https://platform.openai.com/',critical:true},
  {id:'microsoft365',name:'Microsoft 365',category:'Email / Productivity',env:['MS_GRAPH_CLIENT_ID','MS_GRAPH_CLIENT_SECRET','MS_GRAPH_TENANT_ID'],url:'https://learn.microsoft.com/graph/',critical:false},
  {id:'redis',name:'Redis',category:'Sessions / Cache',env:['REDIS_URL','SBC_REDIS_URL'],url:'https://redis.io/',critical:false},
  {id:'auth0',name:'Auth0 / OIDC',category:'Identity',env:['SBC_OIDC_ISSUER','SBC_OIDC_CLIENT_ID'],url:'https://auth0.com/',critical:false},
  {id:'temporal',name:'Temporal',category:'Durable Workflows',env:['TEMPORAL_ADDRESS','TEMPORAL_NAMESPACE'],url:'https://temporal.io/',critical:false},
  {id:'amqp',name:'RabbitMQ / AMQP',category:'Event Bus',env:['AMQP_URL'],url:'https://www.rabbitmq.com/',critical:false},
  {id:'otel',name:'OpenTelemetry',category:'Observability',env:['OTEL_EXPORTER_OTLP_ENDPOINT'],url:'https://opentelemetry.io/',critical:false}
];
function gatewayStatus(g){
  const aliases={TWILIO_AUTH_TOKEN:['SBC_TWILIO_AUTH_TOKEN'],GODADDY_PAT:['GODADDY_PAT'],FOUROVER4_API_KEY:['FOUROVER4_API_KEY'],VISTAPRINT_API_KEY:['VISTAPRINT_API_KEY']};
  const present=k=>Boolean(process.env[k]||(typeof secretCache!=='undefined'&&secretCache.has(k))||(aliases[k]||[]).some(a=>typeof secretCache!=='undefined'&&secretCache.has(a)));
  const configured=g.env.some(present);
  const complete=g.env.every(present);
  return {id:g.id,name:g.name,category:g.category,critical:g.critical,configured,complete,status:complete?'READY':configured?'PARTIAL':'STANDBY',url:g.url,missing:g.env.filter(k=>!present(k))};
}
function gatewayReadiness(){
  const gateways=GATEWAY_DEFINITIONS.map(gatewayStatus);
  return {version:BUILD_VERSION,generatedAt:new Date().toISOString(),gateways,summary:{ready:gateways.filter(x=>x.status==='READY').length,partial:gateways.filter(x=>x.status==='PARTIAL').length,standby:gateways.filter(x=>x.status==='STANDBY').length}};
}

// SBC_V6549_LORNA_LEAST_PRIVILEGE: deny-by-default workforce boundary for the Lead Researcher role. This runs before API routes, including routes that were previously missing auth middleware.
function sbcLornaRole(user){return ['lead_researcher','lead_generator','researcher','prospector'].includes(String(user?.role||'').trim().toLowerCase());}
function sbcLornaAllowedRequest(req,user){
 const p=String(req.path||''),m=String(req.method||'GET').toUpperCase();
 if(!p.startsWith('/api/'))return !/^\/(?:office-box|ops-center|admin|settings|system-console|commercial-console)(?:\/|$)/i.test(p);
 if((p==='/api/login'||p==='/api/logout')&&['POST','GET'].includes(m))return true;
 if(['/api/me','/api/release-identity','/api/bootstrap','/api/catalog'].includes(p))return m==='GET';
 if(p==='/api/v9/bootstrap')return m==='GET';
 if(p==='/api/v9/lead-verification')return m==='GET';
 if(/^\/api\/v9\/lead-verification\/[^/]+$/.test(p))return m==='POST';
 if(p==='/api/v9/time/clock')return m==='POST';
 if(p==='/api/v9/time/status')return m==='GET';
 if(p==='/api/workforce/lorna')return m==='GET';
 if(p==='/api/workforce/lead-draft')return ['GET','PUT','DELETE'].includes(m);
 if(p==='/api/workforce/leads')return ['GET','POST'].includes(m);
 if(/^\/api\/workforce\/leads\/[^/]+$/.test(p))return ['GET','PUT'].includes(m);
 if(p==='/api/v10/leads/submit')return m==='POST';
 // Researchers use /api/workforce/leads; owner CSV import stays owner-only.
 if(p==='/api/training')return m==='GET';
 if(/^\/api\/training\/courses\/[^/]+$/.test(p))return m==='GET';
 if(/^\/api\/training\/history\/[^/]+$/.test(p)&&m==='GET'){
  const requested=decodeURIComponent(p.split('/').pop()||'');
  return [user?.id,user?.username].some(x=>x!=null&&String(x)===requested);
 }
 if(['/api/training/telemetry','/api/training/progress','/api/training/attempts'].includes(p))return m==='POST';
 if(/(?:^|\/)(?:time[-_]?clock|clock[-_]?in|clock[-_]?out|time[-_]?entries|timeentries)(?:\/|$)/i.test(p)&&['GET','POST'].includes(m)&&!/(?:admin|team|payroll|export|audit|settings|users|all)/i.test(p))return true;
 if(/^\/api\/(?:workforce\/)?(?:onboarding\/me|onboarding\/self|workforce\/onboarding)(?:\/|$)/i.test(p)&&['GET','POST'].includes(m))return true;
 return false;
}
app.use(async function sbcLornaLeastPrivilegeGate(req,res,next){
 const p=String(req.path||'');
 const isApi=p.startsWith('/api/');
 const isSensitivePage=/^\/(?:office-box|ops-center|admin|settings|system-console|commercial-console)(?:\/|$)/i.test(p);
 if(!isApi&&!isSensitivePage)return next();
 if(isApi&&['/api/login','/api/release-identity'].includes(p))return next();
 try{
  const user=await sessionUser(req);
  req._sbcRoleIdentity=user;if(!user||!sbcLornaRole(user))return next();
  if(sbcLornaAllowedRequest(req,user))return next();
  res.setHeader('Cache-Control','no-store');
  return res.status(403).json({ok:false,code:'LORNA_LEAST_PRIVILEGE_DENIED',error:'This page or API is outside the Lead Researcher role.'});
 }catch(e){
  console.warn('[SBC LORNA ACCESS] session verification failed; restricted request blocked:',String(e?.code||e?.message||'session error'));
  return res.status(503).json({ok:false,code:'LORNA_ACCESS_VERIFICATION_FAILED',error:'Access could not be verified. The request was blocked.'});
 }
});

// SBC_V6676_DEMO_VIEWER_API: server-enforced allowlist, not a cosmetic CSS restriction.
function sbcDemoViewerAllowed(method,route){
 const p=String(route||'').split('?')[0],m=String(method||'GET').toUpperCase();
 if(m==='POST'&&p==='/api/logout')return true;
 return m==='GET'&&['/api/me','/api/bootstrap','/api/catalog','/api/release-identity'].includes(p);
}
app.use(async function sbcDemoViewerGate(req,res,next){
 const p=String(req.path||'');if(!p.startsWith('/api/')||p==='/api/login')return next();
 try{
  const user=Object.hasOwn(req,'_sbcRoleIdentity')?req._sbcRoleIdentity:await sessionUser(req);
  if(!user||String(user.role||'')!=='demo')return next();
  if(sbcDemoViewerAllowed(req.method,p))return next();
  res.setHeader('Cache-Control','private, no-store');
  return res.status(403).json({ok:false,code:'SBC_DEMO_READ_ONLY',error:'Demo mode uses sample data only. Sign in as the owner to perform business operations.'});
 }catch(e){return res.status(503).json({ok:false,code:'DEMO_AUTH_UNAVAILABLE',error:'Demo permissions could not be verified safely.'});}
});
