async function ensureRevenueOSSchema(){
  if(!mysqlPool)return;
  await mysqlPool.query(`CREATE TABLE IF NOT EXISTS sbc_revenue_control (tenant_id BIGINT PRIMARY KEY,global_kill TINYINT(1) NOT NULL DEFAULT 0,outbound_kill TINYINT(1) NOT NULL DEFAULT 0,sales_kill TINYINT(1) NOT NULL DEFAULT 0,fulfillment_kill TINYINT(1) NOT NULL DEFAULT 0,updated_by VARCHAR(120),updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4`);
  await mysqlPool.query(`CREATE TABLE IF NOT EXISTS sbc_revenue_lead_scores (id BIGINT AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,lead_id VARCHAR(120) NOT NULL,score INT NOT NULL DEFAULT 0,tier VARCHAR(20) NOT NULL DEFAULT 'COLD',signals_json LONGTEXT,reasons_json LONGTEXT,model_version VARCHAR(60) NOT NULL,calculated_at DATETIME NOT NULL,UNIQUE KEY uq_revenue_lead_score(tenant_id,lead_id),KEY idx_revenue_score(tenant_id,score,tier)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4`);
  await mysqlPool.query(`CREATE TABLE IF NOT EXISTS sbc_revenue_tasks (task_id VARCHAR(120) PRIMARY KEY,tenant_id BIGINT NOT NULL,lead_id VARCHAR(120),action VARCHAR(80) NOT NULL,priority VARCHAR(20) NOT NULL DEFAULT 'NORMAL',status VARCHAR(20) NOT NULL DEFAULT 'OPEN',due_at DATETIME NULL,payload_json LONGTEXT,idempotency_key CHAR(64) NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uq_revenue_task_idem(tenant_id,idempotency_key),KEY idx_revenue_task_queue(tenant_id,status,priority,due_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4`);
  await mysqlPool.query(`CREATE TABLE IF NOT EXISTS sbc_revenue_events (event_id VARCHAR(120) PRIMARY KEY,tenant_id BIGINT NOT NULL,lead_id VARCHAR(120),event_type VARCHAR(80) NOT NULL,state_from VARCHAR(30),state_to VARCHAR(30),payload_json LONGTEXT,idempotency_key CHAR(64) NOT NULL,created_at DATETIME NOT NULL,UNIQUE KEY uq_revenue_event_idem(tenant_id,idempotency_key),KEY idx_revenue_event_lead(tenant_id,lead_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4`);
  await mysqlPool.query(`CREATE TABLE IF NOT EXISTS sbc_revenue_touch_suppression (id BIGINT AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,contact_id VARCHAR(120) NOT NULL,channel VARCHAR(30) NOT NULL,purpose VARCHAR(50) NOT NULL,opt_in_proof VARCHAR(500),suppressed TINYINT(1) NOT NULL DEFAULT 0,source VARCHAR(120),created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uq_touch_policy(tenant_id,contact_id,channel,purpose),KEY idx_touch_contact(tenant_id,contact_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4`);  await mysqlPool.query(`CREATE TABLE IF NOT EXISTS sbc_lead_consent_registry (id BIGINT AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,contact_id VARCHAR(120),phone VARCHAR(40) NOT NULL,has_marketing_consent TINYINT(1) NOT NULL DEFAULT 0,opt_in_timestamp DATETIME NULL,consent_source VARCHAR(120),consent_text VARCHAR(1000),suppressed TINYINT(1) NOT NULL DEFAULT 0,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uq_consent_phone(tenant_id,phone),KEY idx_consent_contact(tenant_id,contact_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4`);
  await mysqlPool.query(`CREATE TABLE IF NOT EXISTS sbc_agent_event_bus (id BIGINT AUTO_INCREMENT PRIMARY KEY,event_type VARCHAR(100) NOT NULL,aggregate_type VARCHAR(80),aggregate_id VARCHAR(120),source_agent VARCHAR(100),payload JSON,idempotency_key CHAR(64) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'pending',priority INT NOT NULL DEFAULT 5,error_log TEXT,created_at DATETIME NOT NULL,processed_at DATETIME NULL,UNIQUE KEY uq_agent_event_idem(idempotency_key),KEY idx_agent_queue(status,priority,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4`);
  await mysqlPool.query(`CREATE TABLE IF NOT EXISTS sbc_money_machine_actions (id BIGINT AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,lead_id VARCHAR(120) NOT NULL,action VARCHAR(80) NOT NULL,priority VARCHAR(20) NOT NULL,reason VARCHAR(500),status VARCHAR(30) NOT NULL DEFAULT 'OPEN',idempotency_key CHAR(64) NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uq_money_action(tenant_id,idempotency_key),KEY idx_money_queue(tenant_id,status,priority,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4`);  await mysqlPool.query(`CREATE TABLE IF NOT EXISTS sbc_sale_execution (id BIGINT AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,lead_id VARCHAR(120) NOT NULL,state VARCHAR(40) NOT NULL,package_name VARCHAR(160),price DECIMAL(12,2),channel VARCHAR(30),purpose VARCHAR(60),owner_approval_required TINYINT(1) NOT NULL DEFAULT 0,block_reason VARCHAR(255),proposal_id VARCHAR(120),checkout_id VARCHAR(120),order_id VARCHAR(120),idempotency_key CHAR(64) NOT NULL,payload_json LONGTEXT,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uq_sale_execution(tenant_id,lead_id,idempotency_key),KEY idx_sale_execution_queue(tenant_id,state,updated_at),KEY idx_sale_execution_lead(tenant_id,lead_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4`);

}
async function revenueControl(tenantId){
  if(!mysqlPool)return {globalKill:false,outboundKill:false,salesKill:false,fulfillmentKill:false};
  await ensureRevenueOSSchema();
  const [rows]=await mysqlPool.query('SELECT * FROM sbc_revenue_control WHERE tenant_id=? LIMIT 1',[tenantId]);
  return rows[0]||{tenant_id:tenantId,globalKill:false,outboundKill:false,salesKill:false,fulfillmentKill:false};
}
async function revenueSafety(req,res,next){
  try{
    const tenantId=requireRequestTenant(req), c=await revenueControl(tenantId);
    const path=req.path||'';
    if(c.globalKill)return res.status(503).json({ok:false,error:'SBC_GLOBAL_REVENUE_KILL_ACTIVE',retryable:false});
    if(c.salesKill && /quote|checkout|sales|outreach|call|sms|voice/i.test(path))return res.status(503).json({ok:false,error:'SBC_SALES_KILL_ACTIVE',retryable:false});
    if(c.outboundKill && /twilio|sms|voice|call|outreach|communications/i.test(path))return res.status(503).json({ok:false,error:'SBC_OUTBOUND_KILL_ACTIVE',retryable:false});
    if(c.fulfillmentKill && /fulfillment|provision|delivery/i.test(path))return res.status(503).json({ok:false,error:'SBC_FULFILLMENT_KILL_ACTIVE',retryable:false});
    req.revenueControl=c; next();
  }catch(e){return res.status(503).json({ok:false,error:'REVENUE_CONTROL_UNAVAILABLE'});}
}
app.use('/api/revenue-os',auth,revenueSafety);
app.get('/api/revenue-os/status',async(req,res)=>{try{const tenantId=requireRequestTenant(req);const c=await revenueControl(tenantId);res.json({ok:true,version:REVENUE_OS.VERSION,control:c});}catch(e){res.status(503).json({ok:false,error:e.message});}});
app.post('/api/revenue-os/score',async(req,res)=>{try{const tenantId=requireRequestTenant(req),lead=req.body?.lead||{},scored=REVENUE_OS.scoreLead(lead);if(mysqlPool){await ensureRevenueOSSchema();await mysqlPool.query(`INSERT INTO sbc_revenue_lead_scores(tenant_id,lead_id,score,tier,signals_json,reasons_json,model_version,calculated_at) VALUES(?,?,?,?,?,?,?,UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE score=VALUES(score),tier=VALUES(tier),signals_json=VALUES(signals_json),reasons_json=VALUES(reasons_json),model_version=VALUES(model_version),calculated_at=UTC_TIMESTAMP()`,[tenantId,String(lead.id||lead.leadId||''),scored.score,scored.tier,JSON.stringify(scored.signals),JSON.stringify(scored.reasons),REVENUE_OS.VERSION]);}res.json({ok:true,tenantId,leadId:lead.id||lead.leadId||null,...scored,nextAction:REVENUE_OS.nextBestAction({...lead,...scored})});}catch(e){res.status(400).json({ok:false,error:e.message});}});
app.post('/api/revenue-os/transition',async(req,res)=>{try{REVENUE_OS.stateTransition(req.body?.from,req.body?.to);const tenantId=requireRequestTenant(req);const payload=req.body?.payload||{};const idem=REVENUE_OS.idempotencyKey('transition',{tenantId,leadId:req.body?.leadId,from:req.body?.from,to:req.body?.to,payload});if(mysqlPool){await ensureRevenueOSSchema();await mysqlPool.query(`INSERT INTO sbc_revenue_events(event_id,tenant_id,lead_id,event_type,state_from,state_to,payload_json,idempotency_key,created_at) VALUES(?,?,?,?,?,?,?,?,UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE event_id=event_id`,[crypto.randomUUID(),tenantId,String(req.body?.leadId||''),'STATE_TRANSITION',req.body.from,req.body.to,JSON.stringify(payload),idem]);}res.json({ok:true,state:req.body.to,idempotencyKey:idem});}catch(e){res.status(409).json({ok:false,error:e.message});}});
