app.post('/api/revenue-os/control',ownerOnly,async(req,res)=>{try{const tenantId=requireRequestTenant(req),b=req.body||{};await ensureRevenueOSSchema();if(mysqlPool)await mysqlPool.query(`INSERT INTO sbc_revenue_control(tenant_id,global_kill,outbound_kill,sales_kill,fulfillment_kill,updated_by,updated_at) VALUES(?,?,?,?,?,?,UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE global_kill=VALUES(global_kill),outbound_kill=VALUES(outbound_kill),sales_kill=VALUES(sales_kill),fulfillment_kill=VALUES(fulfillment_kill),updated_by=VALUES(updated_by),updated_at=UTC_TIMESTAMP()`,[tenantId,b.globalKill?1:0,b.outboundKill?1:0,b.salesKill?1:0,b.fulfillmentKill?1:0,req.user?.id||'owner']);res.json({ok:true,control:await revenueControl(tenantId)});}catch(e){res.status(503).json({ok:false,error:e.message});}});
app.post('/api/revenue-os/communication-check',async(req,res)=>{try{const tenantId=requireRequestTenant(req),b=req.body||{};let suppressed=Boolean(b.suppressed),optInProof=Boolean(b.optInProof);if(mysqlPool&&b.contactId){await ensureRevenueOSSchema();const [r]=await mysqlPool.query('SELECT suppressed,opt_in_proof FROM sbc_revenue_touch_suppression WHERE tenant_id=? AND contact_id=? AND channel=? AND purpose=? LIMIT 1',[tenantId,String(b.contactId),String(b.channel||'sms'),String(b.purpose||'marketing')]);if(r[0]){suppressed=Boolean(r[0].suppressed);optInProof=Boolean(r[0].opt_in_proof);}}res.json({ok:true,...REVENUE_OS.communicationGate({...b,suppressed,optInProof})});}catch(e){res.status(503).json({ok:false,error:e.message});}});
