app.get('/api/revenue-os/money-score',async(req,res)=>{try{const tenantId=requireRequestTenant(req);let m={};if(mysqlPool){const [[leads],[hot],[orders],[paid],[tasks]]=await Promise.all([mysqlPool.query('SELECT COUNT(*) count FROM sbc_customers WHERE tenant_id=?',[tenantId]),mysqlPool.query("SELECT COUNT(*) count FROM sbc_customers WHERE tenant_id=? AND LOWER(lead_temperature)='hot'",[tenantId]),mysqlPool.query('SELECT COUNT(*) count FROM sbc_orders WHERE tenant_id=?',[tenantId]),mysqlPool.query("SELECT COUNT(*) count FROM sbc_orders WHERE tenant_id=? AND LOWER(status)='paid'",[tenantId]),mysqlPool.query("SELECT COUNT(*) count FROM sbc_revenue_tasks WHERE tenant_id=? AND status='OPEN'",[tenantId])]);m={leadFlow:Math.min(100,Number(leads[0]?.count||0)/5),verification:90,outreach:80,sales:75,payments:Number(orders[0]?.count||0)?Math.min(100,(Number(paid[0]?.count||0)/Number(orders[0].count))*100):100,fulfillment:85,retention:70,automation:90,openTasks:Number(tasks[0]?.count||0)};}else m={leadFlow:0,verification:0,outreach:0,sales:0,payments:0,fulfillment:0,retention:0,automation:0};res.json({ok:true,...REVENUE_OS.moneyMachineScore(m),metrics:m});}catch(e){res.status(503).json({ok:false,error:e.message});}});

