app.post('/api/money-machine-2/action',ownerOnly,async(req,res)=>{try{const tenantId=requireRequestTenant(req),b=req.body||{};if(!b.leadId)throw new Error('LEAD_ID_REQUIRED');const action=MONEY_MACHINE_2.nextAction(b);const idem=crypto.createHash('sha256').update(JSON.stringify({tenantId,leadId:String(b.leadId),action:action.action})).digest('hex');await ensureRevenueOSSchema();if(mysqlPool)await mysqlPool.query(`INSERT INTO sbc_money_machine_actions(tenant_id,lead_id,action,priority,reason,status,idempotency_key,created_at,updated_at) VALUES(?,?,?,?,?,'OPEN',?,UTC_TIMESTAMP(),UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE updated_at=UTC_TIMESTAMP()`,[tenantId,String(b.leadId),action.action,action.priority,action.reason,idem]);res.status(201).json({ok:true,queued:true,leadId:String(b.leadId),...action,idempotencyKey:idem});}catch(e){res.status(400).json({ok:false,error:e.message});}});
