const ZERO_TRUST_PUBLIC_API_ALLOWLIST=[/^\/api\/voice\/twiml$/, /^\/api\/login$/, /^\/api\/portal\//, /^\/api\/webhooks\/(stripe|square|4over4|vistaprint)$/, /^\/api\/v462\/webhooks\//, /^\/api\/public\/checkout$/, /^\/api\/health$/, /^\/__sbc_health$/];
app.use((req,res,next)=>{if(String(process.env.SBC_ZERO_TRUST_ENFORCE||'true')!=='true'||!req.path.startsWith('/api/'))return next();if(ZERO_TRUST_PUBLIC_API_ALLOWLIST.some(rx=>rx.test(req.path)))return next();if(sessionCookieToken(req)||String(req.headers.authorization||'').startsWith('Bearer '))return next();return res.status(401).json({error:'Zero-trust edge: authenticated session required.'});});
// V56.9.1 capability gasket: optional rotating capability for intentionally public API paths. Authenticated sessions bypass it.
app.use((req,res,next)=>{if(String(process.env.SBC_PUBLIC_CAPABILITY_REQUIRED||'false').toLowerCase()!=='true'||req.path!=='/api/public/checkout')return next();if(sessionCookieToken(req)||String(req.headers.authorization||'').startsWith('Bearer '))return next();const cap=req.get('x-sbc-capability')||req.query?.capability||'';if(!V569_PRODUCTION_EXPANSION.verifyCapability(cap,req.path))return res.status(404).json({error:'Public capability required.'});next();});

const PRODUCTION_READINESS = require('./enterprise/production-readiness-gate');
