app.get('/healthz',async(req,res)=>{
  try{
    const dbReady=Boolean(mysqlPool);
    let mysqlOk=false;
    if(mysqlPool){await mysqlPool.query('SELECT 1');mysqlOk=true;}
    const production=String(process.env.NODE_ENV||'').toLowerCase()==='production';
    const ok=!production || (dbReady&&mysqlOk);
    res.status(ok?200:503).json({ok,status:ok?'healthy':'not_ready',version:BUILD_VERSION,requestId:req.requestId,database:{configured:dbReady,reachable:mysqlOk},runtimeGate:RUNTIME_GATE.snapshot()});
  }catch(e){res.status(503).json({ok:false,status:'not_ready',version:BUILD_VERSION,requestId:req.requestId,database:{configured:Boolean(mysqlPool),reachable:false},error:'DATABASE_UNAVAILABLE'});}
});
app.get('/livez',(req,res)=>{
  const ok=!fatalRuntimeFault;
  res.status(ok?200:503).json({ok,status:ok?'live':'failed',version:BUILD_VERSION,requestId:req.requestId,recoveryRequired:Boolean(MYSQL_RECOVERY_REQUIRED)});
});
app.get('/readyz',async(req,res)=>{
  let mysqlOk=false;
  try{if(mysqlPool){await mysqlPool.query('SELECT 1');mysqlOk=true;}}catch{}
  const configured=Boolean(process.env.DB_HOST&&process.env.DB_USER&&process.env.DB_NAME);
  const ready=!fatalRuntimeFault && (mysqlOk || !configured);
  res.status(ready?200:503).json({ok:ready,status:ready?'ready':'not_ready',version:BUILD_VERSION,requestId:req.requestId,database:{configured,reachable:mysqlOk},recoveryRequired:Boolean(MYSQL_RECOVERY_REQUIRED),writeProtection:Boolean(MYSQL_RECOVERY_REQUIRED),writePrerequisitesReported:Boolean(!SBC_RUNTIME_READ_ONLY&&sbcWriterLeaseReady&&MYSQL_RECOVERY_EVALUATED&&!MYSQL_RECOVERY_REQUIRED&&mysqlOk)});
});

