app.post('/api/crm/leads/transition-pipeline',auth,async(req,res)=>{
  try{
    const spec=V562_NEXT.optimisticTransitionSpec({leadId:req.body?.id,targetState:req.body?.target_state});
    const lead=(db.customers||[]).find(c=>String(c.id)===spec.leadId);
    if(!lead)return res.status(404).json({ok:false,error:'Lead not found.'});
    const previousState=String(lead.status||'');
    lead.status=spec.targetState;
    lead.updatedAt=now();
    addActivity('pipeline_transition',`Pipeline moved ${lead.businessName||lead.id}: ${previousState||'Unknown'} → ${spec.targetState}`,{customerId:lead.id,previousState,targetState:spec.targetState,operationId:spec.operationId,actorId:req.user.id});
    await saveData();
    V562_NEXT.publish('lead.pipeline.transitioned',{leadId:lead.id,previousState,targetState:spec.targetState,operationId:spec.operationId});
    res.json({ok:true,...spec,previousState,currentState:spec.targetState});
  }catch(e){res.status(400).json({ok:false,error:e.message});}
});

