app.post('/api/v562/tier1/lead-bulk/preview',auth,(req,res)=>{
  if(!['owner','manager','lead_researcher'].includes(String(req.user?.role||'')) && !isLornaLeadAccount(req.user)) return res.status(403).json({ok:false,error:'Lead intake access required.'});
  try{
    const raw=Buffer.from(String(req.body?.csvBase64||''),'base64');
    const rows=TIER1_V562.parseCsvBinary(raw,{maxBytes:25*1024*1024,maxRows:250000});
    const batchId=req.body?.batchId||TIER1_V562.createBatchId(req.body?.source||'Lorna');
    const out=TIER1_V562.normalizeLeadRows(rows,{batchId,source:req.body?.source||'Lorna'});
    res.json({ok:true,version:BUILD_VERSION,batchId,counts:out.counts,preview:out.leads.slice(0,25)});
  }catch(e){res.status(400).json({ok:false,error:e.message});}
});

app.post('/api/v562/tier1/lead-bulk/ingest',auth,async(req,res)=>{
  if(!['owner','manager','lead_researcher'].includes(String(req.user?.role||'')) && !isLornaLeadAccount(req.user)) return res.status(403).json({ok:false,error:'Lorna lead intake access required.'});
  try{
    const csvBase64=String(req.body?.csvBase64||'');
    if(!csvBase64)return res.status(400).json({ok:false,error:'csvBase64 is required.'});
    const batchId=req.body?.batchId||TIER1_V562.createBatchId(req.body?.source||'Lorna');
    const key=TIER1_V562.idempotencyKey('lead-bulk-ingest',{batchId,sha256:TIER1_V562.idempotencyKey('payload',csvBase64)});
    const durable=typeof V462_INFRA!=='undefined' ? await V462_INFRA.publishEvent('lead.bulk.ingest.requested',{batchId,source:req.body?.source||'Lorna',requestedBy:req.user.id},{idempotencyKey:key}) : null;
    if(durable?.duplicate)return res.status(200).json({ok:true,duplicate:true,batchId,idempotencyKey:key,eventId:durable.eventId});
    const worker=await TIER1_V562.spawnWorker({workerPath:path.join(__dirname,'workers','tier1-bulk-ingest.js'),payload:{csvBase64,batchId,source:req.body?.source||'Lorna'},timeoutMs:120000});
    if(!worker.ok)throw new Error(worker.error||'Bulk ingestion worker failed.');
    TIER1_V562.publish('lead.bulk.ingested',{batchId,counts:worker.counts,tenantId:requireRequestTenant(req)});
    res.status(202).json({ok:true,version:BUILD_VERSION,batchId,idempotencyKey:key,eventId:durable?.eventId||null,counts:worker.counts,leads:worker.rows});
  }catch(e){res.status(400).json({ok:false,error:e.message});}
});

app.get('/api/v562/tier1/events',auth,(req,res)=>{
  res.status(200);res.setHeader('Content-Type','text/event-stream');res.setHeader('Cache-Control','no-cache, no-transform');res.setHeader('Connection','keep-alive');res.flushHeaders?.();
  const send=(evt)=>{try{res.write(`id: ${evt.id}\nevent: ${evt.topic}\ndata: ${JSON.stringify(evt.payload||{})}\n\n`);}catch{}}
  const unsubscribe=TIER1_V562.subscribe(send);send({id:crypto.randomUUID(),topic:'tier1.connected',payload:{version:BUILD_VERSION,at:new Date().toISOString()}});
  const keep=setInterval(()=>{try{res.write(': keep-alive\n\n')}catch{}},25000);
  req.on('close',()=>{clearInterval(keep);unsubscribe();});
});

