app.get('/api/v56/next-best-action',auth,(req,res)=>{
  try{
    const scan=V56_AUTONOMY.scan(db);
    const customers=(db.customers||[]).filter(c=>!['Customer','Lost','Do Not Call','Closed','Duplicate','Not Qualified','DNC'].includes(String(c.status||'')));
    const ranked=customers.map(c=>({...c,_score:Number(c.opportunityScore||0)+(String(c.leadTemperature||'').toLowerCase()==='hot'?25:String(c.leadTemperature||'').toLowerCase()==='warm'?10:0)})).sort((a,b)=>b._score-a._score);
    let action={type:'pipeline',priority:'MEDIUM',title:'Keep the sales engine moving',detail:'Review verified opportunities and follow-ups before increasing lead volume.',target:'crm'};
    if(scan.money?.paidWaiting) action={type:'fulfillment',priority:'HIGH',title:'Move paid work',detail:`${scan.money.paidWaiting} paid order${scan.money.paidWaiting===1?'':'s'} need fulfillment movement.`,target:'orders'};
    else if(scan.money?.staleHot) action={type:'sales',priority:'HIGH',title:'Work stale hot opportunities',detail:`${scan.money.staleHot} hot opportunity${scan.money.staleHot===1?'':'ies'} have gone untouched for more than four hours.`,target:'crm'};
    else if(scan.capacity?.underloaded) action={type:'growth',priority:'MEDIUM',title:'Feed the pipeline',detail:`Only ${scan.capacity.ready} ready opportunities remain against ${scan.capacity.dailyCapacity}/day capacity. Increase targeted sourcing.`,target:'leadimport'};
    else if(ranked[0]) action={type:'sales',priority:'MEDIUM',title:`Work ${ranked[0].businessName||'the top opportunity'}`,detail:`Opportunity score ${ranked[0]._score}/100${ranked[0].dealValue?' · potential '+Number(ranked[0].dealValue).toLocaleString('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}):''}.`,target:'crm'};
    res.json({ok:true,version:BUILD_VERSION,action,topOpportunities:ranked.slice(0,5).map(c=>({id:c.id,businessName:c.businessName,score:c._score,temperature:c.leadTemperature,dealValue:c.dealValue}))});
  }catch(e){res.status(500).json({ok:false,version:BUILD_VERSION,error:e.message});}
});

