function orderParsed(o){if(!o)return {}; if(o.parsed&&typeof o.parsed==='object')return o.parsed; try{return o.notes&&String(o.notes).trim().startsWith('{')?JSON.parse(o.notes):{}}catch{return {}}}
function updateOrderParsed(o,patch){const parsed=orderParsed(o);Object.assign(parsed,patch);o.notes=JSON.stringify(parsed);o.updatedAt=now();return parsed}
