async function sendOrderIntake(order,baseOverride=''){const c=(db.customers||[]).find(x=>x.id===order.customerId)||{businessName:order.customerName,email:'',phone:''};const url=customerIntakeUrl(order,baseOverride);if(!url)return {sent:false,reason:'SBC_PUBLIC_URL is not configured.'};const t=intakeTemplateForOrder(order);const results=[];if(c.email){try{await sendEmail(c,t.subject,t.body.replace('{{intake_url}}',url));results.push('email')}catch(e){results.push(`email_failed:${e.message}`)}}if(c.phone){try{await sendSms(c,t.body.replace('{{intake_url}}',url));results.push('sms')}catch(e){results.push(`sms_failed:${e.message}`)}}const delivered=results.some(x=>x==='email'||x==='sms');
  const failureResults=results.filter(x=>x.includes('_failed:'));
  if(!delivered && failureResults.length){
    const marker=`Customer intake delivery failed for SBC order ${order.id}`;
    if(!db.tasks.some(t=>String(t.type||'').toLowerCase()==='customer intake'&&String(t.notes||'').includes(order.id)&&t.status!=='Completed')){
      db.tasks.unshift({id:id('task'),customerId:order.customerId||'',customerName:order.customerName||'',title:`Customer Intake — ${order.product||order.id}`,dueAt:now(),type:'Customer Intake',priority:'High',status:'Open',notes:`${marker}. Channels attempted: ${failureResults.join(' | ')}. Manual customer contact required.`,assignedTo:'',assignedToName:'Sales / Customer Intake',createdBy:'square-webhook',createdAt:now(),updatedAt:now()});
    }
  }
  updateOrderParsed(order,{customerIntakeUrl:url,customerIntakeSentAt:delivered?now():'',customerIntakeChannels:results,customerIntakeDeliveryStatus:delivered?'DELIVERED':'BLOCKED_REQUIRES_HUMAN'});
  return {sent:delivered,url,channels:results,deliveryStatus:delivered?'DELIVERED':'BLOCKED_REQUIRES_HUMAN'};}
async function createSquarePaymentLinkForOrder(o,req){
  if(RUNTIME_GATE.blocked('NEW_CHECKOUTS')){const e=new Error('NEW_CHECKOUTS_PAUSED_BY_OWNER');e.status=423;throw e;}
  if(!o) throw new Error('Order not found.');
  if(Number(o.price||0)<=0) throw new Error('Order total must be greater than $0.');
  if(o.squarePaymentLink?.url || orderParsed(o).squarePaymentLinkUrl) return {existing:true,url:o.squarePaymentLink?.url||orderParsed(o).squarePaymentLinkUrl,order:o};
  if(o.checkoutLinkStatus==='RECONCILIATION_REQUIRED'||orderParsed(o).checkoutLinkStatus==='RECONCILIATION_REQUIRED'){
    const e=Error('SQUARE_PAYMENT_LINK_RECONCILIATION_REQUIRED');e.status=409;throw e;
  }
  const cust=db.customers.find(c=>c.id===o.customerId);
  if(!o.tenantId) throw new Error('TENANT_CONTEXT_REQUIRED');
  const economicItems=(()=>{try{const p=JSON.parse(o.notes||'{}');return Array.isArray(p.items)&&p.items.length?p.items:[{id:String(o.product||'unknown'),name:String(o.product||'Order'),qty:1,unitPrice:Number(o.price||0)}];}catch{return [{id:String(o.product||'unknown'),name:String(o.product||'Order'),qty:1,unitPrice:Number(o.price||0)}]}})();
  const econ=await FINANCIAL_GOVERNOR.evaluate({tenantId:o.tenantId,action:'square_payment_link',resourceId:o.id,items:economicItems,price:Number(o.price||0),idempotencyKey:`square-link:${o.id}`,request:{path:'/square/payment-link',agentKey:req?.user?.agentKey||'API'}});
  if(econ.status!=='ALLOWED'){const e=new Error(econ.reason||'GOVERNOR_HOLD');e.status=423;e.holdId=econ.holdId;throw e;}
  const parsed=orderParsed(o);
  const requestBody={idempotency_key:'',description:`SBC ${o.id} payment for ${o.customerName||cust?.businessName||'Customer'}`.slice(0,4096),payment_note:`SBC Order ${o.id}`.slice(0,500),order:{location_id:String(process.env.SQUARE_LOCATION_ID),reference_id:String(o.id),line_items:[squareOrderLineItem(o)]},checkout_options:{allow_tipping:false,redirect_url:String(process.env.SQUARE_SUCCESS_REDIRECT_URL||`${String(process.env.SBC_PUBLIC_URL||'').replace(/\/$/,'')}/payment-success?order=${encodeURIComponent(o.id)}`)}};
  const pre={}; if(cust?.email)pre.buyer_email=String(cust.email).slice(0,256); const phone=normalizeBuyerPhone(cust?.phone); if(phone)pre.buyer_phone_number=phone; if(Object.keys(pre).length)requestBody.pre_populated_data=pre;
  // Reusing an order-scoped key prevents another Square link on retry after an uncertain response.
  requestBody.idempotency_key=SBC_SQUARE_SAFETY.linkIdempotencyKey({tenantId:o.tenantId,orderId:o.id,environment:squareEnvironment(),locationId:process.env.SQUARE_LOCATION_ID,amountCents:squareMoneyCents(o.price)});
  const j=await squareApi('/v2/online-checkout/payment-links',{method:'POST',body:requestBody});
  const pl=j.payment_link||{}; if(!pl.id||!pl.url||!pl.order_id)throw new Error('Square did not return a complete payment link.');
  const record={id:id('sqpay'),sbcOrderId:o.id,squarePaymentLinkId:pl.id,squareOrderId:pl.order_id,squarePaymentId:'',paymentUrl:pl.url,longUrl:pl.long_url||'',amount:Number(o.price||0),currency:'USD',status:'PENDING',customerId:o.customerId||'',customerName:o.customerName||'',createdAt:now(),updatedAt:now(),completedAt:'',createdBy:req.user?.id||'',createdByName:req.user?.name||''};
  squarePaymentRecords().unshift(record); squarePaymentRecords().splice(5000);
  updateOrderParsed(o,{squarePaymentLinkId:pl.id,squareOrderId:pl.order_id,squarePaymentLinkUrl:pl.url,squarePaymentStatus:'PENDING',squarePaymentCreatedAt:now(),squarePaymentEnvironment:squareEnvironment()});
  o.paymentUrl=pl.url; o.paymentStatus='Pending'; o.fulfillmentStatus='Awaiting Customer Payment';
  addActivity('payment_link',`Generated Square payment link for ${o.id}`,{orderId:o.id,squareOrderId:pl.order_id,squarePaymentLinkId:pl.id,amount:o.price});
  await saveData();
  return {existing:false,url:pl.url,longUrl:pl.long_url||'',paymentLinkId:pl.id,squareOrderId:pl.order_id,order:o};
}
function squareSignatureValid(rawBody,signature){
  const key=String(process.env.SQUARE_WEBHOOK_SIGNATURE_KEY||'');
  const url=String(process.env.SQUARE_WEBHOOK_URL||'').trim() || squareWebhookUrl();
  if(!key||!url||!signature)return false;
  const raw=Buffer.isBuffer(rawBody)?rawBody:Buffer.from(String(rawBody||''),'utf8');
  const expected=crypto.createHmac('sha256',key).update(url).update(raw).digest('base64');
  const supplied=Buffer.from(String(signature).trim(),'utf8');
  const wanted=Buffer.from(expected,'utf8');
  return supplied.length===wanted.length && supplied.length>0 && crypto.timingSafeEqual(supplied,wanted);
}

async function sendBig3OfficeBoxHandoff(order, {reason='paid-order', force=false}={}) {
  const base=String(process.env.SBC_OFFICE_BOX_URL||'').replace(/\/$/,'');
  const secret=String(process.env.SBC_WEBHOOK_SECRET||'');
  if(!base || !secret) return {ok:false,configured:false,reason:!base?'SBC_OFFICE_BOX_URL_NOT_CONFIGURED':'SBC_WEBHOOK_SECRET_NOT_CONFIGURED'};
  const customer=(db.customers||[]).find(c=>String(c.id)===String(order?.customerId))||{};
  const ent=BIG3.entitlementFor(order?.product);
  if(ent.officeBox!=='included' && !force) return {ok:true,configured:true,skipped:true,reason:'OFFICE_BOX_NOT_INCLUDED'};
  const token=crypto.randomBytes(32).toString('base64url');
  const payload=BIG3.buildHandoff({order,customer,packageName:order?.product,activationToken:token,sourceVersion:BUILD_VERSION});
  payload.reason=reason;
  const signature=BIG3.sign(payload,secret);
  try{
    const r=await fetch(`${base}/api/integrations/sbc/handoff`,{method:'POST',headers:{'content-type':'application/json','x-sbc-signature':signature,'x-sbc-event':'order.paid','x-sbc-idempotency-key':payload.idempotencyKey},body:JSON.stringify(payload),signal:AbortSignal.timeout(10000)});
    const body=await r.json().catch(()=>({}));
    if(r.ok){
      const activationUrl=String(body.activation_url||'');
      const expiresAt=String(body.expires_at||body.activation_expires_at||'');
      updateOrderParsed(order,{officeBoxHandoffId:body.handoff_id||'',officeBoxHandoffStatus:body.status||'',officeBoxActivationUrl:activationUrl,officeBoxActivationExpiresAt:expiresAt,officeBoxHandoffAt:now(),officeBoxHandoffReason:reason});
      const c=(db.customers||[]).find(x=>String(x.id)===String(order?.customerId));
      if(activationUrl && c?.email && !orderParsed(order).officeBoxActivationSentAt){
        const subject='Your SBC Office Box is ready to activate';
        const bodyText=`Hi ${c.contactName||c.name||'there'},\n\nYour SBC Office Box workspace is ready for secure activation.\n\nActivate your workspace here: ${activationUrl}\n\nThe activation link expires in 72 hours and can be used once. You will create your own password during activation. SBC will never send you a password by email.\n\nIf you need help, reply to this message or contact SBC.\n\nSuccessful By Choice\nBecause Why Not?`;
        try{await sendEmail(c,subject,bodyText);updateOrderParsed(order,{officeBoxActivationSentAt:now(),officeBoxActivationChannel:'email'});}catch(e){addActivity('office_box_activation_email_error',`Office Box activation email failed for ${order.id}: ${e.message}`,{orderId:order.id});}
      }
    }
    return {ok:r.ok,configured:true,status:r.status,response:body};
  }catch(e){return {ok:false,configured:true,reason:'OFFICE_BOX_UNREACHABLE',error:e.message};}
}

async function handleSquarePaymentEvent(event,baseOverride=''){
  const payment=event?.data?.object?.payment||event?.data?.object||{};
  const squarePaymentId=String(payment.id||''); const squareOrderId=String(payment.order_id||''); const status=String(payment.status||'').toUpperCase();
  if(!squarePaymentId && !squareOrderId)return {ignored:true,reason:'No payment/order id'};
  const paymentAmountCents=Number(payment.amount_money?.amount||0);
  const records=squarePaymentRecords();
  let rec=records.find(x=>(squarePaymentId&&x.squarePaymentId===squarePaymentId)||(squareOrderId&&x.squareOrderId===squareOrderId));
  let order=rec?db.orders.find(x=>x.id===rec.sbcOrderId):null;
  if(!order&&squareOrderId)order=(db.orders||[]).find(x=>orderParsed(x).squareOrderId===squareOrderId);
  if(!order)return {ignored:true,reason:'No matching SBC order',squareOrderId,squarePaymentId};
  // Validate Square order, location, payment ID, amount and currency before modifying anything.
  if(status==='COMPLETED'){
    const proof=SBC_V6659_SQUARE_PROOF.validateCompleted(payment,order,orderParsed(order),rec,process.env.SQUARE_LOCATION_ID);
    if(!proof.ok)return {ok:false,orderId:order.id,status:'RECONCILIATION_REQUIRED',code:proof.code};
  }
  // Refuse out-of-order PENDING/FAILED/CANCELED events that could undo recorded capture.
  if(status!=='COMPLETED' && SBC_V6659_SQUARE_PROOF.storedOrderCapture(orderParsed(order)))
    return {ignored:true,reason:'STALE_NONCOMPLETED_EVENT_AFTER_CAPTURE',orderId:order.id};
  if(!rec){rec={id:id('sqpay'),sbcOrderId:order.id,squarePaymentLinkId:orderParsed(order).squarePaymentLinkId||'',squareOrderId,paymentUrl:orderParsed(order).squarePaymentLinkUrl||order.paymentUrl||'',amount:Number(order.price||0),currency:'USD',status:'UNKNOWN',createdAt:now(),updatedAt:now(),squarePaymentId:'',customerId:order.customerId||'',customerName:order.customerName||''};records.unshift(rec)}
  rec.squarePaymentId=squarePaymentId||rec.squarePaymentId; rec.status=status||rec.status; rec.updatedAt=now();
  if(status==='COMPLETED'){
    const expectedAmountCents=squareMoneyCents(order.price);
    if(expectedAmountCents<=0||paymentAmountCents!==expectedAmountCents||String(payment.amount_money?.currency||'').toUpperCase()!=='USD'){
      rec.status='AMOUNT_MISMATCH';rec.lastError=`Square amount ${paymentAmountCents} did not match SBC order ${expectedAmountCents}`;rec.updatedAt=now();await saveData();
      addActivity('payment_amount_mismatch',`Square payment amount did not match SBC order ${order.id}`,{orderId:order.id,squarePaymentId,squareOrderId,paymentAmountCents,expectedAmountCents});
      return {ok:false,orderId:order.id,status:'AMOUNT_MISMATCH',squarePaymentId,expectedAmountCents,paymentAmountCents};
    }
    const alreadyPaid=SBC_V6659_SQUARE_PROOF.persistedCompletion(orderParsed(order),payment);
    const sbcLaunchQaDurable=Number(order.price)===1&&
      String(order.product||'')==='SBC Launch QA - $1 Test Service'&&
      orderParsed(order).sbcLaunchQa?.kind==='OWNER_ONLY_ONE_DOLLAR_CHECKOUT'&&
      orderParsed(order).sbcLaunchQa?.version===1&&
      Array.isArray(orderParsed(order).items)&&
      orderParsed(order).items.some(line=>String(line?.sku||'')==='SBC_LAUNCH_QA_1USD');
    rec.status='PAID';rec.completedAt=rec.completedAt||now();order.paymentStatus='Paid';order.status='Paid';
    if(!sbcLaunchQaDurable)order.fulfillmentStatus='Ready for Fulfillment';
    else if(!String(order.fulfillmentStatus||'').startsWith('QA '))
      order.fulfillmentStatus='QA - NO VENDOR FULFILLMENT';
    if(alreadyPaid){
      rec.duplicateCompletedAt=rec.duplicateCompletedAt||now();
      records.splice(5000); await saveData();
      return {ok:true,orderId:order.id,status:'PAID',squarePaymentId:rec.squarePaymentId,duplicate:true};
    }
    updateOrderParsed(order,{squarePaymentStatus:'PAID',squarePaymentId:rec.squarePaymentId,squarePaymentCompletedAt:rec.completedAt,fulfillmentStatus:'Ready for Fulfillment'});
    addActivity('payment_received',`Square payment received for ${order.id}`,{orderId:order.id,squareOrderId:rec.squareOrderId,squarePaymentId:rec.squarePaymentId,amount:order.price});
    // SBC_V6693_OFFICE_BOX_LEGACY_PRECOMMIT_QUARANTINE: explicit Office Box sales require dedicated POST-COMMIT V2 flow.
    const sbcOfficeBoxExplicitPurchase=(()=>{
      const notes=orderParsed(order);
      const lines=Array.isArray(notes.items)?notes.items:[];
      const hasLine=lines.some(line=>/^OFFICE_BOX(?:_|$)/i.test(String(line?.sku||'')));
      const hasMeta=/^OFFICE_BOX(?:_|$)/i.test(String(notes.officeBoxSku||order.officeBoxSku||''));
      const hasName=/office[ _-]*box/i.test(String(order.product||'')+' '+String(notes.bundleId||''));
      return hasLine||hasMeta||hasName;
    })();
    const sbcLaunchQaExplicitPurchase=sbcLaunchQaDurable;
    if(!sbcOfficeBoxExplicitPurchase&&!sbcLaunchQaExplicitPurchase){
    try{await REVENUE_AUTOPILOT_V56150.recordFunnelEvent('payment_completed',order.customerId,{tenantId:order.tenantId||TENANT_DEFAULT_ID,orderId:order.id,amount:Number(order.price||0),idempotencyKey:`payment_completed:${order.id}`});}catch(e){}
    const c=db.customers.find(x=>x.id===order.customerId);if(c){c.status='Customer';c.updatedAt=now();ensureProjectForCustomer(c,orderParsed(order).bundleId||'',orderParsed(order).bundleName||order.product);}
    // V60.2 Commercial OS: successful paid orders create/replay a commercial tenant idempotently.
    try{
      const bundle=String(orderParsed(order).bundleId||'').toLowerCase();
      const planId=bundle.includes('growth')?'growth':bundle.includes('professional')?'professional':bundle.includes('essentials')?'essentials':bundle.includes('starter')?'starter':'quickstart';
      const commercialTenant=await SBC_COMMERCIAL.provisionTenant({businessName:String(c?.businessName||order.customerName||'SBC Customer'),planId,idempotencyKey:`square-paid-order:${order.id}`,metadata:{source:'square-payment',orderId:order.id,customerId:order.customerId||'',squarePaymentId:rec.squarePaymentId}});
      updateOrderParsed(order,{commercialTenantId:commercialTenant.tenantId,commercialPlanId:commercialTenant.planId});
      try{await SBC_COMMERCIAL.recordUsage({tenantId:commercialTenant.tenantId,eventType:'SETUP_REVENUE',amountCents:Math.round(Number(order.price||0)*100),metadata:{orderId:order.id,squarePaymentId:rec.squarePaymentId},eventId:`commercial-payment:${order.id}`});}catch(_){ }
    }catch(e){addActivity('commercial_tenant_provision_error',`Commercial tenant provisioning deferred for ${order.id}: ${e.message}`,{orderId:order.id});}

    try{const tenantId=Number(order.tenantId||c?.tenantId||TENANT_DEFAULT_ID);const brand=orderParsed(order).brandProfile||c?.brandProfile||{};const storefront=V569_PRODUCTION_EXPANSION.provisionStorefront({tenantId,customer:c||{},order,brand,template:brand.template||orderParsed(order).storefrontTemplate||'print-reseller'});addActivity('tenant_storefront_provisioned',`Generated branded storefront for ${order.customerName||order.id}`,{orderId:order.id,tenantId,file:storefront.file,template:storefront.profile.template});}catch(e){addActivity('tenant_storefront_provision_error',`Branded storefront generation did not complete for ${order.id}: ${e.message}`,{orderId:order.id});}
    ensureCommissionForSale({...order,orderId:order.id,total:order.price,paidAt:rec.completedAt,items:orderParsed(order).items||[],salesRepId:order.salesRepId||orderParsed(order).salesRepId||''});
    if(!db.tasks.some(t=>t.type==='Fulfillment'&&t.customerId===order.customerId&&String(t.notes||'').includes(`SBC order ${order.id}`)&&t.status!=='Completed')){const task={id:id('task'),customerId:order.customerId||'',customerName:order.customerName||'',title:`Fulfillment — ${order.product||order.id}`,dueAt:now(),type:'Fulfillment',priority:'High',status:'Open',notes:`Paid via Square. SBC order ${order.id}. Square payment ${rec.squarePaymentId}.`,assignedTo:'',assignedToName:'Fulfillment',createdBy:'square-webhook',createdAt:now(),updatedAt:now()};db.tasks.unshift(task);}
    try{await GOD_KIM.orchestrate({order,requestUser:{id:'square-webhook',name:'GodKim / Square'},createFulfillmentJobsForOrder,processReadyFulfillmentJobs,vendorCapabilities,addActivity,audit,saveData,db,catalog:CATALOG,sendCustomerStatus:async(order,msg)=>{const c=(db.customers||[]).find(x=>x.id===order.customerId);if(c&&c.email)return sendEmail(c,msg.subject,msg.body);return {sent:false};},testMode:false});}catch(e){addActivity('fulfillment_automation_error',`GodKim orchestration could not start for ${order.id}: ${e.message}`,{orderId:order.id});}
    try{const handoff=await sendBig3OfficeBoxHandoff(order,{reason:'square-payment-completed'});addActivity('big3_office_box_handoff',handoff.ok?`Office Box handoff ${handoff.skipped?'skipped':'sent'} for ${order.id}`:`Office Box handoff not completed for ${order.id}`,{orderId:order.id,officeBox:handoff});}catch(e){addActivity('big3_office_box_handoff_error',`Office Box handoff failed for ${order.id}: ${e.message}`,{orderId:order.id})}
    if(!orderParsed(order).customerIntakeSentAt){try{await sendOrderIntake(order,baseOverride)}catch(e){addActivity('intake_error',`Customer intake could not be sent for ${order.id}: ${e.message}`,{orderId:order.id})}}
    }else if(sbcLaunchQaExplicitPurchase){
      order.fulfillmentStatus='QA VERIFIED - NO FULFILLMENT';
      updateOrderParsed(order,{fulfillmentStatus:'QA VERIFIED - NO FULFILLMENT',sbcLaunchQaPaidVerified:true});
      addActivity('launch_qa_payment_verified','$1 launch QA Square capture verified; vendor actions held for '+order.id,
        {orderId:order.id,paymentId:rec.squarePaymentId,amountCents:100,source:'SQUARE_CAPTURE'});
    }else{
      addActivity('office_box_precommit_fulfillment_quarantined',
        'Office Box paid capture saved; generic fulfillment and legacy invitation held for '+order.id,
        {orderId:order.id,reason:'OFFICE_BOX_V2_COMMITTED_MYSQL_PROVIDER_PROOF_REQUIRED'});
    }
  } else if(status==='CANCELED'||status==='FAILED'){
    rec.status=status;order.paymentStatus=status==='FAILED'?'Failed':'Canceled';order.fulfillmentStatus='Payment Required';updateOrderParsed(order,{squarePaymentStatus:rec.status});
    if(status==='FAILED'){
      try{await REVENUE_AUTOPILOT_V56150.recordFunnelEvent('payment_failed',order.customerId,{tenantId:order.tenantId||TENANT_DEFAULT_ID,orderId:order.id,amount:Number(order.price||0),idempotencyKey:`payment_failed:${order.id}:${event.event_id||squarePaymentId}`});}catch(e){}
      const c=(db.customers||[]).find(x=>String(x.id)===String(order.customerId));
      try{
        const recovery=V566_RAILS.subscriptionRecovery({status:'PAYMENT_FAILED',customer_id:order.customerId,customer_email:c?.email||'',amount:Number(order.price||0),event_id:event.event_id||squarePaymentId});
        if(recovery.eligible){const durable=V562NEXT.billingFriction({status:'payment_failed',client_id:order.customerId,client_email:c?.email||'',amount:Number(order.price||0),invoice_id:event.event_id||squarePaymentId});addActivity('subscription_recovery_queued',`Payment recovery queued for ${order.customerName||order.id}`,{orderId:order.id,recovery,durable});}
      }catch(e){addActivity('subscription_recovery_error',`Payment recovery could not be queued for ${order.id}: ${e.message}`,{orderId:order.id});}
    }
  } else if(status){order.paymentStatus=status;updateOrderParsed(order,{squarePaymentStatus:status});}
  records.splice(5000); await saveData(); return {ok:true,orderId:order.id,status:rec.status,squarePaymentId:rec.squarePaymentId};
}

