    { const [vcols]=await mysqlPool.query('SELECT COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=?',['sbc_fulfillment_jobs']); const vnames=new Set((vcols||[]).map(x=>String(x.COLUMN_NAME||''))); if(!vnames.has('value')) { await mysqlPool.query('ALTER TABLE sbc_fulfillment_jobs ADD COLUMN value DECIMAL(12,2) NOT NULL DEFAULT 0 AFTER cost'); await mysqlPool.query('UPDATE sbc_fulfillment_jobs j JOIN sbc_orders o ON o.id=j.order_id SET j.value=o.price WHERE j.value=0 AND o.price>0'); } }
