// ===== V30.3 ENTERPRISE ARCHITECTURE FOUNDATION =====
// Memory is a working cache; MySQL/outbox is the source of truth. Optional external
// infrastructure (RabbitMQ, read replica, telemetry sink) is activated only when configured.
function ensureTenantDefaults(){
  const collections=['users','customers','quotes','orders','renewals','activities','callReports','callLogs','appointments','sequences','sequenceEnrollments','emailTemplates','tasks','customerAccounts','customerMessages'];
  for(const k of collections){for(const x of (db[k]||[])){if(x.tenantId==null&&x.tenant_id!=null)x.tenantId=__sbcRequireTenantId(x.tenant_id);}}
  // Tenant assignment for legacy rows is a migration task, not a runtime fallback.
}
function tenantIdForUser(u){return __sbcRequireTenantId(u?.tenantId)}
function tenantOwns(req,record){if(!record)return true;const tenant=requireRequestTenant(req);if(record.tenantId==null)return false;return Number(record.tenantId)===tenant}
function tenantFilter(req,rows){return (rows||[]).filter(x=>tenantOwns(req,x))}
function setTenant(req,res,next){req.tenantId=tenantIdForUser(req.user);next()}

// AES-256-GCM vault for sensitive application secrets that legitimately need database persistence.
// V55.23: do NOT require another GoDaddy environment slot. Preserve an existing
// SBC_VAULT_KEY when present; otherwise derive a stable vault key from the existing
// SBC portal secret. The derived key is never returned to clients or written to logs.
function vaultKeySource(){
  if(String(process.env.SBC_VAULT_KEY||'').trim()) return 'SBC_VAULT_KEY';
  if(String(PORTAL_SECRET||'').trim()) return 'SBC_PORTAL_SECRET_DERIVED';
  throw new Error('No stable server-side vault key source is available.');
}
function vaultKey(){
  const raw=String(process.env.SBC_VAULT_KEY||'').trim() || String(PORTAL_SECRET||'').trim();
  if(!raw)throw new Error('No stable server-side vault key source is available.');
  return crypto.createHash('sha256').update(`sbc-provider-vault:v2:${raw}`).digest();
}
function encryptVault(plaintext){
  const iv=crypto.randomBytes(12),cipher=crypto.createCipheriv('aes-256-gcm',vaultKey(),iv);const enc=Buffer.concat([cipher.update(String(plaintext),'utf8'),cipher.final()]);
  return `v1.${iv.toString('base64url')}.${cipher.getAuthTag().toString('base64url')}.${enc.toString('base64url')}`;
}
function decryptVault(blob){
  const [v,ivS,tagS,dataS]=String(blob||'').split('.');if(v!=='v1')throw new Error('Unsupported vault format');
  const decipher=crypto.createDecipheriv('aes-256-gcm',vaultKey(),Buffer.from(ivS,'base64url'));decipher.setAuthTag(Buffer.from(tagS,'base64url'));return Buffer.concat([decipher.update(Buffer.from(dataS,'base64url')),decipher.final()]).toString('utf8');
}
async function vaultSecret(name,tenantId=TENANT_DEFAULT_ID){
  if(!mysqlPool)return '';
  const [rows]=await mysqlPool.query('SELECT secret_ciphertext FROM sbc_secret_vault WHERE tenant_id=? AND secret_name=? ORDER BY updated_at DESC LIMIT 1',[tenantId,String(name)]);
  if(!rows[0]?.secret_ciphertext)return '';
  return decryptVault(rows[0].secret_ciphertext);
}
async function credentialSecret(name,envNames=[]){
  try{const v=await vaultSecret(name);if(v)return v;}catch(e){console.warn('[SBC VAULT] read:',e.message)}
  for(const k of envNames){if(process.env[k])return process.env[k]}
  return '';
}


const secretCache=new Map();
async function loadVaultSecrets(){if(!mysqlPool)return;try{const [rows]=await mysqlPool.query('SELECT secret_name,secret_ciphertext FROM sbc_secret_vault WHERE tenant_id=?',[TENANT_DEFAULT_ID]);for(const r of rows){try{secretCache.set(r.secret_name,decryptVault(r.secret_ciphertext))}catch(e){console.warn('[SBC VAULT] decrypt failed for',r.secret_name)}}}catch(e){console.warn('[SBC VAULT] load:',e.message)}}
function secretValue(name,...fallbackNames){if(secretCache.has(name))return secretCache.get(name);for(const n of fallbackNames){if(process.env[n])return process.env[n]}return ''}
async function vaultBootstrapFromEnvironment(){
  if(!mysqlPool||process.env.SBC_VAULT_BOOTSTRAP!=='true')return;
  try{
    vaultKey();
    const names=['SBC_TWILIO_AUTH_TOKEN','TWILIO_AUTH_TOKEN','TWILIO_API_KEY_SECRET','GODADDY_PAT'];
    for(const name of names){
      const value=process.env[name];
      if(!value)continue;
      await mysqlPool.query(`INSERT INTO sbc_secret_vault(id,tenant_id,secret_name,secret_ciphertext,created_at,updated_at) VALUES (?,?,?,?,UTC_TIMESTAMP(),UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE secret_ciphertext=VALUES(secret_ciphertext),updated_at=UTC_TIMESTAMP()`,[id('vault'),TENANT_DEFAULT_ID,name,encryptVault(value)]);
      secretCache.set(name,value);
    }
    console.log(`[SBC VAULT] credential bootstrap complete using ${vaultKeySource()}; no additional hosting secret required.`);
  }catch(e){console.warn('[SBC VAULT] bootstrap skipped:',e.message)}
}

// Minimal JWT/JWKS support using Node crypto. Existing durable cookie sessions remain the default
// until SBC_AUTH_MODE=jwt is explicitly enabled, so this upgrade is reversible.
function jwtKeys(){
  const priv=process.env.SBC_JWT_PRIVATE_KEY,pub=process.env.SBC_JWT_PUBLIC_KEY;
  if(priv&&pub)return {privateKey:priv,publicKey:pub,kid:crypto.createHash('sha256').update(pub).digest('hex').slice(0,16)};
  return null;
}
function jwtSign(payload){const keys=jwtKeys();if(!keys)return null;const head=b64u(JSON.stringify({alg:'RS256',typ:'JWT',kid:keys.kid})),body=b64u(JSON.stringify(payload));const sig=crypto.sign('RSA-SHA256',Buffer.from(`${head}.${body}`),keys.privateKey).toString('base64url');return `${head}.${body}.${sig}`;}
function jwtVerify(token){const keys=jwtKeys();if(!keys)return null;try{const [h,p,s]=String(token||'').split('.');if(!h||!p||!s)return null;const header=JSON.parse(fromB64u(h)),payload=JSON.parse(fromB64u(p));if(header.alg!=='RS256'||!crypto.verify('RSA-SHA256',Buffer.from(`${h}.${p}`),keys.publicKey,Buffer.from(s,'base64url')))return null;if(Number(payload.exp||0)*1000<Date.now())return null;return payload;}catch{return null}}

// Redis-backed process-independent runtime state. MySQL remains the safe session fallback.
async function initRedis(){
  const url=process.env.SBC_REDIS_URL||process.env.REDIS_URL||'';
  if(!url||!RedisClient){redisReady=false;return false;}
  try{
    redisClient=RedisClient.createClient({url,socket:{reconnectStrategy:(retries)=>Math.min(1000*retries,10000)}});
    redisClient.on('error',e=>console.warn('[SBC REDIS]',e.message));
    await redisClient.connect(); redisReady=true; return true;
  }catch(e){console.warn('[SBC REDIS] unavailable; MySQL durability remains active:',e.message);redisReady=false;redisClient=null;return false;}
}
function redisSessionKey(token){return `sbc:session:${sessionHash(token)}`}
async function redisPutSession(token,rec){if(!redisReady||!redisClient)return false;const ttl=Math.max(1,Math.ceil((Number(rec.expiresAt)-Date.now())/1000));await redisClient.set(redisSessionKey(token),JSON.stringify(rec),{EX:ttl});return true}
async function redisGetSession(token){if(!redisReady||!redisClient)return null;const raw=await redisClient.get(redisSessionKey(token));if(!raw)return null;try{return JSON.parse(raw)}catch{return null}}
async function redisDropSession(token){if(redisReady&&redisClient)await redisClient.del(redisSessionKey(token))}
async function acquireWorkerLeader(){if(!redisReady||!redisClient)return process.env.NODE_APP_INSTANCE in {'0':1} || !process.env.NODE_APP_INSTANCE;const key='sbc:worker:leader';const value=`${process.pid}:${crypto.randomUUID()}`;const ok=await redisClient.set(key,value,{NX:true,EX:45});if(!ok)return false;setInterval(async()=>{try{if(await redisClient.get(key)===value)await redisClient.expire(key,45)}catch{}},15000).unref();return true}
const DISTRIBUTED_LOCK = createDistributedLock({get redisClient(){return redisClient},get redisReady(){return redisReady},get mysqlPool(){return mysqlPool},logger:console});

// V54.2.2 — Revenue PLAY uses a durable DB lease instead of a MySQL named lock.
// GET_LOCK() is connection-scoped and can report false lock contention when an
// unrelated pooled connection survives or is reused. The lease below is an
// explicit row with an expiry, so stale ownership is reclaimable and release is
// token-checked. Redis can still be used by the broader automation fabric.
async function acquireRevenuePlayLease({ttlSeconds=180,waitMs=5000}={}){
  if(!mysqlPool) return {acquired:false,reason:'mysql_unavailable',release:async()=>{}};
  const name='revenue-first-play';
  const token=`${process.pid}:${Date.now()}:${crypto.randomUUID()}`;
  const ttl=Math.max(30,Math.min(600,Number(ttlSeconds)||180));
  const deadline=Date.now()+Math.max(0,Number(waitMs)||0);
  while(true){
    try{
      await mysqlPool.query(`INSERT INTO sbc_runtime_leases (lease_name,lease_token,expires_at,updated_at)
        VALUES (?,?,DATE_ADD(UTC_TIMESTAMP(),INTERVAL ? SECOND),UTC_TIMESTAMP())
        ON DUPLICATE KEY UPDATE
          lease_token=IF(expires_at <= UTC_TIMESTAMP(),VALUES(lease_token),lease_token),
          expires_at=IF(expires_at <= UTC_TIMESTAMP(),VALUES(expires_at),expires_at),
          updated_at=IF(expires_at <= UTC_TIMESTAMP(),UTC_TIMESTAMP(),updated_at)`,[name,token,ttl]);
      const [rows]=await mysqlPool.query('SELECT lease_token,expires_at FROM sbc_runtime_leases WHERE lease_name=? LIMIT 1',[name]);
      if(String(rows?.[0]?.lease_token||'')===token){
        let released=false;
        return {
          acquired:true,
          fenceToken:token,
          verify:async()=>{try{const [r]=await mysqlPool.query('SELECT lease_token,expires_at FROM sbc_runtime_leases WHERE lease_name=? LIMIT 1',[name]);return String(r?.[0]?.lease_token||'')===token && new Date(r?.[0]?.expires_at||0).getTime()>Date.now()}catch{return false}},
          release:async()=>{if(released)return;released=true;try{await mysqlPool.query('DELETE FROM sbc_runtime_leases WHERE lease_name=? AND lease_token=?',[name,token])}catch(e){console.warn('[SBC REVENUE LEASE] release:',e.message)}}
        };
      }
    }catch(e){
      console.warn('[SBC REVENUE LEASE] acquire:',e.message);
      if(Date.now()>=deadline) return {acquired:false,reason:'lease_error',release:async()=>{}};
    }
    if(Date.now()>=deadline) return {acquired:false,reason:'revenue_first_lock_busy',release:async()=>{}};
    await new Promise(r=>setTimeout(r,Math.min(250,Math.max(50,deadline-Date.now()))));
  }
}
