// Optional read replica. If not configured, all reads safely fall back to the primary pool.
let mysqlReadPool=null;
async function initReadReplica(){
  if(!(process.env.DB_READ_HOST&&process.env.DB_USER&&process.env.DB_PASSWORD&&process.env.DB_NAME))return false;
  try{const mysql=require('mysql2/promise');mysqlReadPool=mysql.createPool({host:process.env.DB_READ_HOST,user:process.env.DB_USER,password:process.env.DB_PASSWORD,database:process.env.DB_NAME,port:Number(process.env.DB_READ_PORT||3306),waitForConnections:true,connectionLimit:Math.max(2,Number(process.env.DB_READ_POOL_SIZE||8)),charset:'utf8mb4'});await mysqlReadPool.query('SELECT 1');return true;}catch(e){console.warn('[SBC CQRS] read replica unavailable:',e.message);mysqlReadPool=null;return false;}
}
async function readQuery(sql,params=[]){const pool=mysqlReadPool||mysqlPool;if(!pool)throw new Error('No MySQL read pool configured.');return pool.query(sql,params)}

const architectureMetrics={startedAt:Date.now(),requests:0,errors:0,latencyMsTotal:0,routeCounts:{},externalErrors:0,queuePublished:0,queueDeferred:0};
async function persistObservabilityEvent(rec){
  if(!mysqlPool)return;
  try{await mysqlPool.query('INSERT INTO sbc_observability_events(timestamp_utc,trace_id,span_id,component,event,level,version,context_json) VALUES (?,?,?,?,?,?,?,?)',[new Date(rec.timestamp),String(rec.trace_id||'').slice(0,32),String(rec.span_id||'').slice(0,16),String(rec.component||'SBC_RUNTIME').slice(0,80),String(rec.event||'event').slice(0,160),String(rec.level||'INFO').slice(0,20),String(rec.version||BUILD_VERSION).slice(0,40),JSON.stringify(rec.context||{})]);}catch(e){/* observability must never take production down */}
}
function jsonLog(level,event,meta={}){
  const rec=OBSERVABILITY.normalizeEvent({level,event,component:meta.component||'SBC_RUNTIME',version:BUILD_VERSION,meta:{...meta,requestId:meta.requestId||''}});
  try{global.__SBC_RECENT_RUNTIME_EVENTS.push({...rec,status:Number(meta.status||0)});if(global.__SBC_RECENT_RUNTIME_EVENTS.length>500)global.__SBC_RECENT_RUNTIME_EVENTS.splice(0,global.__SBC_RECENT_RUNTIME_EVENTS.length-500);}catch{}
  rec.context.requestId=meta.requestId||rec.context.requestId||'';
  try{console.log(JSON.stringify(rec));persistObservabilityEvent(rec).catch(()=>{});shipOperationalLog(rec).catch(()=>{});}catch{console.log(`[SBC ${String(level).toUpperCase()}] ${event}`)}
}

