  ddl.push(`CREATE TABLE IF NOT EXISTS sbc_lead_quarantine (id VARCHAR(100) PRIMARY KEY,tenant_id BIGINT NOT NULL DEFAULT 1,batch_id VARCHAR(100) NOT NULL DEFAULT '',\`row_number\` INT NOT NULL DEFAULT 0,business_name VARCHAR(255) NOT NULL DEFAULT '',contact_name VARCHAR(255) NOT NULL DEFAULT '',email VARCHAR(320) NOT NULL DEFAULT '',phone VARCHAR(80) NOT NULL DEFAULT '',website VARCHAR(500) NOT NULL DEFAULT '',industry VARCHAR(160) NOT NULL DEFAULT '',lead_score INT NOT NULL DEFAULT 0,lead_temperature VARCHAR(20) NOT NULL DEFAULT 'cold',reason VARCHAR(120) NOT NULL DEFAULT 'LOW_QUALITY_SCORE_BELOW_55',status VARCHAR(30) NOT NULL DEFAULT 'QUARANTINED',payload_json LONGTEXT NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX idx_lead_quarantine_tenant_status(tenant_id,status),INDEX idx_lead_quarantine_batch(batch_id),INDEX idx_lead_quarantine_created(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4`);
