function hasCapability(req,cap){const role=String(req.user?.role||'');return (KIM_CAPABILITIES[cap]||[]).includes(role);}
function requireCapability(cap){return (req,res,next)=>{if(!req.user)return res.status(401).json({error:'Authentication required.'});if(!hasCapability(req,cap))return res.status(403).json({error:`Capability denied: ${cap}`});req.capability=cap;next();};}
function kimSystemAllowed(req,cap){return req.user?.role==='system' || hasCapability(req,cap);}
function redactSensitive(obj,role){if(!obj||typeof obj!=='object')return obj;const out=Array.isArray(obj)?obj.slice():{...obj};if(role!=='owner'){for(const k of ['passwordHash','token','tokenHash','secret','apiKey','api_key','accessToken','refreshToken','privateKey','secretCiphertext'])if(k in out)delete out[k];}return out;}

