function addActivity(type,message,meta={}){db.activities.unshift({id:id('act'),type,message,meta,createdAt:now()});db.activities=db.activities.slice(0,200)}

// Shared numeric money normalizer. Keep this at module scope so website demos,
// revenue, order summaries, and supervisor code cannot hit a scope-dependent ReferenceError.
function money(v){ const n=Number(v); return Number.isFinite(n) ? n : 0; }

// V55.2 — Revenue Autopilot Supervisor: manager + mechanic over the existing revenue engine.
function ecosystemOrderSplit(orders=[]){
  const printPattern=/card|print|flyer|banner|brochure|postcard|sticker|sign|yard|shirt|t-shirt|apparel|poster|menu|rack card/i;
  const list=Array.isArray(orders)?orders:[];
  const bucket=(isPrint)=>{
    const rows=list.filter(o=>printPattern.test(String(o?.product||o?.name||''))===isPrint);
    return {orders:rows.length,value:rows.reduce((sum,o)=>sum+money(o?.price??o?.total??0),0)};
  };
  return {digital:bucket(false),print:bucket(true)};
}

