// V32.9.0 — Enterprise Control Fabric: capabilities 101–150.
// These services are provider-neutral and fail closed: external writes remain gated by
// configured credentials/contracts, while internal ledgers, queues, hashes and readiness
// functions operate locally and are auditable.
function kimV329Gate(req,res,next){
  if(!req.user)return res.status(401).json({error:'Authentication required.'});
  if(!['owner','manager','kim_operator','system'].includes(String(req.user.role||'')))return res.status(403).json({error:'Kim enterprise operations access required.'});
  next();
}
let v329StarterLoaded=false;
