// V54.1.4 — Canonical CRM lead-mesh bridge.
// The V32.9 enterprise fabric previously maintained a separate in-memory starter-lead
// queue. That made the panel report zero leads even while the canonical CRM contained
// active sales leads. The CRM is the source of truth now; this bridge only mirrors
// non-destructive lead metadata into the enterprise fabric for queueing/visibility.
async function syncV329CanonicalLeadMesh(){
  const customers=Array.isArray(db.customers)?db.customers:[];
  // During guarded recovery, the authoritative CRM is intentionally empty. Use the
  // existing lead mesh as a read-only projection so Kim's dashboard does not falsely
  // report zero prospects. Never write this projection into the CRM here.
  if(MYSQL_RECOVERY_REQUIRED && mysqlPool){
    try{
      const [rows]=await mysqlPool.query(`SELECT id,batch_id,business_name,contact_name,email,phone,website,industry,address,source,status,created_at,updated_at FROM sbc_lead_mesh ORDER BY id DESC LIMIT 1000`);
      const mapped=(rows||[]).map(r=>({id:`recovery-lead-${String(r.id)}`,crmCustomerId:'',batchId:String(r.batch_id||'recovery-lead-mesh'),businessName:String(r.business_name||''),contactName:String(r.contact_name||''),email:String(r.email||''),phone:String(r.phone||''),website:String(r.website||''),city:'',address:String(r.address||''),industry:String(r.industry||''),source:String(r.source||'Lead Mesh'),status:'Needs Verification',verificationStatus:'Needs Verification',leadTemperature:'',leadScore:0,workable:false,readOnlyRecoveryProjection:true,leadMeshId:Number(r.id),updatedAt:r.updated_at||now()}));
      const batch={id:'recovery-lead-mesh',source:'sbc_lead_mesh recovery projection',rows:mapped.length,accepted:mapped.length,duplicates:0,schema:{source:'sbc_lead_mesh'},createdAt:now(),status:'RECOVERY_PROJECTION'};
      V329.state.leadBatches.set(batch.id,batch); V329.state.leads=mapped; V329.state.verificationQueue=[]; V329.state.workableQueue=[];
      return {source:'sbc_lead_mesh recovery projection',activeSalesLeads:0,verificationQueue:mapped.length,workableQueue:0,verifiedOrSalesReady:0,ownerVerifiedRecoveryLeads:0,preservedLeadMeshCandidates:mapped.length,readOnlyRecoveryProjection:true,records:mapped.length,recoveryRequired:true};
    }catch(e){console.warn('[V32.9] recovery projection unavailable:',e.message);}
  }
  const excluded=new Set(['Customer','Lost','Do Not Call','Closed','Duplicate','Not Qualified']);
  // V64.2.25: canonical lead sync must include owner-verified recovery leads even
  // when their temperature is blank. The prior Hot/Warm-only filter caused the
  // restored sbc_lead_mesh records to disappear from Kim/Operations after restore.
  const active=customers.filter(c=>{
    if(!c || isSbcSyntheticTestRecord(c) || excluded.has(String(c.status||'Lead'))) return false;
    const recoveryVerified=Boolean(c?.leadIntelligence?.recoverySource==='sbc_lead_mesh' && c?.leadIntelligence?.ownerVerified===true);
    const normalSalesLead=['Hot','Warm'].includes(String(c.leadTemperature||'')) && Boolean(String(c.email||'').trim()||String(c.phone||'').trim());
    return recoveryVerified || normalSalesLead;
  });
  const mapped=active.map(c=>{
    const recoveryVerified=Boolean(c?.leadIntelligence?.recoverySource==='sbc_lead_mesh' && c?.leadIntelligence?.ownerVerified===true);
    return {
      id:String(c.id),crmCustomerId:String(c.id),batchId:recoveryVerified?'crm-verified-recovery':'crm-active-sales',
      businessName:String(c.businessName||''),contactName:String(c.contactName||''),email:String(c.email||''),phone:String(c.phone||''),website:String(c.website||''),
      city:String(c.city||''),address:String(c.address||''),industry:String(c.industry||''),source:String(c.source||'CRM'),
      status:recoveryVerified?'Verified':String(c.verificationStatus||'Needs Verification'),
      verificationStatus:recoveryVerified?'Verified':String(c.verificationStatus||'Needs Verification'),
      leadTemperature:String(c.leadTemperature||''),leadScore:Number(c.leadScore||0),workable:Boolean(c.workableOverride) && !recoveryVerified,
      readOnlyRecoveryProjection:recoveryVerified?false:undefined,
      recoverySource:recoveryVerified?'sbc_lead_mesh':undefined,
      updatedAt:c.updatedAt||now()
    };
  });
  const batch={id:'crm-active-sales',source:'canonical CRM Active Sales Leads + owner-verified recovery',rows:mapped.length,accepted:mapped.length,duplicates:0,schema:{source:'db.customers'},createdAt:now(),status:'SYNCED'};
  V329.state.leadBatches.set(batch.id,batch); V329.state.leads=mapped;
  // Recovery-restored records are real CRM leads, but remain non-workable until
  // the owner-controlled restore gate is complete and the runtime is restarted.
  const restored=mapped.filter(x=>x.recoverySource==='sbc_lead_mesh');
  const normal=mapped.filter(x=>x.recoverySource!=='sbc_lead_mesh');
  V329.state.verificationQueue=[];
  V329.state.workableQueue=normal;
  return {
    source:'db.customers',activeSalesLeads:mapped.length,verificationQueue:0,
    workableQueue:normal.length,verifiedOrSalesReady:mapped.filter(x=>x.verificationStatus==='Verified'||x.verificationStatus==='Sales Ready').length,
    ownerVerifiedRecoveryLeads:restored.length,readOnlyRecoveryProjection:false
  };
}
async function promoteAllActiveLeadsToWorkable(){
  const customers=Array.isArray(db.customers)?db.customers:[]; const excluded=new Set(['Customer','Lost','Do Not Call','Closed','Duplicate','Not Qualified']); let changed=0;
  for(const c of customers){if(!c||isSbcSyntheticTestRecord(c)||excluded.has(String(c.status||'Lead')))continue;if(!['Hot','Warm'].includes(String(c.leadTemperature||'')))continue;if(!String(c.email||'').trim()&&!String(c.phone||'').trim())continue;if(!c.workableOverride){c.workableOverride=true;c.workableAt=now();c.workableBy='owner';c.updatedAt=now();changed++;}}
  const sync=await syncV329CanonicalLeadMesh();
  if(changed)audit({id:'system',name:'SBC Workable Queue Migration',role:'system'},'leads_promoted_to_workable',`Marked ${changed} active Warm/Hot leads as human-workable while preserving verification state`,{changed,workableQueue:sync.workableQueue,verificationPreserved:true});
  return {changed,...sync};
}


