app.post('/api/kim/v350/leads/import-starter',auth,async(req,res)=>{if(!['owner','kim_operator','lead_researcher','system'].includes(req.user.role))return res.status(403).json({error:'Lead mesh import is restricted to Owner, Kim, or Lorna.'});try{const result=V350.importCSV();if(mysqlPool){const rows=result.records||[];let inserted=0;for(const r of rows){const [out]=await mysqlPool.query('INSERT IGNORE INTO sbc_lead_mesh(batch_id,`row_number`,business_name,contact_name,email,phone,phone_normalized,website,industry,address,source,status,dedupe_key,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[r.batchId,r.rowNumber,r.businessName,r.contactName,r.email,r.phone,r.phoneNormalized,r.website,r.industry,r.address,r.source,r.status,r.dedupeKey,sqlDateTime(now()),sqlDateTime(now())]);inserted+=Number(out.affectedRows||0);}result.inserted=inserted;result.skipped=(result.rows||0)-inserted;}audit(req.user,'lead_mesh_import',`Imported starter lead mesh batch ${result.batchId}`,result);res.json({ok:true,result});}catch(e){res.status(400).json({ok:false,error:e.message});}});
app.get('/api/kim/v350/leads',auth,(req,res)=>{if(!['owner','kim_operator','lead_researcher','system'].includes(req.user.role))return res.status(403).json({error:'Lead mesh access denied.'});if(!mysqlPool)return res.json({ok:true,rows:[],source:V350.state.leadMesh});const limit=Math.max(1,Math.min(500,Number(req.query.limit||250)));mysqlPool.query('SELECT id,batch_id,`row_number`,business_name,contact_name,email,phone,website,industry,address,source,status,created_at,updated_at FROM sbc_lead_mesh ORDER BY id DESC LIMIT ?',[limit]).then(([rows])=>res.json({ok:true,rows,source:V350.state.leadMesh})).catch(e=>res.status(500).json({error:e.message}));});
// SBC_V6522_API_STABILIZATION: bound slow MySQL projection so the UI receives explicit degraded state instead of hanging.

// SBC_V6567_MARKETING_API: tenant-scoped durable content workflow; public publishing remains disabled until provider verification.
async function sbcEnsureMarketingHubSchema(){
 if(!mysqlPool)throw Object.assign(new Error('MARKETING_MYSQL_UNAVAILABLE'),{status:503});
 if(SBC_RUNTIME_READ_ONLY||!MYSQL_RECOVERY_EVALUATED||MYSQL_RECOVERY_REQUIRED||!sbcWriterLeaseReady)throw Object.assign(new Error('MARKETING_WRITER_GATE_CLOSED'),{status:423});
 await mysqlPool.query("CREATE TABLE IF NOT EXISTS sbc_marketing_content (tenant_id BIGINT NOT NULL,item_id VARCHAR(96) NOT NULL,title VARCHAR(180) NOT NULL,platform VARCHAR(24) NOT NULL,offer VARCHAR(120) NOT NULL,body MEDIUMTEXT NOT NULL,media_url VARCHAR(2048) NOT NULL DEFAULT '',cta_url VARCHAR(2048) NOT NULL DEFAULT '',cta VARCHAR(120) NOT NULL DEFAULT '',status VARCHAR(24) NOT NULL DEFAULT 'DRAFT',scheduled_at DATETIME NULL,approved_by VARCHAR(120) NULL,approved_at DATETIME NULL,provider_post_id VARCHAR(255) NOT NULL DEFAULT '',published_at DATETIME NULL,publish_error_code VARCHAR(80) NOT NULL DEFAULT '',created_by VARCHAR(120) NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,PRIMARY KEY(tenant_id,item_id),KEY idx_sbc_marketing_status(tenant_id,status,updated_at),KEY idx_sbc_marketing_schedule(tenant_id,status,scheduled_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
}
function sbcMarketingItem(row){return {id:String(row.item_id),title:row.title,platform:row.platform,offer:row.offer,body:row.body,mediaUrl:row.media_url||'',ctaUrl:row.cta_url||'',cta:row.cta,status:String(row.status||'DRAFT').toLowerCase(),scheduledAt:row.scheduled_at?new Date(row.scheduled_at).toISOString():'',approvedBy:row.approved_by||'',approvedAt:row.approved_at?new Date(row.approved_at).toISOString():'',providerPostId:row.provider_post_id||'',publishedAt:row.published_at?new Date(row.published_at).toISOString():'',publishErrorCode:row.publish_error_code||'',createdAt:row.created_at?new Date(row.created_at).toISOString():'',updatedAt:row.updated_at?new Date(row.updated_at).toISOString():'',durable:true};}
async function sbcMarketingSecret(name,tenantId){try{const v=await vaultSecret(name,tenantId);if(v)return v;}catch{}if(String(tenantId)!==String(TENANT_DEFAULT_ID))return '';return secretValue(name,name)||'';}
async function sbcMarketingFetchJSON(url,options={}){const r=await fetch(url,{...options,signal:AbortSignal.timeout(12000)});const data=await r.json().catch(()=>({}));if(!r.ok)throw Object.assign(new Error('MARKETING_PROVIDER_HTTP_'+r.status),{code:'MARKETING_PROVIDER_HTTP_'+r.status,statusCode:r.status});return data;}
async function sbcMarketingProviderAuth(platform,tenantId){
 if(platform==='facebook'||platform==='instagram'){
  const pageId=await sbcMarketingSecret('META_PAGE_ID',tenantId),pageToken=await sbcMarketingSecret('META_PAGE_ACCESS_TOKEN',tenantId),igId=await sbcMarketingSecret('META_INSTAGRAM_BUSINESS_ACCOUNT_ID',tenantId);
  if(!pageId||!pageToken||(platform==='instagram'&&!igId))throw Object.assign(new Error('MARKETING_CREDENTIALS_MISSING'),{code:'MARKETING_CREDENTIALS_MISSING'});
  const configuredVersion=await sbcMarketingSecret('META_GRAPH_API_VERSION',tenantId);const version=String(configuredVersion||process.env.META_GRAPH_API_VERSION||'v26.0').replace(/[^v0-9.]/g,'');const graphBase='https://graph.facebook.com/'+(version||'v26.0');
  const page=await sbcMarketingFetchJSON(graphBase+'/'+encodeURIComponent(pageId)+'?fields=id,name',{headers:{Authorization:'Bearer '+pageToken}});
  if(String(page.id||'')!==String(pageId))throw Object.assign(new Error('META_PAGE_ID_MISMATCH'),{code:'META_PAGE_ID_MISMATCH'});
  if(platform==='instagram'){const ig=await sbcMarketingFetchJSON(graphBase+'/'+encodeURIComponent(igId)+'?fields=id,username',{headers:{Authorization:'Bearer '+pageToken}});if(String(ig.id||'')!==String(igId))throw Object.assign(new Error('META_INSTAGRAM_ID_MISMATCH'),{code:'META_INSTAGRAM_ID_MISMATCH'});}
  return {platform,pageId,pageToken,igId,graphBase,verified:true};
 }
 if(platform==='google'){
  const clientId=await sbcMarketingSecret('GOOGLE_BUSINESS_PROFILE_CLIENT_ID',tenantId),clientSecret=await sbcMarketingSecret('GOOGLE_BUSINESS_PROFILE_CLIENT_SECRET',tenantId),refreshToken=await sbcMarketingSecret('GOOGLE_BUSINESS_PROFILE_REFRESH_TOKEN',tenantId),accountId=await sbcMarketingSecret('GOOGLE_BUSINESS_PROFILE_ACCOUNT_ID',tenantId),locationId=await sbcMarketingSecret('GOOGLE_BUSINESS_PROFILE_LOCATION_ID',tenantId);
  if(!clientId||!clientSecret||!refreshToken||!accountId||!locationId)throw Object.assign(new Error('MARKETING_CREDENTIALS_MISSING'),{code:'MARKETING_CREDENTIALS_MISSING'});
  const tokenBody=new URLSearchParams({client_id:clientId,client_secret:clientSecret,refresh_token:refreshToken,grant_type:'refresh_token'});
  const token=await sbcMarketingFetchJSON('https://oauth2.googleapis.com/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:tokenBody});
  if(!token.access_token)throw Object.assign(new Error('GOOGLE_ACCESS_TOKEN_UNAVAILABLE'),{code:'GOOGLE_ACCESS_TOKEN_UNAVAILABLE'});
  const parent='accounts/'+encodeURIComponent(accountId)+'/locations/'+encodeURIComponent(locationId);
  await sbcMarketingFetchJSON('https://mybusiness.googleapis.com/v4/'+parent+'/localPosts?pageSize=1',{headers:{Authorization:'Bearer '+token.access_token}});
  return {platform,accessToken:token.access_token,accountId,locationId,parent,verified:true};
 }
 throw Object.assign(new Error('UNSUPPORTED_MARKETING_PLATFORM'),{code:'UNSUPPORTED_MARKETING_PLATFORM'});
}
async function sbcPublishMarketingRow(row,provider){
 if(!row.approved_at)throw Object.assign(new Error('OWNER_APPROVAL_REQUIRED'),{code:'OWNER_APPROVAL_REQUIRED'});
 if(provider.platform==='facebook'){
  const form=new URLSearchParams({message:String(row.body||'')});if(row.cta_url)form.set('link',row.cta_url);
  const out=await sbcMarketingFetchJSON(provider.graphBase+'/'+encodeURIComponent(provider.pageId)+'/feed',{method:'POST',headers:{Authorization:'Bearer '+provider.pageToken,'Content-Type':'application/x-www-form-urlencoded'},body:form});
  if(!out.id)throw Object.assign(new Error('META_POST_ID_MISSING'),{code:'META_POST_ID_MISSING'});return String(out.id);
 }
 if(provider.platform==='instagram'){
  if(!row.media_url||!/^https:\/\//i.test(String(row.media_url)))throw Object.assign(new Error('INSTAGRAM_PUBLIC_HTTPS_MEDIA_URL_REQUIRED'),{code:'INSTAGRAM_PUBLIC_HTTPS_MEDIA_URL_REQUIRED'});
  const form=new URLSearchParams({image_url:row.media_url,caption:String(row.body||'')});
  const container=await sbcMarketingFetchJSON(provider.graphBase+'/'+encodeURIComponent(provider.igId)+'/media',{method:'POST',headers:{Authorization:'Bearer '+provider.pageToken,'Content-Type':'application/x-www-form-urlencoded'},body:form});
  if(!container.id)throw Object.assign(new Error('INSTAGRAM_CONTAINER_ID_MISSING'),{code:'INSTAGRAM_CONTAINER_ID_MISSING'});
  let ready=false;for(let i=0;i<5;i++){const status=await sbcMarketingFetchJSON(provider.graphBase+'/'+encodeURIComponent(container.id)+'?fields=status_code',{headers:{Authorization:'Bearer '+provider.pageToken}});if(status.status_code==='FINISHED'){ready=true;break}if(status.status_code==='ERROR')throw Object.assign(new Error('INSTAGRAM_MEDIA_PROCESSING_FAILED'),{code:'INSTAGRAM_MEDIA_PROCESSING_FAILED'});await new Promise(resolve=>setTimeout(resolve,1000))}
  if(!ready)throw Object.assign(new Error('INSTAGRAM_MEDIA_NOT_READY'),{code:'INSTAGRAM_MEDIA_NOT_READY'});
  const publish=await sbcMarketingFetchJSON(provider.graphBase+'/'+encodeURIComponent(provider.igId)+'/media_publish',{method:'POST',headers:{Authorization:'Bearer '+provider.pageToken,'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({creation_id:String(container.id)})});
  if(!publish.id)throw Object.assign(new Error('INSTAGRAM_PUBLISH_ID_MISSING'),{code:'INSTAGRAM_PUBLISH_ID_MISSING'});return String(publish.id);
 }
 if(provider.platform==='google'){
  const payload={languageCode:'en-US',summary:String(row.body||''),topicType:'STANDARD'};
  if(row.media_url){if(!/^https:\/\//i.test(String(row.media_url)))throw Object.assign(new Error('GOOGLE_PUBLIC_HTTPS_MEDIA_URL_REQUIRED'),{code:'GOOGLE_PUBLIC_HTTPS_MEDIA_URL_REQUIRED'});payload.media=[{mediaFormat:'PHOTO',sourceUrl:row.media_url}]}
  if(row.cta_url){const cta=String(row.cta||'').toLowerCase();const action=cta.includes('book')?'BOOK':cta.includes('call')?'CALL':cta.includes('quote')||cta.includes('learn')?'LEARN_MORE':cta.includes('visit')?'LEARN_MORE':'LEARN_MORE';payload.callToAction={actionType:action};if(action!=='CALL')payload.callToAction.url=row.cta_url}
  const out=await sbcMarketingFetchJSON('https://mybusiness.googleapis.com/v4/'+provider.parent+'/localPosts',{method:'POST',headers:{Authorization:'Bearer '+provider.accessToken,'Content-Type':'application/json'},body:JSON.stringify(payload)});
  if(!out.name)throw Object.assign(new Error('GOOGLE_LOCAL_POST_ID_MISSING'),{code:'GOOGLE_LOCAL_POST_ID_MISSING'});return String(out.name);
 }
 throw Object.assign(new Error('UNSUPPORTED_MARKETING_PLATFORM'),{code:'UNSUPPORTED_MARKETING_PLATFORM'});
}
async function sbcMarketingInsights(platform,provider){
 if(platform==='facebook'){const since=Math.floor((Date.now()-28*86400000)/1000),until=Math.floor(Date.now()/1000),out={};for(const metric of ['page_media_view','page_total_media_view_unique','page_post_engagements','page_views_total']){try{const q=new URLSearchParams({metric,period:'day',since:String(since),until:String(until)});const d=await sbcMarketingFetchJSON(provider.graphBase+'/'+encodeURIComponent(provider.pageId)+'/insights?'+q.toString(),{headers:{Authorization:'Bearer '+provider.pageToken}});const values=(d.data?.[0]?.values||[]).map(x=>x.value).filter(v=>v!==undefined&&v!==null&&Number.isFinite(Number(v)));out[metric]=values.length?values.reduce((n,v)=>n+Number(v),0):null}catch{out[metric]=null}}return {platform,verified:true,periodDays:28,metrics:out}}
 if(platform==='instagram'){const q=new URLSearchParams({fields:'id,like_count,comments_count,timestamp',limit:'25'});const d=await sbcMarketingFetchJSON(provider.graphBase+'/'+encodeURIComponent(provider.igId)+'/media?'+q.toString(),{headers:{Authorization:'Bearer '+provider.pageToken}});const media=Array.isArray(d.data)?d.data:[],sum=k=>{const values=media.map(x=>x[k]).filter(v=>v!==undefined&&v!==null);return values.length?values.reduce((n,v)=>n+(Number.isFinite(Number(v))?Number(v):0),0):null};return {platform,verified:true,period:'latest_25_media',metrics:{postsReturned:media.length,likesLast25Posts:sum('like_count'),commentsLast25Posts:sum('comments_count')}}}
 const end=new Date(),start=new Date(end.getTime()-28*86400000),parent=provider.parent,payload={locationNames:[parent],basicRequest:{metricRequests:[{metric:'VIEWS_SEARCH',options:['AGGREGATED_TOTAL']},{metric:'VIEWS_MAPS',options:['AGGREGATED_TOTAL']},{metric:'ACTIONS_WEBSITE',options:['AGGREGATED_TOTAL']},{metric:'ACTIONS_PHONE',options:['AGGREGATED_TOTAL']},{metric:'ACTIONS_DRIVING_DIRECTIONS',options:['AGGREGATED_TOTAL']}],timeRange:{startTime:start.toISOString(),endTime:end.toISOString()}}};const d=await sbcMarketingFetchJSON('https://mybusiness.googleapis.com/v4/accounts/'+encodeURIComponent(provider.accountId)+'/locations:reportInsights',{method:'POST',headers:{Authorization:'Bearer '+provider.accessToken,'Content-Type':'application/json'},body:JSON.stringify(payload)});const out={};for(const v of d.locationMetrics?.[0]?.metricValues||[]){const value=v.totalValue&&v.totalValue.value!==undefined&&v.totalValue.value!==null?Number(v.totalValue.value):NaN;out[v.metric]=Number.isFinite(value)?value:null};return {platform,verified:true,periodDays:28,metrics:out}
}
app.get('/api/marketing/analytics',auth,ownerOnly,async(req,res)=>{try{const tenantId=requireRequestTenant(req);if(!mysqlPool)return res.status(503).json({ok:false,error:'MARKETING_MYSQL_UNAVAILABLE'});const [rows]=await mysqlPool.query('SELECT status,COUNT(*) AS count FROM sbc_marketing_content WHERE tenant_id=? GROUP BY status',[tenantId]);const counts={draft:0,pendingApproval:0,approved:0,scheduled:0,publishing:0,published:0,failed:0};for(const row of rows){const k=String(row.status||'').toLowerCase(),key=k==='pending_approval'?'pendingApproval':k;if(Object.prototype.hasOwnProperty.call(counts,key))counts[key]=Number(row.count||0)}const platforms={};for(const platform of ['facebook','instagram','google']){try{const provider=await sbcMarketingProviderAuth(platform,tenantId);platforms[platform]=await sbcMarketingInsights(platform,provider)}catch(e){platforms[platform]={platform,verified:false,metrics:null,errorCode:String(e.code||'INSIGHTS_UNAVAILABLE').slice(0,80)}}}res.setHeader('Cache-Control','no-store');return res.json({ok:true,periodDays:28,counts,platforms,attribution:{available:false,reason:'UTM and conversion attribution are not connected; CAC and ROAS are not calculated.'}})}catch(e){return res.status(503).json({ok:false,error:String(e.code||'MARKETING_ANALYTICS_UNAVAILABLE')});}});
async function sbcProcessDueMarketingPosts(){if(!mysqlPool||SBC_RUNTIME_READ_ONLY||!MYSQL_RECOVERY_EVALUATED||MYSQL_RECOVERY_REQUIRED||!sbcWriterLeaseReady)return;let rows=[];try{[rows]=await mysqlPool.query("SELECT tenant_id,item_id,title,platform,offer,body,media_url,cta_url,cta,status,scheduled_at,approved_by,approved_at,provider_post_id,published_at,publish_error_code,created_by,created_at,updated_at FROM sbc_marketing_content WHERE status='SCHEDULED' AND scheduled_at<=UTC_TIMESTAMP() ORDER BY scheduled_at ASC LIMIT 5")}catch(e){if(String(e.code||'')!=='ER_NO_SUCH_TABLE')console.warn('[SBC MARKETING] scheduled read unavailable:',String(e.code||e.message||'database error'));return}for(const row of rows){const tenantId=Number(row.tenant_id);let provider;try{provider=await sbcMarketingProviderAuth(row.platform,tenantId)}catch(e){continue}let claim;try{[claim]=await mysqlPool.query("UPDATE sbc_marketing_content SET status='PUBLISHING',publish_error_code='',updated_at=UTC_TIMESTAMP() WHERE tenant_id=? AND item_id=? AND status='SCHEDULED' AND scheduled_at<=UTC_TIMESTAMP() AND approved_at IS NOT NULL",[tenantId,row.item_id])}catch{continue}if(!claim.affectedRows)continue;try{const remoteId=await sbcPublishMarketingRow(row,provider);await mysqlPool.query("UPDATE sbc_marketing_content SET status='PUBLISHED',provider_post_id=?,published_at=UTC_TIMESTAMP(),publish_error_code='',updated_at=UTC_TIMESTAMP() WHERE tenant_id=? AND item_id=? AND status='PUBLISHING'",[remoteId,tenantId,row.item_id]);}catch(e){await mysqlPool.query("UPDATE sbc_marketing_content SET status='FAILED',publish_error_code=?,updated_at=UTC_TIMESTAMP() WHERE tenant_id=? AND item_id=? AND status='PUBLISHING'",[String(e.code||'PUBLISH_FAILED').slice(0,80),tenantId,row.item_id]).catch(()=>{});}}}
const sbcMarketingSchedulerTimer=setInterval(()=>{sbcProcessDueMarketingPosts().catch(()=>{})},60000);if(sbcMarketingSchedulerTimer.unref)sbcMarketingSchedulerTimer.unref();
async function sbcMarketingSecretPresent(name,tenantId){return Boolean(await sbcMarketingSecret(name,tenantId));}
app.get('/api/marketing/integrations/status',auth,ownerOnly,async(req,res)=>{try{const tenantId=requireRequestTenant(req),platform=String(req.query?.platform||'');const configs={facebook:['META_PAGE_ID','META_PAGE_ACCESS_TOKEN'],instagram:['META_PAGE_ID','META_PAGE_ACCESS_TOKEN','META_INSTAGRAM_BUSINESS_ACCOUNT_ID'],google:['GOOGLE_BUSINESS_PROFILE_CLIENT_ID','GOOGLE_BUSINESS_PROFILE_CLIENT_SECRET','GOOGLE_BUSINESS_PROFILE_REFRESH_TOKEN','GOOGLE_BUSINESS_PROFILE_ACCOUNT_ID','GOOGLE_BUSINESS_PROFILE_LOCATION_ID']};if(!configs[platform])return res.status(400).json({ok:false,error:'UNSUPPORTED_MARKETING_PLATFORM'});const missing=[];for(const name of configs[platform])if(!await sbcMarketingSecretPresent(name,tenantId))missing.push(name);let verified=false,verificationErrorCode='';if(!missing.length){try{await sbcMarketingProviderAuth(platform,tenantId);verified=true}catch(e){verificationErrorCode=String(e.code||'PROVIDER_VERIFICATION_FAILED').slice(0,80)}}res.setHeader('Cache-Control','no-store');return res.json({ok:true,platform,status:verified?'connected':missing.length?'not_configured':'configured',configured:missing.length===0,verified,missingSecrets:missing,verificationErrorCode,tokenExposed:false,publishEnabled:verified,verificationMessage:verified?'Provider identity and access check passed.':missing.length?'Required credentials are missing.':'Credentials are present, but provider identity or permissions could not be verified.'});}catch(e){return res.status(503).json({ok:false,error:'MARKETING_INTEGRATION_STATUS_UNAVAILABLE'});}});
app.get('/api/marketing/content',auth,ownerOnly,async(req,res)=>{try{if(!mysqlPool)return res.status(503).json({ok:false,error:'MARKETING_MYSQL_UNAVAILABLE',durable:false});const tenantId=requireRequestTenant(req);const [rows]=await mysqlPool.query('SELECT item_id,title,platform,offer,body,media_url,cta_url,cta,status,scheduled_at,approved_by,approved_at,provider_post_id,published_at,publish_error_code,created_by,created_at,updated_at FROM sbc_marketing_content WHERE tenant_id=? ORDER BY updated_at DESC LIMIT 500',[tenantId]);return res.json({ok:true,durable:true,items:rows.map(sbcMarketingItem)});}catch(e){return res.status(503).json({ok:false,error:String(e.code||'')==='ER_NO_SUCH_TABLE'?'MARKETING_SCHEMA_NOT_READY':'MARKETING_CONTENT_READ_FAILED',durable:false});}});
app.post('/api/marketing/content',auth,ownerOnly,async(req,res)=>{try{await sbcEnsureMarketingHubSchema();const tenantId=requireRequestTenant(req),b=req.body||{},platform=String(b.platform||'').toLowerCase(),title=String(b.title||'').trim().slice(0,180),offer=String(b.offer||'').trim().slice(0,120),body=String(b.body||'').trim().slice(0,12000),mediaUrl=String(b.mediaUrl||'').trim().slice(0,2048),ctaUrl=String(b.ctaUrl||'').trim().slice(0,2048),cta=String(b.cta||'').trim().slice(0,120),itemId=String(b.id||'').trim();const safeHttps=u=>{if(!u)return true;try{return new URL(u).protocol==='https:'}catch{return false}};if(!['facebook','instagram','google'].includes(platform)||!title||!body||!/^[-A-Za-z0-9_]{8,96}$/.test(itemId)||!safeHttps(mediaUrl)||!safeHttps(ctaUrl))return res.status(400).json({ok:false,error:'INVALID_MARKETING_CONTENT_OR_MEDIA_URL'});const sqlNow=new Date().toISOString().slice(0,19).replace('T',' ');await mysqlPool.query("INSERT INTO sbc_marketing_content(tenant_id,item_id,title,platform,offer,body,media_url,cta_url,cta,status,created_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,'DRAFT',?,?,?) ON DUPLICATE KEY UPDATE title=VALUES(title),platform=VALUES(platform),offer=VALUES(offer),body=VALUES(body),media_url=VALUES(media_url),cta_url=VALUES(cta_url),cta=VALUES(cta),status='DRAFT',scheduled_at=NULL,approved_by=NULL,approved_at=NULL,updated_at=VALUES(updated_at)",[tenantId,itemId,title,platform,offer,body,mediaUrl,ctaUrl,cta,String(req.user.id||req.user.username||'owner'),sqlNow,sqlNow]);const [rows]=await mysqlPool.query('SELECT item_id,title,platform,offer,body,media_url,cta_url,cta,status,scheduled_at,approved_by,approved_at,provider_post_id,published_at,publish_error_code,created_by,created_at,updated_at FROM sbc_marketing_content WHERE tenant_id=? AND item_id=? LIMIT 1',[tenantId,itemId]);return res.status(201).json({ok:true,durable:true,item:sbcMarketingItem(rows[0])});}catch(e){return res.status(Number(e.status||503)).json({ok:false,error:String(e.message||'MARKETING_CONTENT_SAVE_FAILED'),durable:false});}});
