function localRateLimit({windowMs=60000,max=12,message='Too many requests. Try again later.'}={}){const m=new Map();return (req,res,next)=>{const key=req.ip||req.socket?.remoteAddress||'x',a=m.get(key)||[];const nowMs=Date.now(),recent=a.filter(t=>nowMs-t<windowMs);if(recent.length>=max)return res.status(429).json({error:message,retryAfterSeconds:Math.ceil((windowMs-(nowMs-(recent[0]||nowMs)))/1000)});recent.push(nowMs);m.set(key,recent);if(m.size>10000&&Math.random()<0.01){for(const [k,v] of m){if(!v.some(t=>nowMs-t<windowMs))m.delete(k)}}next()}}
function rateLimit(){return localRateLimit({windowMs:60000,max:12,message:'Too many login attempts. Try again in a minute.'})}
const apiRateLimiter = expressRateLimit ? expressRateLimit({windowMs:Number(process.env.SBC_API_RATE_WINDOW_MS||15*60*1000),max:Number(process.env.SBC_API_RATE_MAX||300),standardHeaders:'draft-7',legacyHeaders:false,skip:(req)=>req.method==='OPTIONS',handler:(req,res)=>res.status(429).json({error:'SBC API rate limit reached. Try again later.',requestId:req.requestId||null})}) : localRateLimit({windowMs:15*60*1000,max:300,message:'SBC API rate limit reached. Try again later.'});
function totals(items){const subtotal=items.reduce((a,x)=>a+(Number(x.qty)||0)*(Number(x.unitPrice)||0),0);return subtotal}

function smtpConfig(){
  const host=process.env.SBC_SMTP_HOST;
  const user=process.env.SBC_SMTP_USER;
  const pass=process.env.SBC_SMTP_PASS;
  if(!host||!user||!pass) return null;
  return {host,user,pass};
}
function createSmtpTransport(port,secure){
  const cfg=smtpConfig();
  if(!cfg) return null;
  return nodemailer.createTransport({
    host:cfg.host,
    port:Number(port),
    secure:Boolean(secure),
    auth:{user:cfg.user,pass:cfg.pass},
    connectionTimeout:5000,
    greetingTimeout:5000,
    socketTimeout:10000
  });
}
function mailTransport(){
  const configuredPort=Number(process.env.SBC_SMTP_PORT||587);
  const configuredSecure=String(process.env.SBC_SMTP_SECURE||'false')==='true';
  return createSmtpTransport(configuredPort,configuredSecure);
}
function smtpTransportCandidates(){
  const configuredPort=Number(process.env.SBC_SMTP_PORT||587);
  const configuredSecure=String(process.env.SBC_SMTP_SECURE||'false')==='true';
  const candidates=[{kind:'configured',host:smtpConfig()?.host,port:configuredPort,secure:configuredSecure,auth:true}];
  // First fallback: authenticated SMTP submission on 587.
  if(configuredPort===465) candidates.push({kind:'submission-fallback',host:smtpConfig()?.host,port:587,secure:false,auth:true});
  // GoDaddy Web Hosting relay: port 25, no SMTP authentication. This is
  // intentionally opt-in by default only for GoDaddy's documented relay host.
  // It avoids the PaaS outbound 465/587 block while keeping credentials out
  // of the relay connection. The sender must be an address whose DNS is managed
  // by the SBC domain and SPF must include secureserver.net.
  const relayHost=String(process.env.SBC_SMTP_RELAY_HOST||'relay-hosting.secureserver.net').trim();
  const relayEnabled=String(process.env.SBC_SMTP_RELAY_ENABLED||'true').toLowerCase()!=='false';
  if(relayEnabled) candidates.push({kind:'godaddy-relay',host:relayHost,port:25,secure:false,auth:false});
  return candidates;
}
function createSmtpTransportForCandidate(candidate){
  const cfg=smtpConfig();
  if(!cfg && candidate.auth!==false) return null;
  const options={
    host:candidate.host || cfg.host,
    port:Number(candidate.port),
    secure:Boolean(candidate.secure),
    connectionTimeout:5000,
    greetingTimeout:5000,
    socketTimeout:10000
  };
  if(candidate.auth!==false) options.auth={user:cfg.user,pass:cfg.pass};
  return nodemailer.createTransport(options);
}
async function smtpVerifyWithFallback(){
  if(!smtpConfig()) return {ok:false,configured:false};
  let lastError=null;
  const attempts=[];
  for(const candidate of smtpTransportCandidates()){
    const transport=createSmtpTransportForCandidate(candidate);
    try{
      await transport.verify();
      try{transport.close();}catch{}
      return {ok:true,configured:true,port:candidate.port,host:candidate.host,kind:candidate.kind,secure:candidate.secure,attempts};
    }catch(e){
      lastError=e;
      attempts.push({kind:candidate.kind,host:candidate.host,port:candidate.port,error:String(e.message||e).slice(0,250)});
      try{transport.close();}catch{}
    }
  }
  return {ok:false,configured:true,error:lastError,attempts};
}
async function smtpSendWithFallback(payload){
  if(!smtpConfig()) throw new Error('Email is not configured. Add SBC_SMTP_HOST, SBC_SMTP_USER and SBC_SMTP_PASS in GoDaddy Secrets.');
  let lastError=null;
  for(const candidate of smtpTransportCandidates()){
    const transport=createSmtpTransportForCandidate(candidate);
    try{
      const info=await transport.sendMail(payload);
      try{transport.close();}catch{}
      return {info,port:candidate.port,host:candidate.host,kind:candidate.kind};
    }catch(e){
      lastError=e;
      try{transport.close();}catch{}
    }
  }
  throw new Error(`SMTP delivery failed on all configured/fallback relay paths: ${String(lastError?.message||lastError).slice(0,250)}`);
}
function mergeTemplate(text,c){return String(text||'').replace(/{{\s*contact_name\s*}}/gi,c?.contactName||'').replace(/{{\s*business_name\s*}}/gi,c?.businessName||'').replace(/{{\s*phone\s*}}/gi,c?.phone||'').replace(/{{\s*website\s*}}/gi,c?.website||'').replace(/{{\s*email\s*}}/gi,c?.email||'');}
async function sendEmail(customer,subject,body){
  if(RUNTIME_GATE.blocked('AUTONOMOUS_OUTREACH')) throw new Error('AUTONOMOUS_OUTREACH_PAUSED_BY_OWNER');
  if(!smtpConfig()) throw new Error('Email is not configured. Add SBC_SMTP_HOST, SBC_SMTP_USER and SBC_SMTP_PASS in GoDaddy Secrets.');
  if(!customer?.email) throw new Error('This lead does not have an email address.');
  const from=process.env.SBC_MAIL_FROM||String(db.settings?.email||'j@sbcmia.com').trim()||process.env.SBC_SMTP_USER;
  const payload={from,to:customer.email,subject:mergeTemplate(subject,customer),text:mergeTemplate(body,customer)};
  const sent=await smtpSendWithFallback(payload);
  addActivity('email',`Email sent to ${customer.businessName||customer.contactName}`,{customerId:customer.id,to:customer.email,subject,smtpPort:sent.port});
  return {messageId:sent.info.messageId,to:customer.email,smtpPort:sent.port};
}
function acquisitionMessagingAllowed(customer){
  const source=String(customer?.source||'').toLowerCase();
  const status=String(customer?.status||'').toLowerCase();
  const acquisitionLike=source.includes('findr')||source.includes('acquisition')||source.includes('prospect')||status==='lead';
  if(!acquisitionLike)return {allowed:true,reason:'existing_customer_or_non-prospect_context'};
  if(customer?.smsOptOut===true || customer?.doNotContact===true || customer?.doNotCall===true)return {allowed:false,reason:'opted_out_or_suppressed'};
  if(customer?.smsConsent===true || customer?.consentToSms===true)return {allowed:true,reason:'explicit_sms_consent'};
  return {allowed:false,reason:'explicit_sms_consent_required_for_prospect_sms'};
}
async function sendSms(customer,body){
  if(RUNTIME_GATE.blocked('AUTONOMOUS_OUTREACH')) throw new Error('AUTONOMOUS_OUTREACH_PAUSED_BY_OWNER');
  const eligibility=acquisitionMessagingAllowed(customer);
  if(!eligibility.allowed) throw new Error(`OUTREACH_BLOCKED:${eligibility.reason}`);
  const sid=process.env.SBC_TWILIO_ACCOUNT_SID||process.env.TWILIO_ACCOUNT_SID;
  const from=process.env.SBC_TWILIO_FROM||process.env.TWILIO_PHONE_NUMBER;
  const keySid=process.env.TWILIO_API_KEY_SID, keySecret=secretValue('TWILIO_API_KEY_SECRET','TWILIO_API_KEY_SECRET');
  const authToken=secretValue('SBC_TWILIO_AUTH_TOKEN','SBC_TWILIO_AUTH_TOKEN','TWILIO_AUTH_TOKEN');
  if(!sid||!from||!(authToken||(keySid&&keySecret))) throw new Error('SMS is not configured. Add the Twilio Account SID, API key SID/secret (or Auth Token), and Twilio phone number in GoDaddy Secrets.');
  if(!customer?.phone) throw new Error('This lead does not have a phone number.');
  const params=new URLSearchParams({To:customer.phone,From:from,Body:mergeTemplate(body,customer)});
  const credentialUser=keySid&&keySecret?keySid:sid, credentialPass=keySid&&keySecret?keySecret:authToken;
  const r=await fetch(`https://api.twilio.com/2010-04-01/Accounts/${encodeURIComponent(sid)}/Messages.json`,{method:'POST',headers:{Authorization:'Basic '+Buffer.from(`${credentialUser}:${credentialPass}`).toString('base64'),'Content-Type':'application/x-www-form-urlencoded'},body:params,signal:AbortSignal.timeout(Number(process.env.SBC_TWILIO_TIMEOUT_MS||20000))});
  const data=await r.json(); if(!r.ok) throw new Error(data.message||'Twilio SMS failed.');
  addActivity('sms',`SMS sent to ${customer.businessName||customer.contactName}`,{customerId:customer.id,to:customer.phone,sid:data.sid});
  return {sid:data.sid,to:customer.phone};
}
function calendarIcs(a){
  const escIcs=v=>String(v||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');
  const dtv=x=>new Date(x).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/,'Z');
  const end=a.endAt||new Date(new Date(a.startAt).getTime()+30*60000).toISOString();
  return `BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//Successful By Choice//SBC Business Command Center//EN\r\nBEGIN:VEVENT\r\nUID:${a.id}@sbc\r\nDTSTAMP:${dtv(new Date())}\r\nDTSTART:${dtv(a.startAt)}\r\nDTEND:${dtv(end)}\r\nSUMMARY:${escIcs(a.title)}\r\nLOCATION:${escIcs(a.location)}\r\nDESCRIPTION:${escIcs(a.notes)}\r\nEND:VEVENT\r\nEND:VCALENDAR\r\n`;
}
let sequenceAutomationRunning=false;
async function processSequences(){
  if(db.settings.automationEnabled===false) return;
  // The worker leader already gates background execution inside this process.
  // Keep a local re-entry guard so a slow cycle cannot race its 60-second timer.
  if(sequenceAutomationRunning){
    jsonLog('debug','sequence_automation_cycle_skipped',{reason:'local_cycle_in_progress'});
    return;
  }
  // SBC_V6603_POLLING_LAYOUT_LOCK_GUARD: non-blocking distributed-lock contention path.
  sequenceAutomationRunning=true;
  let lease;
  try {
    // A competing process owns this cycle: do not wait in the worker and hold up
    // subsequent background work. The distributed lock remains authoritative.
    lease=await DISTRIBUTED_LOCK.acquire('automation-sequences',{ttlSeconds:120,waitMs:0});
  } catch(err) {
    sequenceAutomationRunning=false;
    jsonLog('warn','sequence_automation_cycle_skipped',{reason:'lock_acquire_error',message:String(err&&err.message||err).slice(0,180)});
    return;
  }
  if(!lease.acquired){
    sequenceAutomationRunning=false;
    const nowMs=Date.now();
    if(nowMs-(global.__SBC_LAST_SEQUENCE_LOCK_SKIP_LOG||0)>300000){
      global.__SBC_LAST_SEQUENCE_LOCK_SKIP_LOG=nowMs;
      jsonLog('debug','sequence_automation_cycle_skipped',{reason:'distributed_lock_busy',note:'Another process holds the lock; no work was executed.'});
    }
    return;
  }
  try {
  const nowMs=Date.now(); let changed=false;
  for(const e of db.sequenceEnrollments||[]){
    if(e.status!=='Active'||!e.nextStepAt||new Date(e.nextStepAt)>new Date()) continue;
    const seq=db.sequences.find(x=>x.id===e.sequenceId), c=db.customers.find(x=>x.id===e.customerId);
    if(!seq||!c){e.status='Stopped';changed=true;continue;}
    if(['Customer','Lost'].includes(c.status)){e.status='Stopped';e.stoppedReason=`Lead became ${c.status}`;e.updatedAt=now();changed=true;continue;}
    const step=seq.steps?.[Number(e.currentStep)||0];
    if(!step){e.status='Completed';e.updatedAt=now();changed=true;continue;}
    try{
      if(step.channel==='Email') await sendEmail(c,step.subject||'Following up with you',step.body||'');
      else if(step.channel==='SMS') await sendSms(c,step.body||step.subject||'');
      else addActivity(step.channel==='Call'?'call':'task',`${step.channel} follow-up: ${step.body||step.subject||'Follow up'}`,{customerId:c.id,sequenceId:seq.id});
      e.currentStep=(Number(e.currentStep)||0)+1;
      const next=seq.steps[e.currentStep];
      if(next){e.nextStepAt=new Date(new Date(e.startedAt).getTime()+Number(next.day||0)*864e5).toISOString();}
      else {e.status='Completed';e.nextStepAt='';}
      e.lastProcessedAt=now();e.updatedAt=now();changed=true;
    }catch(err){
      e.lastError=err.message;e.lastAttemptAt=now();e.retryCount=(e.retryCount||0)+1;e.nextStepAt=new Date(Date.now()+6*3600000).toISOString();changed=true;
      addActivity('automation_error',`Automation paused for ${c.businessName||c.contactName}: ${err.message}`,{customerId:c.id,sequenceId:seq.id});
    }
  }
  if(changed) try{await saveData()}catch(err){console.error('Sequence save:',err.message)}
  } finally {
    try{await lease.release();}finally{sequenceAutomationRunning=false;}
  }
}

