const webLeadHits=new Map();
function webLeadRateLimit(ip){const key=String(ip||'unknown'),nowMs=Date.now(),arr=(webLeadHits.get(key)||[]).filter(t=>nowMs-t<60000);if(arr.length>=12)return false;arr.push(nowMs);webLeadHits.set(key,arr);return true}
