function SBC_V6649_ERROR_STATUS(e){const c=String(e?.code||e?.message||'');return c==='SBC_F4_PERSISTENCE_NOT_READY'?423:c==='TENANT_CONTEXT_REQUIRED'?403:/MYSQL_RELATIONAL_COMMIT_FAILED|MYSQL_RECOVERY/.test(c)?503:400;}
