async function runFantastic4AutonomousSweep(){
  const out=AUTONOMOUS.sweep(db.fantastic4,db,{limit:50});
  // Payment events hand off to the existing GodKim fulfillment path. The marker prevents duplicate orchestration.
  for(const evt of (db.fantastic4.autonomous?.events||[]).filter(e=>e.trigger==='payment.verified' && e.source==='autonomous_sweep').slice(0,10)){
    const orderId=String(evt.payload?.orderId||'');
    const order=(db.orders||[]).find(o=>String(o.id)===orderId);
    if(!order || order.__f4AutonomousLaunchId) continue;
    if(typeof GOD_KIM?.orchestrate!=='function') continue;
    try{
      const result=await GOD_KIM.orchestrate({order,requestUser:{id:'f4-autonomous',name:'Fantastic 4 Autonomous Engine'},createFulfillmentJobsForOrder,processReadyFulfillmentJobs,vendorCapabilities,addActivity,audit,saveData,db,catalog:CATALOG,sendCustomerStatus:async(order,msg)=>{const c=(db.customers||[]).find(x=>x.id===order.customerId);if(c&&c.email)return sendEmail(c,msg.subject,msg.body);return {sent:false};},testMode:false});
      order.__f4AutonomousLaunchId=evt.id; order.__f4AutonomousLaunchAt=new Date().toISOString(); order.__f4AutonomousKimResult={ok:Boolean(result?.ok),stage:result?.stage||'',traceId:result?.traceId||''};
      addActivity('f4_autonomous_order_launch',`Fantastic 4 autonomously launched fulfillment for ${order.id}`,{orderId:order.id,traceId:result?.traceId||''});
      try{await OFFICE_BOX_BRIDGE.dispatch({schema:'sbc.autonomy.v1',correlationId:result?.traceId||evt.id,eventType:'fulfillment.autonomous_started',tenantId:order.customerId||null,orderId:order.id,action:'fulfillment_start',risk:'normal',requiresHuman:false,payload:{stage:result?.stage||'fulfillment'},source:'command-center'});}catch(e){addActivity('office_box_bridge_error',`Office Box bridge unavailable for ${order.id}: ${e.message}`,{orderId:order.id});}
    }catch(e){
      F4.alert(db.fantastic4,{severity:'HIGH',type:'autonomous_fulfillment',message:`Autonomous fulfillment escalation: ${e.message}`,orderId});
      addActivity('f4_autonomous_fulfillment_error',`Fantastic 4 autonomous fulfillment stopped for ${order.id}: ${e.message}`,{orderId:order.id});
    }
  }
  return out;
}

