app.post('/api/v462/webhooks/:provider',async(req,res)=>{
  const provider=String(req.params.provider||'unknown').toLowerCase().replace(/[^a-z0-9_-]/g,'-');
  const envKey=`SBC_V460_WEBHOOK_SECRET_${provider.toUpperCase().replace(/[^A-Z0-9]/g,'_')}`;
  const secret=process.env[envKey]||process.env.SBC_WEBHOOK_SECRET||'';
  const timestamp=req.get('x-sbc-timestamp')||req.get('x-webhook-timestamp')||'';
  const nonce=req.get('x-sbc-nonce')||req.get('x-webhook-nonce')||'';
  const signature=req.get('x-sbc-signature')||req.get('x-webhook-signature')||'';
  const check=V462_INFRA.verifyHmac({rawBody:req.rawBody||Buffer.from(JSON.stringify(req.body||{})),signature,secret,timestamp,nonce});
  if(!check.ok)return res.status(401).json({ok:false,error:'Webhook authentication failed.',reason:check.reason});
  const result=await V462_INFRA.publishEvent(`webhook.${provider}`,{provider,body:req.body||{},receivedAt:new Date().toISOString()},{idempotencyKey:req.get('x-idempotency-key')||undefined});
  if(!result.accepted)return res.status(503).json({ok:false,error:'Durable event queue unavailable.'});
  res.status(202).json({ok:true,accepted:true,eventId:result.eventId,backend:result.backend});
});

app.post('/api/v462/events',auth,async(req,res)=>{
  const topic=String(req.body?.topic||'').trim();
  if(!topic)return res.status(400).json({ok:false,error:'topic is required'});
  const permit=V462_INFRA.backgroundPermit({cost:String(req.body?.cost||'normal')});
  if(!permit.allowed)return res.status(429).json({ok:false,error:'Background work throttled.',retryAfterMs:permit.delayMs,reason:permit.reason});
  const result=await V462_INFRA.publishEvent(topic,req.body?.payload||{});
  if(!result.accepted)return res.status(503).json({ok:false,error:'Durable event queue unavailable.'});
  res.status(202).json({ok:true,...result});
});

// ===== V32.1.7 SUPER CLEAN OPERATIONS — GoDaddy-compatible reliability layer =====
const HEALTH_VENDOR_CACHE = {updatedAt:0, results:[]};
function configuredHealthTargets(){
  const raw=String(process.env.SBC_HEALTH_VENDOR_URLS||'').trim();
  if(!raw)return [];
  try{
    const parsed=JSON.parse(raw);
    if(Array.isArray(parsed)) return parsed.map((x,i)=>typeof x==='string'?{name:`vendor-${i+1}`,url:x}:x).filter(x=>x?.url);
  }catch{}
  return raw.split(',').map((url,i)=>({name:`vendor-${i+1}`,url:url.trim()})).filter(x=>x.url);
}
async function probeHealthTargets(){
  const targets=configuredHealthTargets();
  const results=await Promise.all(targets.slice(0,20).map(async target=>{
    const started=Date.now();
    try{
      const r=await fetch(String(target.url),{method:'GET',headers:{'User-Agent':'SBC-Health-Probe/43.2.3'},signal:AbortSignal.timeout(Math.max(500,Math.min(10000,Number(process.env.SBC_HEALTH_TIMEOUT_MS||3000))))});
      return {name:String(target.name||target.url),url:String(target.url),status:r.status,ok:r.ok,latencyMs:Date.now()-started,checkedAt:now()};
    }catch(e){return {name:String(target.name||target.url),url:String(target.url),status:0,ok:false,latencyMs:Date.now()-started,error:String(e.message||e).slice(0,240),checkedAt:now()};}
  }));
  HEALTH_VENDOR_CACHE.updatedAt=Date.now();HEALTH_VENDOR_CACHE.results=results;return results;
}
app.get('/api/health/vendors',auth,async(req,res)=>{
  const refresh=String(req.query.refresh||'')==='1';
  if(refresh||Date.now()-HEALTH_VENDOR_CACHE.updatedAt>30000) await probeHealthTargets();
  const results=HEALTH_VENDOR_CACHE.results;
  res.json({ok:results.every(x=>x.ok),version:BUILD_VERSION,generatedAt:now(),targetsConfigured:configuredHealthTargets().length,results,latencyProfiles:results.map(x=>({name:x.name,latencyMs:x.latencyMs,ok:x.ok,status:x.status}))});
});
