// Optional external log shipping. Disabled unless an HTTPS endpoint is explicitly configured.
const LOG_SHIPPER={queue:[],sending:false};
async function shipOperationalLog(rec){
  const endpoint=String(process.env.SBC_LOG_SHIP_URL||'').trim();if(!endpoint||!/^https:\/\//i.test(endpoint))return false;
  LOG_SHIPPER.queue.push(rec);if(LOG_SHIPPER.queue.length>1000)LOG_SHIPPER.queue.shift();if(LOG_SHIPPER.sending)return true;
  LOG_SHIPPER.sending=true;
  try{const batch=LOG_SHIPPER.queue.splice(0,25);const r=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json','X-SBC-Log-Key':String(process.env.SBC_LOG_SHIP_KEY||'')},body:JSON.stringify({source:'sbc-command-center',version:BUILD_VERSION,events:batch}),signal:AbortSignal.timeout(5000)});if(!r.ok)LOG_SHIPPER.queue.unshift(...batch);return r.ok}catch{LOG_SHIPPER.queue.unshift(...batch);return false}finally{LOG_SHIPPER.sending=false;}
}

