function liveObservabilityProbe(){
  const nowMs=Date.now();
  const recent=Array.isArray(global.__SBC_RECENT_RUNTIME_EVENTS)?global.__SBC_RECENT_RUNTIME_EVENTS:[];
  const windowMs=Math.max(60000,Math.min(3600000,Number(process.env.SBC_OBS_HEALTH_WINDOW_MS||900000)));
  const events=recent.filter(x=>nowMs-new Date(x.timestamp||0).getTime()<=windowMs);
  const slow=events.filter(x=>x.event==='slow_request');
  const errors=events.filter(x=>Number(x.status||0)>=500 || String(x.level||'').toUpperCase()==='ERROR');
  return {windowMs,eventCount:events.length,slowRequests:slow.length,errors:errors.length,healthy:errors.length===0,source:'in-process runtime telemetry'};
}
