// Demo retention: hourly cleanup of generated local sandbox artifacts older than the configured retention period.
async function cleanupExpiredDemoArtifacts(){
  const days=Math.max(1,Math.min(365,Number(process.env.SBC_DEMO_RETENTION_DAYS||14)));const cutoff=Date.now()-days*86400000;
  const root=path.join(DATA_DIR,'demo-sandbox');let removed=0;
  if(fs.existsSync(root)) for(const file of fs.readdirSync(root)){const full=path.join(root,file);try{const st=fs.statSync(full);if(st.isFile()&&st.mtimeMs<cutoff){fs.rmSync(full,{force:true});removed++;}}catch{}}
  const m=megaData();let archived=0;m.websiteDemos=m.websiteDemos.map(d=>{if(!d.archived&&new Date(d.createdAt||0).getTime()<cutoff){archived++;return {...d,archived:true,archivedAt:now(),archiveReason:`${days}-day demo retention`};}return d;});
  if(removed||archived)await megaSave(m);return {days,removed,archived};
}

// Graceful shutdown for GoDaddy/Node restarts; no PM2/Docker dependency is required.
let sbcHttpServer=null;let sbcShutdownStarted=false;let sbcBackgroundTimers=[];
async function gracefulShutdown(signal='SIGTERM'){
  if(sbcShutdownStarted)return;sbcShutdownStarted=true;
  try{RUNTIME_HARDENING.beginShutdown();}catch{}
  console.log(`[SBC SHUTDOWN] ${signal} received; draining active work.`);
  for(const t of sbcBackgroundTimers)try{clearInterval(t)}catch{}
  try{if(mysqlKeepaliveTimer)clearInterval(mysqlKeepaliveTimer)}catch{}
  mysqlKeepaliveTimer=null;
  const deadline=Date.now()+Math.max(1000,Math.min(15000,Number(process.env.SBC_SHUTDOWN_DRAIN_MS||10000)));
  while(Date.now()<deadline){const jobs=megaData().fulfillmentJobs||[];const active=jobs.filter(j=>['processing','claimed'].includes(String(j.status||'').toLowerCase()));if(!active.length)break;await new Promise(r=>setTimeout(r,250));}
  try{if(global.__SBC_WSS)global.__SBC_WSS.close()}catch{}
  try{if(sbcHttpServer)await new Promise(resolve=>sbcHttpServer.close(()=>resolve()))}catch{}
  try{await RUNTIME_HARDENING.waitForRequests(Math.max(0,Math.min(5000,Number(process.env.SBC_SHUTDOWN_REQUEST_DRAIN_MS||5000))))}catch{}
  // A shutdown race previously allowed mysqlPool.end() to win against an in-flight
  // saveData() transaction. Finish the existing snapshot before closing MySQL.
  try{if(saveDataInFlight)await saveDataInFlight}catch(e){console.warn('[SBC SHUTDOWN] pending save flush:',e?.message||e)}
  try{if(sessionMysqlPool)await sessionMysqlPool.end()}catch{}
  try{if(mysqlPool)await mysqlPool.end()}catch{}
  try{if(redisClient?.quit)await redisClient.quit()}catch{}
  console.log('[SBC SHUTDOWN] clean shutdown complete.');process.exit(0);
}
process.once('SIGINT',()=>gracefulShutdown('SIGINT'));process.once('SIGTERM',()=>gracefulShutdown('SIGTERM'));


