app.post('/api/kim/fabric/action-policy',auth,(req,res)=>res.json({ok:true,action:String(req.body?.action||''),policy:KIM_AI_FABRIC.actionPolicy(req.body?.action,req.user?.role)}));
app.post('/api/kim/fabric/agent-plan',auth,async(req,res)=>{
  const request=String(req.body?.request||'').slice(0,4000);
  const classified=KIM_AI_FABRIC.intent(request);
  const proposed=[
    classified.intent==='payment'?'review_payment_context':
    classified.intent==='fulfillment'?'inspect_fulfillment_status':
    classified.intent==='sales'?'prepare_sales_context':
    classified.intent==='appointment'?'prepare_schedule_options':'summarize_request'
  ];
  const policies=proposed.map(action=>({action,policy:KIM_AI_FABRIC.actionPolicy(action,req.user?.role)}));
  res.json({ok:true,mode:'bounded_autonomy',request:KIM_AI_FABRIC.mask({request}),intent:classified,proposedActions:policies,requiresHuman:policies.some(x=>!x.policy.allowed)});
});

app.get('/api/enterprise/global-readiness',auth,(req,res)=>{if(!['owner','manager'].includes(req.user.role))return res.status(403).json({error:'Enterprise architecture oversight is restricted to management.'});res.json({ok:true,version:BUILD_VERSION,architectureVersion:ARCHITECTURE_VERSION,readiness:GLOBAL_READINESS.readiness(process.env),enterprise:enterpriseReadiness()});});


// ===== V32.6.0 KIM OPERATING SYSTEM =====
// Operational expansion: production telemetry, preflight, DTF optimization, vendor routing,
// lead intelligence, workforce separation, audit-chain telemetry and infrastructure readiness.
function kim326Store(){const m=megaData();return KIM326.ensure(m)}
function kim326Allowed(req,area){return KIM326.can(req.user?.role,area)}
function kim326Guard(area){return (req,res,next)=>{if(!kim326Allowed(req,area))return res.status(403).json({error:`Kim OS capability denied: ${area}`});next()}}
function kim326ProductionRows(m){return (m.productionPipeline||[]).map(p=>{const d=kim326Store();if(!d.stageHistory.some(x=>x.productionId===p.id)){d.stageHistory.push({id:KIM326.id('stage'),productionId:p.id,orderId:p.orderId,from:'',to:KIM326.normalizeStage(p.stage),at:p.createdAt||now(),actorId:'migration',actorName:'SBC V32.6 migration'})}p.stage=KIM326.normalizeStage(p.stage);return {...p,telemetry:KIM326.stageTelemetry(d,p),overdue:KIM326.overdue(d,p)}})}

app.get('/api/kim/ops326/readiness',auth,kim326Guard('telemetry'),async(req,res)=>{
  const m=v24ProductionStore();v24EnsurePipelineForPaidOrders(m);const d=kim326Store();const rows=kim326ProductionRows(m);const jobs=m.fulfillmentJobs||[];
  const customers=db.customers||[];const leads=customers.filter(c=>String(c.status||'').toLowerCase()==='lead');
  const overdueJobs=rows.filter(x=>x.overdue).length;const cpu=process.cpuUsage();
  res.json({ok:true,version:KIM326.VERSION,slogan:'Run the business. Don\'t just chase the business.',role:KIM326.roleCapabilities(req.user.role),protected:KIM326.capabilities().protected,production:{stages:KIM326.STAGES,counts:Object.fromEntries(KIM326.STAGES.map(s=>[s,rows.filter(x=>x.stage===s).length])),overdue4h:overdueJobs,rows:rows.slice(0,200)},leads:{raw:leads.length,verified:leads.filter(x=>x.emailVerified).length,elite:leads.filter(x=>x.leadTier==='Elite Target').length},vendors:d.vendorHealth,telemetry:{latency:d.latency.slice(0,100),cpu:{user:cpu.user,system:cpu.system},uptimeSeconds:Math.floor(process.uptime())},trl:{current:Number(process.env.SBC_TRL||8.5),target:9},blueGreen:d.blueGreen,features:KIM326.capabilities().features,featureMatrix:KIM326.FEATURE_MATRIX});
});

app.get('/api/kim/ops326/production',auth,kim326Guard('production'),async(req,res)=>{const m=v24ProductionStore();v24EnsurePipelineForPaidOrders(m);const d=kim326Store();const rows=kim326ProductionRows(m);await megaSave(m);res.json({ok:true,stages:KIM326.STAGES,rows})});
app.patch('/api/kim/ops326/production/:id',auth,kim326Guard('production'),async(req,res)=>{const m=v24ProductionStore();const d=kim326Store();const p=m.productionPipeline.find(x=>x.id===req.params.id);if(!p)return res.status(404).json({error:'Production record not found.'});const next=req.body?.stage?KIM326.normalizeStage(req.body.stage):KIM326.normalizeStage(p.stage);if(next!==KIM326.normalizeStage(p.stage))KIM326.recordStage(d,p,next,req.user);if(req.body?.notes!==undefined)p.notes=String(req.body.notes||'').slice(0,4000);if(req.body?.blockedReason!==undefined)p.blockedReason=String(req.body.blockedReason||'').slice(0,1000);p.updatedAt=now();await megaSave(m);audit(req.user,'kim326_production_update',`Kim OS moved ${p.orderNumber||p.id} to ${p.stage}`,{productionId:p.id,stage:p.stage});res.json({...p,telemetry:KIM326.stageTelemetry(d,p),overdue:KIM326.overdue(d,p)})});
app.post('/api/kim/ops326/production/bulk-status',auth,kim326Guard('production'),async(req,res)=>{const ids=Array.isArray(req.body?.ids)?req.body.ids.map(String):[];const next=KIM326.normalizeStage(req.body?.stage);if(!ids.length)return res.status(400).json({error:'ids are required.'});const m=v24ProductionStore(),d=kim326Store(),updated=[],errors=[];for(const pid of ids){const p=m.productionPipeline.find(x=>String(x.id)===pid);if(!p){errors.push({id:pid,error:'not found'});continue}try{if(next!==KIM326.normalizeStage(p.stage))KIM326.recordStage(d,p,next,req.user);updated.push(p.id)}catch(e){errors.push({id:pid,error:e.message})}}await megaSave(m);audit(req.user,'kim326_bulk_status',`Bulk moved ${updated.length} production records to ${next}`,{ids:updated,errors});res.json({ok:errors.length===0,updated,errors})});

app.post('/api/kim/ops326/preflight',auth,kim326Guard('production'),(req,res)=>{try{const b=Buffer.from(String(req.body?.dataBase64||'').replace(/^data:[^;]+;base64,/,'') ,'base64');if(!b.length)return res.status(400).json({error:'dataBase64 is required.'});res.json({ok:true,preflight:KIM326.rasterPreflight(b,req.body?.mime,req.body?.physicalWidthIn,req.body?.physicalHeightIn)})}catch(e){res.status(400).json({error:e.message})}});
app.post('/api/kim/ops326/dtf-optimize',auth,kim326Guard('production'),(req,res)=>res.json({ok:true,optimization:KIM326.optimizeDtf(Array.isArray(req.body?.items)?req.body.items:[],req.body?.sheetWidth||22,req.body?.sheetHeight||60,req.body?.gap||.15)}));
app.post('/api/kim/ops326/proof',auth,kim326Guard('production'),(req,res)=>res.json({ok:true,html:KIM326.proofHtml(req.body?.production||{},req.body?.brand||{})}));
app.post('/api/kim/ops326/asset-lock',auth,kim326Guard('production'),async(req,res)=>{const m=v24ProductionStore();const d=kim326Store();const p=m.productionPipeline.find(x=>x.id===req.body?.productionId);const a=m.productionArtwork.find(x=>x.id===req.body?.artworkId);if(!p||!a)return res.status(404).json({error:'Production or artwork not found.'});if(a.lockedHash)return res.status(409).json({error:'Asset is already locked.'});const data=Buffer.from(a.dataBase64||'','base64');a.sha256=crypto.createHash('sha256').update(data).digest('hex');a.lockedHash=a.sha256;a.lockedAt=now();a.lockedBy=req.user.id;a.immutable=true;d.assetVault.unshift({id:KIM326.id('vault'),productionId:p.id,artworkId:a.id,sha256:a.sha256,sessionId:req.session?.id||'',lockedAt:a.lockedAt,lockedBy:req.user.id,mode:'content-addressed-immutable'});await megaSave(m);audit(req.user,'kim326_asset_locked',`Locked approved asset ${a.name}`,{productionId:p.id,artworkId:a.id,sha256:a.sha256});res.json({ok:true,asset:{id:a.id,name:a.name,sha256:a.sha256,lockedAt:a.lockedAt,immutable:true}})});
app.get('/api/kim/ops326/asset-vault',auth,kim326Guard('production'),(req,res)=>{const d=kim326Store();res.json({ok:true,mode:'content-addressed-immutable',items:d.assetVault.slice(0,200)})});
app.post('/api/kim/ops326/shipping-webhook',async(req,res)=>{const secret=String(process.env.SBC_SHIPPING_WEBHOOK_SECRET||'');const sig=String(req.get('x-sbc-signature')||'');const body=JSON.stringify(req.body||{});if(!secret)return res.status(503).json({ok:false,error:'shipping_webhook_secret_not_configured'});const expected=crypto.createHmac('sha256',secret).update(body).digest('hex');const sigBytes=Buffer.from(sig),expectedBytes=Buffer.from(expected);if(!sig||sigBytes.length!==expectedBytes.length||!crypto.timingSafeEqual(sigBytes,expectedBytes))return res.status(401).json({error:'Invalid webhook signature.'});const m=megaData();const d=kim326Store();const job=m.fulfillmentJobs.find(x=>String(x.id)===String(req.body?.jobId));if(!job)return res.status(404).json({error:'Fulfillment job not found.'});job.trackingNumber=String(req.body?.trackingNumber||job.trackingNumber||'');job.vendorStatus=String(req.body?.status||'tracking_update');if(['delivered','fulfilled','completed','complete'].includes(String(req.body?.status||'').toLowerCase()))job.status=String(req.body.status).toLowerCase();job.updatedAt=now();syncOrderFulfillmentLifecycle(job.orderId);d.vendorEvents.unshift({id:KIM326.id('ship'),jobId:job.id,status:job.vendorStatus,trackingNumber:job.trackingNumber,at:now()});await megaSave(m);res.json({ok:true,jobId:job.id,status:job.vendorStatus,trackingNumber:job.trackingNumber})});
app.get('/api/kim/ops326/vendor-health',auth,kim326Guard('vendors'),(req,res)=>{const names=['4over4','VistaPrint','GoDaddy','Square','Twilio','Email','OpenAI'];const out={};for(const n of names){const env=n==='4over4'?Boolean(secretValue('FOUROVER4_API_KEY','FOUROVER4_API_KEY')):n==='VistaPrint'?Boolean(secretValue('VISTAPRINT_API_KEY','VISTAPRINT_API_KEY')):n==='GoDaddy'?Boolean(secretValue('GODADDY_PAT','GODADDY_PAT')):n==='Square'?squareConfigured():n==='Twilio'?Boolean(process.env.TWILIO_ACCOUNT_SID&&process.env.TWILIO_AUTH_TOKEN):n==='Email'?Boolean(process.env.SBC_SMTP_HOST):Boolean(process.env.OPENAI_API_KEY);out[n]={configured:env,status:env?'READY':'STANDBY',checkedAt:now()}}res.json({ok:true,providers:out})});
