// Login hardening: these helpers are intentionally idempotent. A missing helper must
// never turn the entire authentication route into a runtime ReferenceError.
// V32.1.3 credential hardening: scrypt-backed employee/demo passwords.
// Owner authentication remains environment-secret based and is intentionally untouched.
function hashPassword(password){
  const salt=crypto.randomBytes(16).toString('hex');
  const key=crypto.scryptSync(String(password||''),salt,64,{N:16384,r:8,p:1});
  return `scrypt$${salt}$${key.toString('hex')}`;
}
function verifyPassword(password,encoded){
  try{
    const parts=String(encoded||'').split('$');
    if(parts.length!==3||parts[0]!=='scrypt')return false;
    const salt=parts[1],expected=Buffer.from(parts[2],'hex');
    const actual=crypto.scryptSync(String(password||''),salt,expected.length,{N:16384,r:8,p:1});
    return expected.length===actual.length&&crypto.timingSafeEqual(expected,actual);
  }catch{return false}
}
