const LEAD_INTELLIGENCE_DEFAULTS={
  opportunityType:'Unclassified',bookingPlatform:'',leadTemperature:'Cold',verificationStatus:'Unverified',
  salesReady:false,verificationNotes:'',recommendedPackage:'',outreachStatus:'Not Contacted',
  lastContacted:'',nextFollowUp:'',assignedRep:'',revenuePlayStatus:'Held',estimatedDealValue:0,
  customerStatus:'Prospect',decisionMakerVerified:false,sourceResearchNotes:''
};
function leadIntel(c){
  c.leadIntelligence=(c.leadIntelligence&&typeof c.leadIntelligence==='object')?c.leadIntelligence:{};
  c.leadIntelligence={...LEAD_INTELLIGENCE_DEFAULTS,...c.leadIntelligence};
  return c.leadIntelligence;
}
function normalizeLeadIntelligence(c){
  const li=leadIntel(c);
  li.salesReady=Boolean(li.salesReady);
  li.estimatedDealValue=Math.max(0,Number(li.estimatedDealValue||0)||0);
  return li;
}
function durableWorkforceUser(u){
  if(!u||!u.username||String(u.username).toLowerCase()==='owner'||String(u.role)==='demo')return;
  u.updatedAt=u.updatedAt||now();
  // The password hash is preserved unless an explicit password change occurs.
  return u;
}
async function persistWorkforceIdentity(u){
  if(typeof MYSQL_RECOVERY_REQUIRED!=='undefined' && MYSQL_RECOVERY_REQUIRED) return;
  if(typeof MYSQL_RECOVERY_EVALUATED!=='undefined' && !MYSQL_RECOVERY_EVALUATED) return;
  if(!mysqlPool||!u||!u.username)return;
  await mysqlPool.query(`INSERT INTO sbc_workforce_users(id,tenant_id,username,name,email,role,active,must_change_password,password_hash,expires_at,created_at,updated_at)
    VALUES (?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE
    name=VALUES(name),email=VALUES(email),role=VALUES(role),active=VALUES(active),
    must_change_password=VALUES(must_change_password),password_hash=IF(VALUES(password_hash)='',password_hash,VALUES(password_hash)),
    expires_at=VALUES(expires_at),updated_at=VALUES(updated_at)`,
    [u.id,u.tenantId||TENANT_DEFAULT_ID,u.username,u.name||'',u.email||u.profile?.email||'',u.role||'caller',u.active===false?0:1,u.mustChangePassword?1:0,u.passwordHash||'',u.expiresAt||null,sqlDateTime(u.createdAt||now()),sqlDateTime(u.updatedAt||now())]);
}
function restoreDurableWorkforceIdentity(u){
  if(!u||!u.username)return u;
  // If a deployment package contains a stale seeded hash, never overwrite a real
  // persisted password. MySQL rehydration is authoritative when available.
  return u;
}
