const V6620_LEGACY_CRM=require('./enterprise/v6620-legacy-crm-tenant-guard.cjs');
app.post('/api/customers',auth,ownerOnly,async(req,res)=>{if(SBC_RUNTIME_READ_ONLY||sbcShutdownStarted||!mysqlPool||!MYSQL_RECOVERY_EVALUATED)return res.status(423).json({ok:false,error:'CRM_RELATIONAL_WRITER_UNAVAILABLE',readOnly:true});if(MYSQL_RECOVERY_REQUIRED)return res.status(423).json({ok:false,error:'MYSQL_RECOVERY_REQUIRED',readOnly:true,message:'CRM writes are disabled until authoritative MySQL recovery is complete.'});const b=req.body||{};if(!b.businessName&&!b.contactName)return res.status(400).json({error:'Business or contact name is required.'});const candidate={businessName:String(b.businessName||'').trim(),contactName:String(b.contactName||'').trim(),phone:String(b.phone||'').trim(),email:String(b.email||'').trim(),city:String(b.city||'').trim()};const dup=leadDuplicateMatches(candidate).filter(m=>V6620_LEGACY_CRM.owns(m.customer,requireRequestTenant(req)));if(dup.length)return res.status(409).json({error:'Possible duplicate lead already exists.',duplicate:true,matches:dup.slice(0,5).map(x=>({id:x.customer.id,businessName:x.customer.businessName,phone:x.customer.phone,email:x.customer.email,reasons:x.reasons}))});const c={id:id('cust'),tenantId:requireRequestTenant(req),...candidate,status:b.status||'Lead',source:String(b.source||'Walk-in'),followUp:b.followUp||'',notes:String(b.notes||''),assignedTo:String(b.assignedTo||''),website:String(b.website||''),address:String(b.address||''),industry:String(b.industry||''),createdAt:now(),updatedAt:now()};normalizeLeadQuality(c);db.customers.unshift(c);addActivity('customer',`Added ${c.businessName||c.contactName}`,{customerId:c.id});audit(req.user,'customer_created',`Created ${c.businessName||c.contactName}`,{customerId:c.id});try{await saveData();}catch(error){console.error('[SBC LEGACY CRM] MySQL persistence rejected',error?.code||'MYSQL_WRITE_FAILED');return res.status(503).json({ok:false,error:'CRM_RELATIONAL_COMMIT_FAILED',retryable:true});}res.status(201).json(c)});
