// V25 Sales Order Builder / fulfillment handoff
const V25_BUNDLES={
 starter:{id:'starter',name:'SBC Business Starter',price:199,officeBoxEntitlement:'upgrade',componentIds:['website','domain','hosting','cards100','launch'],paymentUrl:PAYMENT_LINKS.starter},
 essentials:{id:'essentials',name:'Business Essentials',price:349,officeBoxEntitlement:'preferred-upgrade',componentIds:['website','domain','hosting','cards200','form','seo_basic','launch'],paymentUrl:PAYMENT_LINKS.basic},
 professional:{id:'professional',name:'SBC Complete Business Launch',price:699,officeBoxEntitlement:'included-foundation',componentIds:['website','domain','domainprotection','wp','m365setup','ssl','cards500','launch'],paymentUrl:''}
};
function v25BundleMatch(ids){const set=new Set(ids);return Object.values(V25_BUNDLES).find(b=>b.componentIds.every(x=>set.has(x)))||null}
function v25OrderItems(items){return Array.isArray(items)?items.map(x=>({id:String(x.id||''),name:String(x.name||'Item'),qty:Math.max(1,Number(x.qty||1)),unitPrice:Math.max(0,Number(x.unitPrice||0)),category:String(x.category||''),paymentUrl:String(x.paymentUrl||'')})).filter(x=>x.id&&x.name):[]}
function v25SalesAccess(req,res,next){if(['owner','manager','caller'].includes(req.user?.role))return next();return res.status(403).json({error:'Sales order access required.'})}
function squareBuyerPreflight(customer){
  const raw=String(customer?.phone||'').trim();
  const normalized=normalizeBuyerPhone(raw);
  const email=String(customer?.email||'').trim().toLowerCase();
  const checks=[
    {name:'email',ok:!email||/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email),detail:email?'Email shape is valid.':'Email not supplied; Square checkout can still be generated.'},
    {name:'phone',ok:!raw||Boolean(normalized),detail:!raw?'Phone not supplied; it will not be pre-populated.':normalized?`Phone normalized to ${normalized}.`:'Phone is not a supported E.164/10-digit/11-digit US format.'}
  ];
  return {ok:checks.every(x=>x.ok),rawPhone:raw,normalizedPhone:normalized||'',checks,provider:'Square',note:'Local preflight only; no Square request or charge is made.'};
}
app.post('/api/kim/square/preflight',auth,ownerOnly,(req,res)=>{res.json({ok:true,version:BUILD_VERSION,preflight:squareBuyerPreflight(req.body||{})});});
app.post('/api/sales-orders',auth,v25SalesAccess,FINANCIAL_GOVERNOR.middleware('sales_order'),async(req,res)=>{const tenantId=requireRequestTenant(req);const b=req.body||{},items=v25OrderItems(b.items);if(!String(b.customerName||'').trim())return res.status(400).json({error:'Customer name is required.'});if(!String(b.customerEmail||'').trim()||!String(b.customerPhone||'').trim())return res.status(400).json({error:'Customer email and phone are required before checkout.'});if(!items.length)return res.status(400).json({error:'Add at least one service or package.'});const subtotal=totals(items),discount=Math.max(0,Number(b.discount||0)),taxRate=Math.max(0,Number(b.taxRate??db.settings.taxRate??0)),tax=Math.max(0,subtotal-discount)*taxRate/100,total=Math.max(0,subtotal-discount)+tax;if(total<=0)return res.status(400).json({error:'Order total must be greater than $0.'});const bundle=v25BundleMatch(items.map(x=>x.id));const product=bundle?bundle.name:items.length===1?items[0].name:'Custom SBC Service Bundle';let customerId=String(b.customerId||'');let cust=customerId?db.customers.find(x=>x.id===customerId):null;if(cust&&Number(cust.tenantId)!==tenantId)return res.status(404).json({error:'Customer not found in the authenticated tenant.'});if(!cust){cust={id:id('cust'),tenantId,businessName:String(b.customerName).trim(),contactName:String(b.contactName||'').trim(),phone:String(b.customerPhone).trim(),email:String(b.customerEmail).trim().toLowerCase(),status:'Proposal',source:'Sales Order',createdAt:now(),updatedAt:now(),assignedTo:req.user.id};db.customers.unshift(cust);customerId=cust.id;}else{cust.phone=String(b.customerPhone).trim();cust.email=String(b.customerEmail).trim().toLowerCase();if(b.contactName!==undefined)cust.contactName=String(b.contactName||'').trim();cust.updatedAt=now();}const quoteId=String(b.quoteId||'');const o={id:id('ord'),tenantId,customerId:customerId,customerName:String(b.customerName).trim(),product,quantity:1,status:'New',cost:0,price:total,quoteId,notes:JSON.stringify({v25:true,quoteId,items,bundleId:bundle?.id||'',bundleName:bundle?.name||'',subtotal,discount,taxRate,tax,total,paymentStatus:'Pending',fulfillmentStatus:'Awaiting Customer Payment',salesRepId:req.user.id,salesRepName:req.user.name,createdAt:now()}),salesRepId:req.user.id,salesRepName:req.user.name,paymentUrl:'',paymentStatus:'Pending',fulfillmentStatus:'Awaiting Customer Payment',createdAt:now(),updatedAt:now()};db.orders.unshift(o);const orderCust=db.customers.find(x=>x.id===o.customerId);if(orderCust){orderCust.status='Proposal';orderCust.updatedAt=now();orderCust.dealValue=total;orderCust.assignedTo=orderCust.assignedTo||req.user.id;}addActivity('sales_order',`Created ${product} order for ${o.customerName}`,{orderId:o.id,customerId:o.customerId,total,salesRepId:req.user.id,bundleId:bundle?.id||'',quoteId});if(quoteId){const linkedQuote=db.quotes.find(x=>x.id===quoteId);if(linkedQuote){linkedQuote.updatedAt=now();addActivity('quote_checkout',`Quote ${linkedQuote.quoteNumber} moved into checkout for ${o.customerName}`,{quoteId,orderId:o.id,total});}}await saveData();
  let checkout=null;
  if(b.generatePaymentLink!==false){try{checkout=await createSquarePaymentLinkForOrder(o,req)}catch(e){return res.status(201).json({ok:true,order:o,bundle:bundle?{id:bundle.id,name:bundle.name,price:bundle.price}:null,paymentUrl:'',paymentStatus:'Pending',dynamicCheckoutError:e.message,squareConfigured:squareConfigured(),requiresManualPayment:true});}}
  res.status(201).json({ok:true,order:o,bundle:bundle?{id:bundle.id,name:bundle.name,price:bundle.price}:null,paymentUrl:checkout?.url||'',longUrl:checkout?.longUrl||'',paymentLinkId:checkout?.paymentLinkId||'',squareOrderId:checkout?.squareOrderId||'',paymentStatus:o.paymentStatus||'Pending',dynamicCheckout:true,requiresManualPayment:false});
});
const PUBLIC_CHECKOUT_RATE=new Map();
app.post('/api/public/checkout',async(req,res)=>{
  try{
    const ip=String(req.headers['x-forwarded-for']||req.socket.remoteAddress||'unknown').split(',')[0].trim();
    const nowMs=Date.now(), recent=PUBLIC_CHECKOUT_RATE.get(ip)||[]; const fresh=recent.filter(t=>nowMs-t<60000);
    if(fresh.length>=12)return res.status(429).json({error:'Too many checkout attempts. Please wait a minute and try again.'});
    fresh.push(nowMs);PUBLIC_CHECKOUT_RATE.set(ip,fresh);
    const b=req.body||{};
    if(String(b.website||'').trim())return res.status(400).json({error:'Invalid checkout request.'});
    const tenantId=requireMappedRequestTenant(req);
    const packageId=String(b.packageId||'').trim(); const pkg=CATALOG.packages.find(x=>String(x.id)===packageId);
    if(!pkg)return res.status(400).json({error:'Approved package not found.'});
    const name=String(b.customerName||b.businessName||'').trim(); const email=String(b.customerEmail||b.email||'').trim().toLowerCase(); const phone=normalizeBuyerPhone(b.customerPhone||b.phone);
    if(!name||!email||!phone)return res.status(400).json({error:'Business name, email and phone are required.'});
    // SBC_V6635_PUBLIC_CHECKOUT_PREFLIGHT: fail BEFORE creating customers/orders when Square or the writer is unavailable.
    if(SBC_RUNTIME_READ_ONLY||!MYSQL_RECOVERY_EVALUATED||MYSQL_RECOVERY_REQUIRED||!sbcWriterLeaseReady)return res.status(423).json({ok:false,code:'CHECKOUT_WRITER_LOCKED',error:'Checkout is temporarily unavailable. No customer or order was created.'});
    if(RUNTIME_GATE.blocked('NEW_CHECKOUTS'))return res.status(423).json({ok:false,code:'CHECKOUT_OWNER_PAUSED',error:'Owner has paused new checkouts. No customer or order was created.'});
    if(!squareConfigured())return res.status(503).json({ok:false,code:'SQUARE_NOT_CONFIGURED',error:'Secure checkout is not yet configured. No customer or order was created.'});
    // SBC_V6666_PUBLIC_SQUARE_ZERO_GHOST_PREFLIGHT: bounded cached GET; no customer/order until Square location is healthy.
    if(!squareWebhookConfigured())return res.status(503).json({ok:false,code:'SQUARE_WEBHOOK_NOT_CONFIGURED',error:'Secure checkout cannot confirm its payment webhook. No customer or order was created.'});
    let squareLocationProbe;
    try{squareLocationProbe=await SBC_SQUARE_LOCATION_PROBE({token:process.env.SQUARE_ACCESS_TOKEN,locationId:process.env.SQUARE_LOCATION_ID,environment:squareEnvironment(),apiVersion:SQUARE_API_VERSION});}
    catch(_){return res.status(503).json({ok:false,code:'SQUARE_PREFLIGHT_UNAVAILABLE',error:'Secure checkout temporarily unavailable. No customer or order was created.'});}
    if(!squareLocationProbe?.reachable)return res.status(503).json({ok:false,code:'SQUARE_PREFLIGHT_UNAVAILABLE',error:'Square location could not be verified. No customer or order was created.'});
    const c={id:id('cust'),tenantId,businessName:name,contactName:String(b.contactName||'').trim(),phone,email,status:'Proposal',source:'Public Checkout',createdAt:now(),updatedAt:now()}; db.customers.unshift(c);
    const items=[{id:pkg.id,name:pkg.name,qty:1,unitPrice:Number(pkg.price),category:pkg.category}];
    const o={id:id('ord'),tenantId,customerId:c.id,customerName:name,product:pkg.name,quantity:1,status:'New',cost:0,price:Number(pkg.price),notes:JSON.stringify({publicCheckout:true,items,bundleId:pkg.id,bundleName:pkg.name,subtotal:Number(pkg.price),discount:0,taxRate:0,tax:0,total:Number(pkg.price),paymentStatus:'Pending',fulfillmentStatus:'Awaiting Customer Payment',createdAt:now()}),salesRepId:'',salesRepName:'SBC Web Checkout',paymentUrl:'',paymentStatus:'Pending',fulfillmentStatus:'Awaiting Customer Payment',createdAt:now(),updatedAt:now()};
    db.orders.unshift(o); c.dealValue=o.price;
    addActivity('public_checkout',`Customer started checkout for ${pkg.name}`,{orderId:o.id,customerId:c.id,packageId:pkg.id,total:o.price});
    await saveData();
    let checkout;
    try{checkout=await createSquarePaymentLinkForOrder(o,{user:{id:'public-checkout',name:'SBC Web Checkout'}});}
    catch(linkError){
      // Unknown provider outcome: retain the pending record for reconciliation, never auto-retry.
      updateOrderParsed(o,{checkoutLinkStatus:'RECONCILIATION_REQUIRED',checkoutLinkFailureAt:now()});
      o.checkoutLinkStatus='RECONCILIATION_REQUIRED';
      o.fulfillmentStatus='Blocked — Payment Link Unconfirmed';
      addActivity('checkout_link_unconfirmed','Square payment link unconfirmed for order '+o.id,{orderId:o.id,tenantId:o.tenantId});
      await saveData();
      return res.status(503).json({ok:false,code:'SQUARE_LINK_UNCONFIRMED',orderId:o.id,recordedPendingOrder:true,automaticRetry:false,error:'The payment link could not be confirmed. An unpaid pending order was retained for owner reconciliation. Do not retry automatically.'});
    }
    res.status(201).json({ok:true,orderId:o.id,package:{id:pkg.id,name:pkg.name,price:pkg.price},paymentUrl:checkout.url,longUrl:checkout.longUrl||'',paymentLinkId:checkout.paymentLinkId,squareOrderId:checkout.squareOrderId,paymentStatus:'Pending',godKim:'armed_after_verified_square_payment'});
  }catch(e){res.status(400).json({ok:false,error:e.message||'Checkout could not be created.'});}
});

app.get('/api/sales-orders',auth,v25SalesAccess,(req,res)=>res.json((db.orders||[]).filter(o=>req.user.role==='owner'||req.user.role==='manager'||!o.salesRepId||o.salesRepId===req.user.id||req.user.role==='fulfillment').map(o=>({...o,parsed:o.notes&&o.notes.startsWith('{')?(()=>{try{return JSON.parse(o.notes)}catch{return {}}})():{}}))));

app.post('/api/owner/launch-qa/create-order',auth,ownerOnly,async(req,res)=>{
 res.setHeader('Cache-Control','no-store');
 if(SBC_RUNTIME_READ_ONLY||sbcShutdownStarted||!mysqlPool||
    !MYSQL_RECOVERY_EVALUATED||MYSQL_RECOVERY_REQUIRED||!sbcWriterLeaseReady||
    RUNTIME_GATE.blocked('NEW_CHECKOUTS'))
  return res.status(423).json({ok:false,code:'LAUNCH_QA_WRITER_OR_CHECKOUT_LOCKED'});
 let tenantId;
 try{tenantId=requireRequestTenant(req)}catch(_){
  return res.status(403).json({ok:false,code:'LAUNCH_QA_TENANT_REQUIRED'});
 }
 const email=String(req.body?.email||'').trim().toLowerCase();
 if(email.length>254||!/^\S+@\S+\.\S+$/.test(email)||
    email.endsWith('.invalid')||email.endsWith('.test'))
  return res.status(400).json({ok:false,code:'LAUNCH_QA_CONTROLLED_EMAIL_REQUIRED'});
 // One test per tenant and owner-provided email: cannot accidentally mint
 // another charge by retrying after an ambiguous response.
 const existing=(db.orders||[]).find(o=>Number(o.tenantId)===tenantId&&
  String(o.product||'')==='SBC Launch QA - $1 Test Service'&&
  orderParsed(o).sbcLaunchQa?.kind==='OWNER_ONLY_ONE_DOLLAR_CHECKOUT'&&
  (db.customers||[]).some(c=>String(c.id)===String(o.customerId)&&
    Number(c.tenantId)===tenantId&&String(c.email||'').toLowerCase()===email));
 if(existing)return res.json({ok:true,existing:true,orderId:existing.id,
  customerId:existing.customerId,amountCents:100,
  paymentStatus:existing.paymentStatus||'Pending',paymentUrl:existing.paymentUrl||'',
  next:'Reuse the existing order. Never issue a second checkout automatically.'});
 const t=now();
 const customer={id:id('cust'),tenantId,businessName:'SBC Launch QA Test Customer',
  contactName:'Owner Internal Test',email,phone:'',status:'Internal Test',
  source:'Owner Launch QA',notes:'Internal test: no vendor fulfillment or follow-up automation',
  createdAt:t,updatedAt:t};
 const order={id:id('ord'),tenantId,customerId:customer.id,
  customerName:customer.businessName,product:'SBC Launch QA - $1 Test Service',
  quantity:1,status:'New',cost:0,price:1,
  notes:JSON.stringify({sbcLaunchQa:{kind:'OWNER_ONLY_ONE_DOLLAR_CHECKOUT',version:1},
   items:[{id:'SBC_LAUNCH_QA_1USD',sku:'SBC_LAUNCH_QA_1USD',
    name:'SBC Launch QA',qty:1,unitPrice:1}],
   customerEmail:email,fulfillmentStatus:'QA - NO VENDOR FULFILLMENT'}),
  launchQaOwnerCreated:true,paymentStatus:'Pending',
  fulfillmentStatus:'QA - NO VENDOR FULFILLMENT',createdAt:t,updatedAt:t};
 db.customers.unshift(customer);db.orders.unshift(order);
 addActivity('launch_qa_order_created','Owner created controlled $1 Square checkout test',
  {orderId:order.id,customerId:customer.id,amountCents:100});
 try{await saveData()}catch(_){
  return res.status(503).json({ok:false,code:'LAUNCH_QA_SAVE_UNCONFIRMED',
   orderId:order.id,automaticRetry:false,
   error:'Persistence uncertain; verify existing order before retry.'});
 }
 return res.status(201).json({ok:true,existing:false,orderId:order.id,
  customerId:customer.id,amountCents:100,paymentStatus:'Pending',
  next:'/api/payments/square/create-link/'+encodeURIComponent(order.id),
  note:'Owner must generate checkout explicitly. This endpoint does not charge.'});
});

