app.delete('/api/appointments/:id',auth,ownerOnly,async(req,res)=>{const i=db.appointments.findIndex(x=>x.id===req.params.id);if(i<0)return res.status(404).json({error:'Appointment not found.'});db.appointments.splice(i,1);await saveData();res.json({ok:true})});
app.post('/api/sequences',auth,ownerOnly,async(req,res)=>{const b=req.body||{};if(!b.name||!Array.isArray(b.steps)||!b.steps.length)return res.status(400).json({error:'Sequence name and at least one step are required.'});const seq={id:id('seq'),name:String(b.name),description:String(b.description||''),active:b.active!==false,steps:b.steps.map((x,i)=>({id:id('step'),day:Number(x.day||i),channel:String(x.channel||'Task'),subject:String(x.subject||''),body:String(x.body||'')})),createdAt:now(),updatedAt:now()};db.sequences.unshift(seq);await saveData();res.status(201).json(seq)});
app.post('/api/sequences/:id/enroll',auth,ownerOnly,async(req,res)=>{const seq=db.sequences.find(x=>x.id===req.params.id),c=db.customers.find(x=>x.id===req.body?.customerId);if(!seq||!c)return res.status(404).json({error:'Sequence or customer not found.'});const start=new Date(req.body.startDate||Date.now());const e={id:id('enr'),sequenceId:seq.id,customerId:c.id,status:'Active',startedAt:start.toISOString(),currentStep:0,nextStepAt:new Date(start.getTime()+Number(seq.steps[0].day||0)*864e5).toISOString(),createdAt:now(),updatedAt:now()};db.sequenceEnrollments.unshift(e);addActivity('sequence',`Enrolled ${c.businessName||c.contactName} in ${seq.name}`,{sequenceId:seq.id,customerId:c.id});await saveData();res.status(201).json(e)});
app.put('/api/sequence-enrollments/:id',auth,ownerOnly,async(req,res)=>{const e=db.sequenceEnrollments.find(x=>x.id===req.params.id);if(!e)return res.status(404).json({error:'Enrollment not found.'});Object.assign(e,req.body||{},{id:e.id,updatedAt:now()});await saveData();res.json(e)});
app.post('/api/email-templates',auth,ownerOnly,async(req,res)=>{const b=req.body||{};if(!b.name||!b.subject||!b.body)return res.status(400).json({error:'Template name, subject and body are required.'});const t={id:id('tpl'),name:String(b.name),purpose:String(b.purpose||'general'),description:String(b.description||''),subject:String(b.subject),body:String(b.body),active:b.active!==false,systemDefault:false,createdAt:now(),updatedAt:now()};db.emailTemplates.unshift(t);await saveData();res.status(201).json(t)});
app.put('/api/email-templates/:id',auth,ownerOnly,async(req,res)=>{const t=db.emailTemplates.find(x=>x.id===req.params.id);if(!t)return res.status(404).json({error:'Template not found.'});Object.assign(t,req.body||{},{id:t.id,updatedAt:now()});t.purpose=String(t.purpose||'general');t.active=t.active!==false;await saveData();res.json(t)});
app.delete('/api/email-templates/:id',auth,ownerOnly,async(req,res)=>{const i=db.emailTemplates.findIndex(x=>x.id===req.params.id);if(i<0)return res.status(404).json({error:'Template not found.'});db.emailTemplates.splice(i,1);await saveData();res.json({ok:true})});
app.get('/api/message-templates',auth,ownerOnly,(req,res)=>{
  const templates=(db.messageTemplates||[]).map(t=>({...t}));
  res.json({templates});
});
app.post('/api/message-templates',auth,ownerOnly,async(req,res)=>{
  const b=req.body||{}, channel=String(b.channel||'sms').toLowerCase();
  if(!['sms','email'].includes(channel)||!b.name||!b.body)return res.status(400).json({error:'Template name, channel and body are required.'});
  const t={id:id('mtpl'),name:String(b.name).trim(),channel,subject:String(b.subject||'').trim(),body:String(b.body),createdAt:now(),updatedAt:now()};
  db.messageTemplates.unshift(t);await saveData();res.status(201).json(t);
});
app.put('/api/message-templates/:id',auth,ownerOnly,async(req,res)=>{
  const t=(db.messageTemplates||[]).find(x=>x.id===req.params.id);if(!t)return res.status(404).json({error:'Template not found.'});
  Object.assign(t,req.body||{},{id:t.id,updatedAt:now()});if(!['sms','email'].includes(String(t.channel)))t.channel='sms';
  await saveData();res.json(t);
});
app.delete('/api/message-templates/:id',auth,ownerOnly,async(req,res)=>{
  const i=(db.messageTemplates||[]).findIndex(x=>x.id===req.params.id);if(i<0)return res.status(404).json({error:'Template not found.'});
  db.messageTemplates.splice(i,1);await saveData();res.json({ok:true});
});


// V8.2 CLEAN START: clear existing lead/customer records exactly once.
async function resetCurrentLeadsOnce(){
  if(db.settings?.v82LeadResetDone===true) return {deleted:0,skipped:true};
  console.warn('[SBC DATA SAFETY] Legacy V8.2 lead reset is permanently disabled in V64.2.16. No CRM rows will be cleared by startup logic.');
  db.settings={...(db.settings||{}),v82LeadResetDone:true};
  await saveData();
  return {deleted:0,skipped:false,blocked:true};
}


