// ===== V26.1 DYNAMIC SALES QUEUE AUTOMATION =====
const TERMINAL_SALES_OUTCOMES=new Set(['Not Interested','Bad Number','Do Not Call','Closed Business','Not Qualified','Duplicate']);
const ACTIVE_SALES_OUTCOMES=new Set(['Interested','Appointment Requested','Order Ready']);
const RETRY_SALES_OUTCOMES=new Set(['No Answer','Left Voicemail']);
const CALLBACK_SALES_OUTCOMES=new Set(['Call Back','Callback']);
function salesQueueStore(){
  const m=megaData();
  if(!m.salesQueues||typeof m.salesQueues!=='object')m.salesQueues={};
  if(!m.settings.salesQueueTarget)m.settings.salesQueueTarget=50;
  return m;
}
function queueForCaller(callerId){
  const m=salesQueueStore(),q=m.salesQueues[callerId]||{target:Number(m.settings.salesQueueTarget||50),leadIds:[],updatedAt:now()};
  q.target=Math.max(1,Math.min(250,Number(q.target||50)));
  q.leadIds=Array.isArray(q.leadIds)?q.leadIds:[];
  return {m,q};
}
function salesQueueCandidates(callerId){
  const {q}=queueForCaller(callerId);
  const existing=new Set(q.leadIds.map(String));
  const terminalStatuses=new Set(['Customer','Lost','Do Not Call','Closed','Duplicate','Not Qualified']);
  const activeCallerIds=new Set((db.users||[]).filter(u=>u.role==='caller'&&u.active!==false).map(u=>String(u.id)));
  return (db.customers||[]).filter(c=>{
    if(existing.has(String(c.id)))return false;
    if(terminalStatuses.has(String(c.status||'')))return false;
    if(c.status==='Customer'||c.status==='Lost')return false;
    if(!String(c.phone||'').trim())return false;

    // V55.12.5 Revenue PLAY queue-admission fix:
    // Lead-generator/owner assignment must not strand a verified phone lead.
    // Preserve ownership when another active CALLER owns the lead, but allow
    // leads assigned to research/admin/non-caller users to enter the caller queue.
    if(c.assignedTo && String(c.assignedTo)!==String(callerId) && activeCallerIds.has(String(c.assignedTo)))return false;

    const queueState=String(c.salesQueueState||'');
    if(['pipeline','retired','processed'].includes(queueState))return false;
    if(['retry','callback'].includes(queueState) && c.salesNextAttemptAt && new Date(c.salesNextAttemptAt)>new Date())return false;
    const verification=String(c.verificationStatus||'').toLowerCase();
    if(!c.workableOverride && !['verified','sales ready'].includes(verification))return false;

    // Revenue PLAY human-call fallback is explicitly admitted once the lead is
    // Sales Ready + Warm/Hot + phone-present. Do not require SMS consent here:
    // the queue is for a HUMAN VOICE CALL, not an SMS send.
    if(String(c.pipelineStage||'')==='Human Call Pending'){
      const state=String(c.verificationStatus||'').toLowerCase();
      const temp=String(c.leadTemperature||'').toLowerCase();
      if(!['verified','sales ready'].includes(state)||!['warm','hot'].includes(temp)||!String(c.phone||'').trim())return false;
      // Human Call Pending is an explicit voice-work stage. Do not require the
      // automated channel router to remain ROUTED_HUMAN_CALL when an email also exists.
    }
    return true;
  }).sort((a,b)=>{
    const revenuePriority=c=>String(c.pipelineStage||'')==='Human Call Pending'?100:0;
    const score=c=> revenuePriority(c)+(Number(c.leadScore||0))+(c.websiteStatus==='No Website'?3:0)+(c.email?2:0)+(c.contactName?2:0)+(c.industry?1:0);
    return score(b)-score(a);
  });
}
async function replenishSalesQueue(callerId,reason='queue_sync'){
  const {m,q}=queueForCaller(callerId);
  const before=q.leadIds.length;
  q.leadIds=q.leadIds.filter(idv=>{
    const c=db.customers.find(x=>String(x.id)===String(idv));
    return c && !['Customer','Lost','Do Not Call','Closed','Duplicate','Not Qualified'].includes(String(c.status||''));
  });
  const need=Math.max(0,q.target-q.leadIds.length);
  if(need){
    const candidates=salesQueueCandidates(callerId).slice(0,need);
    candidates.forEach(c=>{c.assignedTo=callerId;q.leadIds.push(c.id);});
  }
  q.updatedAt=now();m.salesQueues[callerId]=q;
  if(q.leadIds.length!==before){
    m.automationEvents.unshift({id:id('evt'),type:'sales_queue_replenished',message:`Sales queue replenished for caller ${callerId}: ${q.leadIds.length}/${q.target}`,meta:{callerId,reason,before,after:q.leadIds.length},createdAt:now()});
    m.automationEvents=m.automationEvents.slice(0,500);
  }
  await megaSave(m);
  return q;
}
function removeFromSalesQueue(callerId,customerId){
  const {m,q}=queueForCaller(callerId);
  q.leadIds=q.leadIds.filter(x=>String(x)!==String(customerId));
  m.salesQueues[callerId]=q;
  return {m,q};
}
async function processSalesDisposition(report,c){
  const callerId=report.callerId;
  if(!callerId)return;
  const outcome=String(report.outcome||'').trim();
  const {m,q}=removeFromSalesQueue(callerId,c.id);
  if(TERMINAL_SALES_OUTCOMES.has(outcome)){
    c.status=outcome==='Do Not Call'?'Do Not Call':outcome==='Closed Business'?'Lost':outcome==='Duplicate'?'Duplicate':'Lost';
    c.salesQueueState='retired';
    c.salesDisposition=outcome;
    c.updatedAt=now();
  }else if(RETRY_SALES_OUTCOMES.has(outcome)){
    c.salesQueueState='retry';
    c.salesDisposition=outcome;
    c.salesNextAttemptAt=new Date(Date.now()+24*3600000).toISOString();
    c.followUp=c.salesNextAttemptAt;
  }else if(CALLBACK_SALES_OUTCOMES.has(outcome)){
    c.salesQueueState='callback';
    c.salesDisposition=outcome;
    c.salesNextAttemptAt=report.callbackAt||new Date(Date.now()+24*3600000).toISOString();
    c.followUp=String(c.salesNextAttemptAt).slice(0,10);
    m.nextActions.unshift({id:id('next'),customerId:c.id,customerName:c.businessName||c.contactName||'Lead',title:'Call customer back',type:'Call Back',priority:'High',status:'Open',dueAt:c.salesNextAttemptAt,ownerId:callerId,notes:'Created automatically from call disposition.',createdAt:now(),updatedAt:now()});
  }else if(ACTIVE_SALES_OUTCOMES.has(outcome)||report.orderReady||report.appointmentRequested){
    c.salesQueueState='pipeline';
    c.salesDisposition=outcome||'Interested';
    if(report.appointmentRequested)c.status='Qualified'; else if(c.status==='Lead')c.status='Contacted';
    m.nextActions.unshift({id:id('next'),customerId:c.id,customerName:c.businessName||c.contactName||'Lead',title:report.orderReady?'Build customer order':'Follow up sales opportunity',type:report.orderReady?'Sales Order':'Sales Follow-Up',priority:'High',status:'Open',dueAt:now(),ownerId:callerId,notes:'Created automatically from call disposition.',createdAt:now(),updatedAt:now()});
  }else{
    c.salesQueueState='processed';
    c.salesDisposition=outcome;
  }
  // Persist the queue change in the same automation cycle, then refill to target.
  q.updatedAt=now();m.salesQueues[callerId]=q;
  await megaSave(m);
  return replenishSalesQueue(callerId,'call_disposition');
}
async function syncAllSalesQueues(){
  const callers=(db.users||[]).filter(u=>u.role==='caller'&&u.active!==false);
  for(const u of callers)await replenishSalesQueue(u.id,'startup_sync');
}


app.get('/api/sales/queue',auth,async(req,res)=>{
  if(!['owner','manager','caller'].includes(req.user.role))return res.status(403).json({error:'Sales queue access required.'});
  const target=Math.max(1,Math.min(250,Number(req.query.target||50)));
  const {m,q}=queueForCaller(req.user.id);q.target=target;m.salesQueues[req.user.id]=q;
  const fresh=await replenishSalesQueue(req.user.id,'queue_open');
  const leads=fresh.leadIds.map(idv=>db.customers.find(c=>String(c.id)===String(idv))).filter(Boolean);
  res.json({target:fresh.target,count:leads.length,leads,available:salesQueueCandidates(req.user.id).length,updatedAt:fresh.updatedAt});
});
app.post('/api/sales/queue/replenish',auth,async(req,res)=>{
  if(!['owner','manager','caller'].includes(req.user.role))return res.status(403).json({error:'Sales queue access required.'});
  const q=await replenishSalesQueue(req.user.id,'manual_replenish');
  const leads=q.leadIds.map(idv=>db.customers.find(c=>String(c.id)===String(idv))).filter(Boolean);
  res.json({ok:true,target:q.target,count:leads.length,leads});
});
app.put('/api/sales/queue/settings',auth,ownerOnly,async(req,res)=>{
  const m=salesQueueStore();const target=Math.max(1,Math.min(250,Number(req.body?.target||50)));
  m.settings.salesQueueTarget=target;await megaSave(m);
  const out={};for(const u of (db.users||[]).filter(x=>x.role==='caller'&&x.active!==false))out[u.id]=await replenishSalesQueue(u.id,'owner_target_change');
  res.json({ok:true,target,queues:out});
});

