const REMOVED_EMPLOYEE_ID_HASH='f8cca34a903b6cd2bbc00f8064713ff9e4652a090278da706319d5d01a8b0ada';
const cryptoForRemoval = require('crypto');
const REMOVED_EMPLOYEE_IDENTIFIERS={usernames:new Set(),names:new Set()};
function removedEmployeeMatch(v){const raw=String(v??'');const x=raw.trim().toLowerCase();const digest=cryptoForRemoval.createHash('sha256').update(raw).digest('hex');return digest===REMOVED_EMPLOYEE_ID_HASH || REMOVED_EMPLOYEE_IDENTIFIERS.usernames.has(x) || REMOVED_EMPLOYEE_IDENTIFIERS.names.has(x);}
function purgeRemovedEmployeeData(){
  const users=db.users||[];
  const removed=users.filter(u=>removedEmployeeMatch(u.id)||removedEmployeeMatch(u.username)||removedEmployeeMatch(u.name));
  const ids=new Set(removed.map(u=>String(u.id)));
  const names=new Set(removed.map(u=>String(u.name||'').trim().toLowerCase()).filter(Boolean));
  const ref=(v)=>ids.has(String(v??''))||names.has(String(v??'').trim().toLowerCase())||removedEmployeeMatch(v);
  db.users=users.filter(u=>!ref(u.id)&&!ref(u.username)&&!ref(u.name));
  const v=db.settings.v9||{};
  for(const k of ['trainingProgress','certifications','workforceNotes','compensation','onboarding','aiMemory']) if(v[k]&&typeof v[k]==='object') for(const key of Object.keys(v[k])) if(ids.has(String(key))||names.has(String(key).toLowerCase())) delete v[k][key];
  for(const k of ['timeEntries','payrollRuns']) if(Array.isArray(v[k])) v[k]=v[k].filter(x=>!(ref(x.userId)||ref(x.employeeId)||ref(x.username)||ref(x.employeeName)||ref(x.userName)));
  db.settings.v9=v;
  const by=(x,...keys)=>keys.some(k=>ref(x?.[k]));
  for(const k of ['callReports','callLogs','tasks','customerMessages','customerAccounts']) if(Array.isArray(db[k])) db[k]=db[k].filter(x=>!by(x,'userId','employeeId','callerId','createdBy','assignedTo','username','userName','employeeName'));
  if(Array.isArray(db.auditLog)) db.auditLog=db.auditLog.filter(x=>!by(x,'userId','employeeId','actorId','createdBy','username','userName','employeeName'));
  if(Array.isArray(db.activities)) db.activities=db.activities.filter(x=>!by(x,'userId','employeeId','actorId','createdBy','assignedTo','username','userName','employeeName'));
  for(const k of ['customers']) if(Array.isArray(db[k])) for(const x of db[k]){if(ref(x.assignedTo)){x.assignedTo='';x.assignedToName='';}if(ref(x.researcherId)){x.researcherId='';x.researcherName='';}}
  for(const k of ['orders','quotes','renewals']) if(Array.isArray(db[k])) for(const x of db[k]){for(const f of ['salesRepId','fulfillmentOwner','assignedTo','createdBy','employeeId','callerId']) if(ref(x[f])) x[f]='';for(const f of ['salesRepName','fulfillmentOwnerName','assignedToName','employeeName']) if(ref(x[f])) x[f]='';}
  if(db.megaOpsStore&&typeof db.megaOpsStore==='object'){
    for(const k of ['approvals','commissionLedger','commissions','employeeRecords','employeeProfiles']) if(Array.isArray(db.megaOpsStore[k])) db.megaOpsStore[k]=db.megaOpsStore[k].filter(x=>!by(x,'userId','employeeId','employeeName','userName','assignedTo','createdBy'));
  }
  const removedIds=[...ids].filter(Boolean);
  return {removedUsers:removed.length,removedIds,removedNames:[]};
}
async function purgeRemovedEmployeeMysql(){
  if(!mysqlPool)return {mysql:false};
  const idList=(db.users||[]).filter(u=>removedEmployeeMatch(u.id)||removedEmployeeMatch(u.username)||removedEmployeeMatch(u.name)).map(u=>String(u.id));
  if(!idList.length)return {mysql:true,removed:0};
  const exec=async(sql,args=[])=>{try{const [r]=await mysqlPool.query(sql,args);return Number(r?.affectedRows||0)}catch(e){return 0}};
  let removed=0;
  removed+=await exec('DELETE FROM sbc_sessions WHERE user_id IN (?)',[idList]);
  removed+=await exec('DELETE FROM sbc_workforce_privileges WHERE user_id IN (?)',[idList]);
  removed+=await exec('DELETE FROM sbc_lead_submissions WHERE submitted_by IN (?)',[idList]);
  removed+=await exec('DELETE FROM sbc_collaboration_ops WHERE actor_id IN (?)',[idList]);
  removed+=await exec('DELETE FROM sbc_audit_log WHERE user_id IN (?)',[idList]);
  for(const [table,col] of [['sbc_notary_requests','created_by'],['sbc_notary_appointments','created_by'],['sbc_notary_journal','completed_by'],['sbc_kim_growth_missions','created_by'],['sbc_kim_enterprise_missions','created_by'],['sbc_kim_commercial_readiness_missions','created_by']]) removed+=await exec(`DELETE FROM ${table} WHERE ${col} IN (?)`,[idList]);
  removed+=await exec("UPDATE sbc_customers SET assigned_to='' WHERE assigned_to IN (?)",[idList]);
    return {mysql:true,removed};
}
