function fulfillmentVendorForItem(item){const n=String(item?.name||'').toLowerCase(),c=String(item?.category||'').toLowerCase();
  if(/domain|hosting|wordpress|microsoft 365|email/.test(n))return 'godaddy';
  if(/business card|flyer|brochure|door hanger|postcard|print/.test(n)||c==='print')return /business card/.test(n)?'fourOverFour':'vistaPrint';
  return 'internal';
}
function fulfillmentJobFor(order,item,vendor){const m=megaData();return {id:id('fulfill'),tenantId:Number(order.tenantId||TENANT_DEFAULT_ID),orderId:order.id,customerId:order.customerId||'',customerName:order.customerName||'',itemId:String(item?.id||''),product:String(item?.name||order.product||'SBC Service'),quantity:Number(item?.qty||order.quantity||1),vendor,status:'ready',vendorStatus:'not_submitted',vendorOrderNumber:'',trackingNumber:'',cost:0,value:Number(order.price||0),requiresOwnerClearance:Number(order.price||0)>=10000,financialLockId:'',ownerClearanceAt:'',ownerClearanceBy:'',requirements:orderParsed(order).customerIntake||{},source:'square-paid-order',testMode:Boolean(orderParsed(order).sbcTest===true),attempts:0,lastError:'',idempotencyKey:`sbc:${order.id}:${String(item?.id||item?.name||'order')}:${vendor}`,claimedAt:'',processingStartedAt:'',leaseUntil:'',nextAttemptAt:'',createdAt:now(),updatedAt:now()};}
async function runOwnerFullTestOrder(req){
  if(req.user?.role!=='owner')throw new Error('Only Romeo / owner can run the full system test order.');
  const stamp=new Date().toISOString();
  const testEmail='sbc-system-test@example.invalid';
  const testPhone='3055550199';
  const c={id:id('cust'),tenantId:TENANT_DEFAULT_ID,businessName:'SBC SYSTEM TEST — DO NOT SERVICE',contactName:'SBC Full-Cycle Test',phone:testPhone,email:testEmail,status:'Lead',source:'SBC V47 Full-Cycle Test',notes:`TEST ONLY. No customer service, vendor submission or real payment. Created ${stamp}.`,createdAt:stamp,updatedAt:stamp,assignedTo:req.user.id};
  db.customers.unshift(c);
  const o={id:id('ord'),tenantId:TENANT_DEFAULT_ID,customerId:c.id,customerName:c.businessName,product:'SBC FULL-CYCLE SYSTEM TEST',quantity:1,status:'New',cost:0,price:1,salesRepId:req.user.id,salesRepName:req.user.name,paymentUrl:'',paymentStatus:'Pending',fulfillmentStatus:'NOT STARTED — TEST',notes:JSON.stringify({sbcTest:true,testType:'full-cycle',noRealCharge:true,items:[{id:'sbc-v47-test',name:'SBC Internal Test Fulfillment',qty:1,unitPrice:1,category:'internal'}],subtotal:1,discount:0,taxRate:0,tax:0,total:1,createdAt:stamp}),createdAt:stamp,updatedAt:stamp};
  db.orders.unshift(o);
  addActivity('system_test',`Created V47 full-cycle test order ${o.id}`,{orderId:o.id,customerId:c.id,ownerId:req.user.id,test:true});
  audit(req.user,'v47_test_order_created','Created controlled V47 full-cycle test order',{orderId:o.id,customerId:c.id,test:true,noRealCharge:true});
  await saveData();

  // Controlled test payment: synthetic state transition only. Square is never charged.
  o.paymentStatus='Paid'; o.status='Paid'; o.fulfillmentStatus='PAID — TEST PAYMENT';
  o.testPayment={status:'SIMULATED_PAID',amount:1,processor:'SBC TEST HARNESS',realCharge:false,createdAt:now()};
  o.updatedAt=now();
  audit(req.user,'v47_test_payment_simulated','Simulated payment for V47 test order; no real processor charge was created',{orderId:o.id,amount:1,realCharge:false});
  await saveData();

  // Exercise the real GodKim orchestration path. The test order is explicitly marked
  // sbcTest=true, so its internal fulfillment adapter completes without contacting a vendor.
  const result=await GOD_KIM.orchestrate({
    order:o,
    requestUser:req.user,
    createFulfillmentJobsForOrder,
    processReadyFulfillmentJobs,
    vendorCapabilities,
    addActivity,
    audit,
    saveData,
    db,
    catalog:CATALOG,
    sendCustomerStatus:async()=>({sent:false,reason:'Controlled test customer uses example.invalid.'}),
    testMode:false
  });
  if(!result?.ok)throw new Error(result?.exception?.reason||'GodKim orchestration did not complete.');
  const liveJobs=(megaData().fulfillmentJobs||[]).filter(j=>j.orderId===o.id);
  const failed=liveJobs.filter(j=>j.status==='failed');
  if(failed.length)throw new Error(`Test fulfillment worker failed: ${failed.map(j=>j.lastError||j.id).join('; ')}`);
  const processed=liveJobs.filter(j=>Number(j.attempts||0)>0).length;
  if(!processed)throw new Error('The test fulfillment job was created but the worker did not process it.');
  if(result.stage!=='COMPLETED')throw new Error(`GodKim test orchestration stopped at ${result.stage}.`);

  o.status='Delivered';
  o.fulfillmentStatus='COMPLETE — TEST';
  o.testCompletedAt=now();
  o.updatedAt=now();
  c.status='Customer';
  c.updatedAt=now();
  addActivity('system_test',`Completed V47 full-cycle test order ${o.id}`,{orderId:o.id,customerId:c.id,test:true,realCharge:false,fulfillmentJobs:liveJobs.map(j=>j.id)});
  audit(req.user,'v47_test_order_completed','Completed controlled V47 full-cycle test order through GodKim orchestration',{orderId:o.id,customerId:c.id,jobIds:liveJobs.map(j=>j.id),traceId:result.traceId,receiptId:result.receipt?.receiptId,realCharge:false});
  await saveData();
  return {ok:true,test:true,realCharge:false,order:{id:o.id,status:o.status,paymentStatus:o.paymentStatus,fulfillmentStatus:o.fulfillmentStatus,customerId:o.customerId},customer:{id:c.id,status:c.status},godKim:{traceId:result.traceId,stage:result.stage,provider:result.provider,receipt:result.receipt,steps:result.steps,elapsedMs:result.elapsedMs},jobs:liveJobs.map(j=>({id:j.id,product:j.product,vendor:j.vendor,status:j.status,vendorStatus:j.vendorStatus,vendorOrderNumber:j.vendorOrderNumber||'',trackingNumber:j.trackingNumber||'',attempts:j.attempts||0})),verification:{orderPersisted:Boolean((db.orders||[]).find(x=>x.id===o.id)),customerPersisted:Boolean((db.customers||[]).find(x=>x.id===c.id)),jobCount:liveJobs.length,processedJobs:processed,failedJobs:failed.length},message:'V47 full-cycle test completed through the real GodKim orchestration path. No real payment or external vendor submission was used.'};
}

// SBC_V6651_FULFILLMENT_EVIDENCE_CONSISTENCY: evidence and tenant identity precede fulfillment.
function SBC_V6651_REQUIRE_PAID(order,expectedTenantId){
 const tenantId=Number(order?.tenantId);
 const expected=expectedTenantId===undefined?tenantId:Number(expectedTenantId);
 if(!Number.isSafeInteger(tenantId)||tenantId<=0||!Number.isSafeInteger(expected)||expected<=0||tenantId!==expected)throw Object.assign(new Error('TENANT_CONTEXT_REQUIRED'),{code:'TENANT_CONTEXT_REQUIRED'});
 const E=require('./enterprise/v6640-payment-evidence.cjs');
 // SBC_V6658_PROVENANCE_REVENUE_FULFILLMENT: no vendor work from status-only claims or incomplete receipts.
 if(!E.providerCapturedSquare(order))throw Object.assign(new Error('PAYMENT_EVIDENCE_REQUIRED'),{code:'PAYMENT_EVIDENCE_REQUIRED'});
 return order;
}
function fulfillmentItemsForOrder(order){
  const parsed=orderParsed(order);
  const direct=Array.isArray(parsed.items)&&parsed.items.length?parsed.items:[];
  const pkg=CATALOG.packages.find(x=>String(x.id)===String(parsed.bundleId||''));
  if(!pkg) return direct.length?direct:[{id:'order',name:order.product||'SBC Service',qty:order.quantity||1,unitPrice:Number(order.price||0),category:''}];
  const features=pkg.features||[]; const out=[];
  const add=(id,name,qty,category)=>out.push({id,name,qty,unitPrice:0,category});
  if(features.some(f=>/domain/i.test(f))) add(`${pkg.id}-domain`,'Domain Registration / Setup',1,'Digital');
  if(features.some(f=>/hosting|wordpress/i.test(f))) add(`${pkg.id}-hosting`,'Web Hosting / Managed Hosting',1,'Digital');
  if(features.some(f=>/microsoft 365|business email|email/i.test(f))) add(`${pkg.id}-email`,'Business Email / Microsoft 365 Setup',1,'Email');
  const card=features.find(f=>/(\d[\d,]*)\s+business cards?/i.test(f)); if(card){const m=card.match(/(\d[\d,]*)\s+business cards?/i);add(`${pkg.id}-cards`,`${m[1]} Business Cards`,Number(String(m[1]).replace(/,/g,'')),'print');}
  if(features.some(f=>/flyer|marketing piece|marketing pieces/i.test(f))) add(`${pkg.id}-print-marketing`,'Marketing Print Piece',1,'print');
  if(!out.length) return direct.length?direct:[{id:'order',name:order.product||'SBC Service',qty:order.quantity||1,unitPrice:Number(order.price||0),category:''}];
  return out;
}
async function createFulfillmentJobsForOrder(order){
  SBC_V6651_REQUIRE_PAID(order);
  const m=megaData(), items=fulfillmentItemsForOrder(order);
  const existing=new Set(m.fulfillmentJobs.filter(j=>j.orderId===order.id).map(j=>`${j.itemId}:${j.vendor}`)); let created=[];
  for(const item of items){const vendor=fulfillmentVendorForItem(item),key=`${String(item.id||item.name)}:${vendor}`;if(existing.has(key))continue;const job=fulfillmentJobFor(order,item,vendor);if(job.requiresOwnerClearance){const lock=V569_PRODUCTION_EXPANSION.financialLock({action:'vendor_fulfillment',amount:job.value,tenantId:job.tenantId,resourceId:job.id,metadata:{orderId:job.orderId,provider:job.vendor,product:job.product}});job.financialLockId=lock.id;job.ownerClearanceAt='';job.ownerClearanceBy='';if(mysqlPool){try{await V569_PRODUCTION_EXPANSION.persistFinancialLock(mysqlPool,lock);}catch(e){console.warn('[SBC VAULT] lock persistence failed:',e.message);throw e;}}global.__SBC_RECENT_RUNTIME_EVENTS=Array.isArray(global.__SBC_RECENT_RUNTIME_EVENTS)?global.__SBC_RECENT_RUNTIME_EVENTS:[];global.__SBC_RECENT_RUNTIME_EVENTS.push({id:`vault-${Date.now()}`,timestamp:Date.now(),event:'vault_breakpoint_triggered',level:'WARN',version:BUILD_VERSION,component:'FULFILLMENT_VAULT',context:{lockId:lock.id,transactionId:job.id,amount:job.value,tenantId:job.tenantId,status:lock.status}});global.__SBC_RECENT_RUNTIME_EVENTS=global.__SBC_RECENT_RUNTIME_EVENTS.slice(-500);}m.fulfillmentJobs.unshift(job);created.push(job);}
  if(created.length){
    try{await enqueueArchitectureEvent('fulfillment.jobs.created',{orderId:order.id,jobIds:created.map(x=>x.id)},order.tenantId||TENANT_DEFAULT_ID)}catch(e){console.warn('[SBC OUTBOX] fulfillment enqueue:',e.message)}
    if(mysqlPool){
      for(const job of created.filter(x=>['fourOverFour','4over4','vistaPrint','vistaprint'].includes(String(x.vendor)))){
        try{
          const idem=job.idempotencyKey;
          await mysqlPool.query('INSERT INTO sbc_vendor_outbox(id,tenant_id,provider,job_id,attempts,status,idempotency_key,request_json,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE updated_at=VALUES(updated_at)',[
            id('vout'), order.tenantId||TENANT_DEFAULT_ID, String(job.vendor), job.id, 0,
            job.requiresOwnerClearance?'OWNER_CLEARANCE_REQUIRED':'STAGED', idem,
            JSON.stringify({schemaVersion:'1.0',provider:job.vendor,jobId:job.id,orderId:job.orderId,customerId:job.customerId,product:job.product,quantity:job.quantity,requirements:job.requirements,idempotencyKey:idem}), sqlDateTime(job.createdAt), sqlDateTime(now())
          ]);
        }catch(e){console.warn('[SBC OUTBOX] vendor staging:',e.message)}
      }
    }
    m.automationEvents.unshift({id:id('evt'),type:'fulfillment_jobs_created',message:`Created ${created.length} automated fulfillment job(s) for ${order.customerName||order.id}`,meta:{orderId:order.id,jobIds:created.map(x=>x.id)},createdAt:now()});m.automationEvents=m.automationEvents.slice(0,500);await megaSave(m);
  }
  return created;
}
async function submitVendorJob(job){
  const sourceOrder=(db.orders||[]).find(o=>String(o.id)===String(job?.orderId));
  SBC_V6651_REQUIRE_PAID(sourceOrder,job?.tenantId);
  const amount=Number(job?.value||0);
  if(amount>=V569_PRODUCTION_EXPANSION.OWNER_THRESHOLD){
    await V569_PRODUCTION_EXPANSION.financialExecutionGate({pool:mysqlPool,amount,tenantId:job?.tenantId||TENANT_DEFAULT_ID,resourceId:job?.id,lockId:job?.financialLockId,action:'vendor_fulfillment'});
  }
  const tenantHealth=V569_PRODUCTION_EXPANSION.tenantHealth(Number(job?.tenantId||TENANT_DEFAULT_ID));
  if(tenantHealth.quarantined)throw new Error('TENANT_WORKER_QUARANTINED');
  const adapter=fulfillmentAdapterFor(job.vendor);adapter.validateOrder(job);return adapter.submitOrder(job);}
async function recoverStaleFulfillmentJobs(){
  // A crashed worker may have submitted a vendor order before dying. A stale
  // processing lease is therefore ambiguous, not proof that no submission happened.
  const m=megaData(); const cutoff=Date.now()-15*60*1000; let recovered=0;
  for(const job of m.fulfillmentJobs){
    const lease=job.leaseUntil?new Date(job.leaseUntil).getTime():0;
    const started=job.processingStartedAt?new Date(job.processingStartedAt).getTime():0;
    if(job.status==='processing' && ((lease && lease<Date.now()) || (started && started<cutoff))){
      job.status='needs_reconciliation';job.vendorStatus='submission_outcome_unknown';job.lastError='Worker lease expired after submission may have started. Reconcile provider state before retrying to prevent duplicate external orders.';job.claimedAt='';job.processingStartedAt='';job.leaseUntil='';job.nextAttemptAt='';job.updatedAt=now();recovered++;
    }
  }
  if(recovered){await megaSave(m);console.warn('[SBC FULFILLMENT] '+recovered+' stale in-flight job(s) held for reconciliation; automatic re-dispatch is blocked.');}
  return recovered;
}
async function claimFulfillmentJob(job){
  if(!job||!job.id)return false;
  const m=megaData();const live=m.fulfillmentJobs.find(x=>String(x.id)===String(job.id));if(!live||live.status!=='ready')return false;
  if(mysqlPool){const [r]=await mysqlPool.query(`UPDATE sbc_fulfillment_jobs SET status='processing',vendor_status='processing',claimed_at=UTC_TIMESTAMP(),processing_started_at=UTC_TIMESTAMP(),lease_until=DATE_ADD(UTC_TIMESTAMP(),INTERVAL 15 MINUTE),updated_at=UTC_TIMESTAMP() WHERE id=? AND status='ready'`,[live.id]);if(!r.affectedRows)return false;}
  const t=Date.now();live.status='processing';live.vendorStatus='processing';live.claimedAt=now();live.processingStartedAt=now();live.leaseUntil=new Date(t+15*60*1000).toISOString();live.updatedAt=now();await megaSave(m);return true;
}
async function requeueDueFailedFulfillmentJobs(){
 const m=megaData(),t=Date.now(),maxAttempts=Math.max(1,Math.min(12,Number(process.env.SBC_FULFILLMENT_MAX_ATTEMPTS||6)));let count=0;
 for(const j of m.fulfillmentJobs){if(String(j.status||'').toLowerCase()!=='failed'||Number(j.attempts||0)>=maxAttempts||!j.nextAttemptAt||new Date(j.nextAttemptAt).getTime()>t)continue;
  if(mysqlPool){const [r]=await mysqlPool.query(`UPDATE sbc_fulfillment_jobs SET status='ready',vendor_status='retry_scheduled',claimed_at=NULL,processing_started_at=NULL,lease_until=NULL,next_attempt_at=NULL,updated_at=UTC_TIMESTAMP() WHERE id=? AND status='failed' AND attempts<? AND next_attempt_at IS NOT NULL AND next_attempt_at<=UTC_TIMESTAMP()`,[j.id,maxAttempts]);if(!r.affectedRows)continue;}
  j.status='ready';j.vendorStatus='retry_scheduled';j.claimedAt='';j.processingStartedAt='';j.leaseUntil='';j.nextAttemptAt='';j.updatedAt=now();count++;
 }
 if(count)await megaSave(m);return count;
}
async function loadNewDurableFulfillmentJobs(){
 if(!mysqlPool)return 0;const [rows]=await mysqlPool.query(`SELECT * FROM sbc_fulfillment_jobs WHERE status IN ('ready','failed','owner_clearance_required','processing','submitted','needs_reconciliation') ORDER BY created_at DESC LIMIT 5000`);
 const m=megaData(),known=new Set(m.fulfillmentJobs.map(j=>String(j.id)));let added=0;
 for(const r of rows||[]){if(known.has(String(r.id)))continue;let req={};try{req=JSON.parse(r.requirements_json||'{}')}catch{}
  m.fulfillmentJobs.push({id:r.id,tenantId:Number(__sbcRequireTenantId(r.tenant_id)),orderId:r.order_id||'',customerId:r.customer_id||'',customerName:r.customer_name||'',itemId:r.item_id||'',product:r.product||'',quantity:Number(r.quantity||1),vendor:r.vendor||'internal',status:r.status||'ready',vendorStatus:r.vendor_status||'',vendorOrderNumber:r.vendor_order_number||'',trackingNumber:r.tracking_number||'',cost:Number(r.cost||0),value:Number(r.value||0),requirements:req,attempts:Number(r.attempts||0),lastError:r.last_error||'',idempotencyKey:r.idempotency_key||'',claimedAt:r.claimed_at?fromSqlDateTime(r.claimed_at):'',processingStartedAt:r.processing_started_at?fromSqlDateTime(r.processing_started_at):'',leaseUntil:r.lease_until?fromSqlDateTime(r.lease_until):'',nextAttemptAt:r.next_attempt_at?fromSqlDateTime(r.next_attempt_at):'',createdAt:fromSqlDateTime(r.created_at),updatedAt:fromSqlDateTime(r.updated_at)});known.add(String(r.id));added++;}
 if(added){db.megaOpsStore=m;console.log('[SBC V65.1.17] hydrated '+added+' durable fulfillment jobs from MySQL.');}return added;
}
async function processReadyFulfillmentJobs(){
  if(db.settings?.automationEnabled===false)return {processed:0,recovered:0,requeued:0,paused:'AUTOMATION_DISABLED'};
  if(typeof MYSQL_RECOVERY_REQUIRED!=='undefined'&&MYSQL_RECOVERY_REQUIRED)return {processed:0,recovered:0,requeued:0,paused:'MYSQL_RECOVERY_REQUIRED'};
  if(typeof MYSQL_RECOVERY_EVALUATED!=='undefined'&&!MYSQL_RECOVERY_EVALUATED)return {processed:0,recovered:0,requeued:0,paused:'MYSQL_RECOVERY_NOT_EVALUATED'};
  if(typeof RUNTIME_GATE!=='undefined'&&RUNTIME_GATE.blocked('FULFILLMENT_AUTOMATION'))return {processed:0,recovered:0,requeued:0,paused:'RUNTIME_GATE_BLOCKED'};
  await loadNewDurableFulfillmentJobs();const requeued=await requeueDueFailedFulfillmentJobs();
  const recovered=await recoverStaleFulfillmentJobs();
  let processed=0,blocked=0;
  const candidates=megaData().fulfillmentJobs.filter(x=>x.status==='ready'&&(!x.nextAttemptAt||new Date(x.nextAttemptAt).getTime()<=Date.now())).slice(0,20);
  for(const candidate of candidates){
    const value=Number(candidate.value||0);
    if(value>=10000 && !candidate.ownerClearanceAt){
      const m=megaData();const live=m.fulfillmentJobs.find(x=>x.id===candidate.id);if(live){live.status='owner_clearance_required';live.vendorStatus='owner_clearance_required';live.requiresOwnerClearance=true;live.lastError='Order value is at or above the $10,000 automation threshold. Owner clearance required.';live.updatedAt=now();m.automationEvents.unshift({id:id('evt'),type:'owner_clearance_required',message:`Fulfillment ${live.id} paused for owner clearance.`,meta:{jobId:live.id,orderId:live.orderId,value},createdAt:now()});m.automationEvents=m.automationEvents.slice(0,500);await megaSave(m);blocked++;}continue;
    }
    if(!(await claimFulfillmentJob(candidate)))continue;const live=megaData().fulfillmentJobs.find(x=>x.id===candidate.id);try{const result=await submitVendorJob(live);const m=megaData(),job=m.fulfillmentJobs.find(x=>x.id===live.id);job.status=result.status;job.vendorStatus=result.status;job.vendorOrderNumber=result.vendorOrderNumber||job.vendorOrderNumber;job.trackingNumber=result.trackingNumber||job.trackingNumber;job.lastError='';job.attempts=Number(job.attempts||0)+1;job.claimedAt='';job.processingStartedAt='';job.leaseUntil='';job.nextAttemptAt='';job.updatedAt=now();syncOrderFulfillmentLifecycle(job.orderId);m.automationEvents.unshift({id:id('evt'),type:'fulfillment_worker',message:`Fulfillment worker completed ${job.id} (${job.vendor}/${job.product}).`,createdAt:now()});m.automationEvents=m.automationEvents.slice(0,500);await megaSave(m);processed++;}catch(e){V569_PRODUCTION_EXPANSION.recordTenantFailure(Number(candidate.tenantId||TENANT_DEFAULT_ID),'fulfillment_vendor',e.message);const m=megaData(),job=m.fulfillmentJobs.find(x=>x.id===live.id);job.attempts=Number(job.attempts||0)+1;const errCode=String(e?.code||e?.cause?.code||'').toUpperCase(),errText=String(e.message||e||'').toLowerCase();const paymentHold=errCode==='PAYMENT_EVIDENCE_REQUIRED'||errCode==='TENANT_CONTEXT_REQUIRED';const ambiguous=['ETIMEDOUT','ESOCKETTIMEDOUT','ECONNRESET','ECONNABORTED','EPIPE','UND_ERR_CONNECT_TIMEOUT','UND_ERR_HEADERS_TIMEOUT','ERR_SOCKET_CLOSED'].includes(errCode)||/timed? out|socket hang up|connection reset|connection closed|upstream timeout|gateway timeout|bad gateway|\b502\b|\b503\b|\b504\b|response lost after submit/.test(errText);job.status=(ambiguous||paymentHold)?'needs_reconciliation':'failed';job.vendorStatus=paymentHold?'payment_evidence_required':ambiguous?'submission_outcome_unknown':'failed';job.lastError=(paymentHold?'Payment evidence or tenant scope is missing; vendor was not contacted. ':ambiguous?'Vendor submission outcome is ambiguous; automatic retry is paused to prevent a duplicate external order. ':'')+String(e.message||e);job.claimedAt='';job.processingStartedAt='';job.leaseUntil='';job.nextAttemptAt=(ambiguous||paymentHold)?'':new Date(Date.now()+Math.min(60*60*1000,Math.pow(2,Math.min(job.attempts,6))*60*1000)).toISOString();job.updatedAt=now();syncOrderFulfillmentLifecycle(job.orderId);m.automationFailures.unshift({id:id('fail'),status:'Open',type:'fulfillment_vendor',message:`${job.vendor} fulfillment failed for ${job.product}: ${job.lastError}`,meta:{jobId:job.id,orderId:job.orderId,attempts:job.attempts},createdAt:now()});m.automationFailures=m.automationFailures.slice(0,100);await megaSave(m);}}return {processed,recovered,requeued,blocked};}

function syncOrderFulfillmentLifecycle(orderId){
 const order=(db.orders||[]).find(o=>String(o.id)===String(orderId));if(!order)return null;
 const jobs=(megaData().fulfillmentJobs||[]).filter(j=>String(j.orderId)===String(orderId));if(!jobs.length)return null;
 const low=v=>String(v||'').toLowerCase(),done=new Set(['completed','complete','fulfilled','delivered']),blocked=new Set(['failed','manual','manual_required','waiting_vendor_credentials','ready_for_owner','owner_clearance_required','provider_mapping_required','blocked']);
 let state='Ready for Fulfillment';
 if(jobs.every(j=>done.has(low(j.status))&&(!j.vendorStatus||done.has(low(j.vendorStatus)))))state='Completed';
 else if(jobs.some(j=>['processing','submitted','dispatched','claimed'].includes(low(j.status))))state='In Progress';
 else if(jobs.some(j=>['failed','needs_reconciliation','submission_outcome_unknown'].includes(low(j.status))||['failed','submission_outcome_unknown'].includes(low(j.vendorStatus))))state='Needs Attention';
 else if(jobs.some(j=>blocked.has(low(j.status))||blocked.has(low(j.vendorStatus))))state='Ready for Fulfillment';
 order.fulfillmentStatus=state;order.fulfillmentUpdatedAt=now();order.godKimStage=state==='Completed'?'COMPLETED':state==='In Progress'?'FULFILLING':state==='Needs Attention'?'NEEDS_ATTENTION':'FULFILLMENT_READY';order.godKimUpdatedAt=now();return {orderId:String(orderId),status:state,jobCount:jobs.length,completedJobs:jobs.filter(j=>done.has(low(j.status))).length};
}

function demoSlug(name){return String(name||'business').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,50)||'business';}
function compileDemoSandbox(html,slug){
  const mode=String(process.env.SBC_DEMO_SANDBOX_MODE||'process').toLowerCase();
  if(mode==='inline')return String(html||'');
  const sandboxRoot=path.join(DATA_DIR,'demo-sandbox');fs.mkdirSync(sandboxRoot,{recursive:true});
  const safeSlug=String(slug||'demo').toLowerCase().replace(/[^a-z0-9-]/g,'').slice(0,80)||'demo';
  const workerToken=crypto.randomBytes(32).toString('hex');
  const childEnv={NODE_ENV:'production',PATH:process.env.PATH||'',SBC_DEMO_SANDBOX_ROOT:sandboxRoot,SBC_DEMO_WORKER_TOKEN:workerToken};
  if(mode==='container'){
    // Container execution is activated only when an external runtime is deliberately supplied.
    throw new Error('Container demo sandbox is not available in this hosting runtime; use process sandbox or configure the approved container worker.');
  }
  const r=spawnSync(process.execPath,[path.join(__dirname,'workers','demo-builder.js')],{input:JSON.stringify({slug:safeSlug,html:String(html||''),workerToken}),encoding:'utf8',timeout:Number(process.env.SBC_DEMO_SANDBOX_TIMEOUT_MS||4500),maxBuffer:1024*1024,env:childEnv});
  if(r.status!==0)throw new Error(String(r.stderr||'Demo sandbox failed.').slice(0,500));
  const out=path.join(sandboxRoot,safeSlug+'.html');
  if(!fs.existsSync(out))throw new Error('Demo sandbox did not produce a file.');
  const compiled=fs.readFileSync(out,'utf8');try{fs.rmSync(out,{force:true})}catch{}
  return compiled;
}
function buildDemoHtml(demo){
  const result=buildSbcSite(demo);
  const slug=String(demo?.slug||'').replace(/[^a-z0-9-]/gi,'').slice(0,80);
  const checkoutBlock=`<section style="font-family:Inter,Arial,sans-serif;padding:42px 20px;background:#0b0c10;color:#fff;text-align:center"><div style="max-width:920px;margin:auto;border:1px solid rgba(255,255,255,.14);border-radius:28px;padding:34px;background:linear-gradient(135deg,rgba(11,116,209,.18),rgba(242,138,25,.12))"><div style="font-size:11px;font-weight:800;letter-spacing:.16em;text-transform:uppercase;opacity:.7">SBC NEXT STEP</div><h2 style="font-size:clamp(28px,5vw,54px);margin:12px 0;letter-spacing:-.05em">Ready to make this real?</h2><p style="max-width:680px;margin:0 auto 22px;color:#b8bec8;line-height:1.7">Choose a starting package. SBC will create a secure Square checkout for this business; card data never enters the SBC system.</p><div style="display:flex;gap:10px;justify-content:center;flex-wrap:wrap"><button data-sbc-checkout="starter" style="border:0;border-radius:999px;padding:14px 20px;font-weight:800;cursor:pointer">Business Starter · $199</button><button data-sbc-checkout="essentials" style="border:1px solid rgba(255,255,255,.25);background:transparent;color:#fff;border-radius:999px;padding:14px 20px;font-weight:800;cursor:pointer">Business Essentials · $349</button><button data-sbc-checkout="professional" style="border:1px solid rgba(255,255,255,.25);background:transparent;color:#fff;border-radius:999px;padding:14px 20px;font-weight:800;cursor:pointer">Complete Launch · $699</button></div><div id="sbcCheckoutStatus" style="margin-top:16px;font-size:12px;color:#9da5b0"></div></div></section><script>(()=>{const slug='${slug}';document.querySelectorAll('[data-sbc-checkout]').forEach(b=>b.addEventListener('click',async()=>{const status=document.getElementById('sbcCheckoutStatus');b.disabled=true;if(status)status.textContent='Preparing secure checkout…';try{const r=await fetch('/api/public/demo-checkout/'+encodeURIComponent(slug),{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({packageId:b.dataset.sbcCheckout})});const j=await r.json();if(!r.ok)throw new Error(j.error||'Checkout unavailable.');location.href=j.paymentUrl;}catch(e){if(status)status.textContent=e.message||'Checkout unavailable.';b.disabled=false;}})})})();</script>`;
  const businessLabel=String(demo?.customer?.businessName||demo?.customer?.contactName||'your business').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const previewRibbon='<aside class="sbc-concept-ribbon" aria-label="Website concept preview"><span class="sbc-concept-dot"></span><span><strong>Custom website concept</strong><small>Prepared for '+businessLabel+' by Successful By Choice</small></span><span class="sbc-concept-tag">PREVIEW</span></aside><style>.sbc-concept-ribbon{position:relative;z-index:70;display:flex;align-items:center;gap:12px;padding:12px clamp(16px,4vw,44px);background:#0b1020;color:#fff;border-bottom:1px solid rgba(255,255,255,.12);font:500 12px/1.4 Inter,system-ui,sans-serif}.sbc-concept-ribbon strong{display:block;font-size:12px;letter-spacing:.01em}.sbc-concept-ribbon small{display:block;color:#b7c1d4;margin-top:2px;font-size:11px}.sbc-concept-dot{width:9px;height:9px;border-radius:50%;background:#f28a19;box-shadow:0 0 0 4px rgba(242,138,25,.16);flex:none}.sbc-concept-tag{margin-left:auto;border:1px solid rgba(255,255,255,.22);border-radius:999px;padding:5px 9px;font-size:9px;font-weight:800;letter-spacing:.14em;color:#dce8ff}@media(max-width:520px){.sbc-concept-ribbon{gap:9px;padding:10px 14px}.sbc-concept-ribbon small{max-width:240px}.sbc-concept-tag{font-size:8px;padding:4px 6px}}</style>';
  const premiumHtml=String(result.html||'').replace('<body>','<body>'+previewRibbon);
  return premiumHtml.replace('</body>',checkoutBlock+'</body>');
}

