function seedLornaOnboardingProfileOnce(){
  const v=v9data();
  v.onboarding=v.onboarding||{};
  v.migrations=v.migrations||{};
  if(v.migrations.lornaOnboardingProfileV1)return false;
  const targets=(db.users||[]).filter(u=>isWorkforceRole(u.role)&&(
    /^lorna\b/i.test(String(u.name||'').trim()) ||
    String(u.email||u.profile?.email||'').trim().toLowerCase()==='lornaleona33@gmail.com'
  ));
  for(const u of targets){
    const old={...onboardingDefault(),...(v.onboarding[u.id]||{})};
    v.onboarding[u.id]={
      ...old,
      legalName:'Lorna Leona',
      preferredName:'Lorna',
      email:'lornaleona33@gmail.com',
      phone:'+639508966150',
      address:'Bagtang Road, Sagpon',
      city:'Daraga',
      region:'Albay',
      postalCode:'4501',
      country:'Philippines',
      timezone:'Asia/Manila',
      remoteLocation:'Philippines',
      paymentMethod:'Wise',
      paymentAccountLast4:'4204',
      updatedAt:now()
    };
    // Do not fabricate agreements, tax/ID completion, owner approval, or certification.
    v.onboarding[u.id].status='Incomplete';
    audit({id:'system',name:'SBC System',role:'owner'},'onboarding_profile_seeded',`Loaded Lorna onboarding profile from approved build data for ${u.name}`,{userId:u.id,preservedAcknowledgments:true,preservedOwnerVerification:true});
  }
  v.migrations.lornaOnboardingProfileV1=true;
  return targets.length>0;
}

