app.get('/api/v11/metrics',auth,(req,res)=>{
  if(!['owner','manager'].includes(req.user.role)) return res.status(403).json({error:'Owner or manager access required.'});
  const users=(db.users||[]).filter(u=>u.role!=='owner');
  const nowMs=Date.now(), dayMs=86400000;
  const parseT=x=>{const t=Date.parse(x||'');return Number.isFinite(t)?t:0};
  const minsFor=e=>{if(!e?.clockIn)return 0;let end=e.clockOut?parseT(e.clockOut):nowMs;let start=parseT(e.clockIn);if(!start)return 0;let m=Math.max(0,Math.round((end-start)/60000));for(const b of (e.breaks||[])){if(b.start&&b.end)m-=Math.max(0,Math.round((parseT(b.end)-parseT(b.start))/60000));}if(e.activeBreak?.start)m-=Math.max(0,Math.round((nowMs-parseT(e.activeBreak.start))/60000));return Math.max(0,m)};
  const calc=(uid,fromMs)=>{
    const entries=(v9data().timeEntries||[]).filter(e=>e.userId===uid&&parseT(e.clockIn)>=fromMs);
    const hours=entries.reduce((a,e)=>a+minsFor(e),0)/60;
    const leads=(db.customers||[]).filter(c=>c.researcherId===uid&&parseT(c.createdAt)>=fromMs);
    const qualified=leads.filter(c=>['Qualified','Proposal','Customer','Won','Closed Sale'].includes(String(c.status||''))).length;
    const rejected=leads.filter(c=>['Rejected','Lost','Disqualified','DNC'].includes(String(c.status||''))).length;
    const calls=(db.callReports||[]).filter(r=>r.callerId===uid&&parseT(r.createdAt)>=fromMs);
    const approvedCalls=calls.filter(r=>r.status==='Approved');
    const contacts=approvedCalls.filter(r=>['Connected','Interested','Appointment Requested','Closed Sale','Sale','Won'].includes(String(r.outcome||''))).length;
    const appointments=approvedCalls.filter(r=>r.appointmentRequested||r.outcome==='Appointment Requested').length;
    const sales=approvedCalls.filter(r=>['Closed Sale','Sale','Won'].includes(String(r.outcome||''))).length;
    const orders=(db.orders||[]).filter(o=>o.fulfillmentOwner===uid&&parseT(o.createdAt)>=fromMs);
    const completed=orders.filter(o=>['Ready','Delivered','Completed'].includes(String(o.status||''))).length;
    return {hours,leads:leads.length,qualified,rejected,qualificationRate:leads.length?qualified/leads.length*100:0,leadsPerHour:hours?leads.length/hours:0,calls:approvedCalls.length,contacts,appointments,sales,closeRate:approvedCalls.length?sales/approvedCalls.length*100:0,orders:orders.length,completedOrders:completed,completionRate:orders.length?completed/orders.length*100:0};
  };
  const from7=nowMs-7*dayMs,from30=nowMs-30*dayMs,from60=nowMs-60*dayMs;
  res.json({generatedAt:new Date().toISOString(),periods:{week:'Last 7 days',month:'Last 30 days',review:'Last 60 days'},employees:users.map(u=>({id:u.id,name:u.name,role:u.role,active:u.active!==false,week:calc(u.id,from7),month:calc(u.id,from30),review:calc(u.id,from60)}))});
});

