app.post('/api/v9/time/clock',auth,async(req,res)=>{const action=String(req.body?.action||''),mode=String(req.body?.mode||'training');if(isWorkforceRole(req.user.role)&&req.user.active===false)return res.status(403).json({error:'Your employee account is inactive.'});if(req.user.role==='caller'&&mode==='calling'&&!v9CanLiveCall(req.user))return res.status(403).json({error:'Live calling requires completed certification and owner approval.'});const v=v9data();v.timeEntries=v.timeEntries||[];let open=v.timeEntries.find(x=>x.userId===req.user.id&&!x.clockOut);if(action==='in'){if(open)return res.status(400).json({error:'You are already clocked in.'});open={id:id('time'),userId:req.user.id,userName:req.user.name,mode:['training','calling','admin'].includes(mode)?mode:'training',clockIn:now(),clockOut:null,breaks:[],activeBreak:null,createdAt:now()};v.timeEntries.unshift(open)}else if(action==='out'){if(!open)return res.status(400).json({error:'You are not clocked in.'});if(open.activeBreak?.start)return res.status(409).json({error:'End your active break before clocking out so the break is recorded correctly.'});open.clockOut=now();open.activeBreak=null}else if(action==='break_start'){if(!open)return res.status(400).json({error:'Clock in first.'});if(open.activeBreak)return res.status(400).json({error:'Break already started.'});open.activeBreak={start:now()}}else if(action==='break_end'){if(!open?.activeBreak)return res.status(400).json({error:'No active break is running.'});const started=Date.parse(open.activeBreak.start),ended=Date.now();if(!Number.isFinite(started)||ended<=started)return res.status(400).json({error:'The break timestamp is invalid. Please start the break again.'});open.breaks=Array.isArray(open.breaks)?open.breaks:[];open.breaks.push({start:open.activeBreak.start,end:new Date(ended).toISOString()});open.activeBreak=null}else return res.status(400).json({error:'Unknown clock action.'});await v9save(v);audit(req.user,'time_clock',`Time clock ${action}`,{mode:open?.mode||mode});res.json(open||{})})
app.get('/api/v9/time/status',auth,(req,res)=>{const v=v9data();res.json({open:(v.timeEntries||[]).find(x=>x.userId===req.user.id&&!x.clockOut)||null,entries:(v.timeEntries||[]).filter(x=>x.userId===req.user.id).slice(0,200)})})
app.post('/api/v9/assign-batch',auth,async(req,res)=>{if(!['owner','manager'].includes(req.user.role))return res.status(403).json({error:'Owner or manager access required.'});const uid=String(req.body?.userId||''),limit=Math.max(1,Math.min(500,Number(req.body?.amount||25)));const u=(db.users||[]).find(x=>x.id===uid&&x.active!==false&&x.role==='caller');if(!u)return res.status(400).json({error:'Select an active Sales Caller.'});const candidates=(db.customers||[]).filter(c=>!['Customer','Lost','DNC'].includes(c.status)&&c.assignedTo!==uid).filter(c=>!c.assignedTo||String(c.assignedTo)==='').slice(0,limit);candidates.forEach(c=>{c.assignedTo=u.id;c.assignedToName=u.name;c.updatedAt=now()});await saveData();audit(req.user,'lead_batch_assignment',`Assigned ${candidates.length} leads to ${u.name}`,{userId:u.id,amount:candidates.length});res.json({assigned:candidates.length,userId:u.id,userName:u.name,leadIds:candidates.map(x=>x.id)})});
app.get('/api/v9/lead-verification',auth,(req,res)=>{
  if(!['owner','manager','lead_researcher'].includes(req.user.role))return res.status(403).json({error:'Lead verification access required.'});
  const all=(db.customers||[]).map(normalizeLeadQuality);
  const mine=sbcLornaRole(req.user)?all.filter(c=>{if(Number(c.tenantId)!==Number(requireRequestTenant(req)))return false;const status=String(c.status||'Lead').trim().toLowerCase(),assigned=String(c.assignedTo||'');return !['customer','lost','do not call','dnc','closed','duplicate'].includes(status)&&(!assigned||assigned===String(req.user.id))&&(String(c.verificationStatus||'')!=='Sales Ready'||assigned===String(req.user.id));}):all;
  const stats={total:mine.length,hot:mine.filter(c=>c.leadTemperature==='Hot').length,warm:mine.filter(c=>c.leadTemperature==='Warm').length,cold:mine.filter(c=>c.leadTemperature==='Cold').length,needsVerification:mine.filter(c=>['Needs Verification','Owner Review'].includes(c.verificationStatus)).length,salesReady:mine.filter(c=>c.verificationStatus==='Sales Ready').length};
  res.json({stats,leads:mine.slice(0,1000),users:['owner','manager'].includes(req.user.role)?(db.users||[]).filter(u=>u.active!==false&&['lead_researcher','caller','manager','owner'].includes(u.role)).map(u=>({id:u.id,name:u.name,role:u.role})):[]});
});
app.post('/api/v9/lead-verification/:id',auth,async(req,res)=>{if(SBC_RUNTIME_READ_ONLY||MYSQL_RECOVERY_REQUIRED||!MYSQL_RECOVERY_EVALUATED||!sbcWriterLeaseReady)return res.status(423).json({error:'CRM writer/recovery gate unavailable. No lead updated.'});
  const allowed=['owner','manager','lead_researcher']; if(!allowed.includes(req.user.role))return res.status(403).json({error:'Lead verification access required.'});
  const c=(db.customers||[]).find(x=>String(x.id)===String(req.params.id)); if(!c)return res.status(404).json({error:'Lead not found.'});
  if(sbcLornaRole(req.user)){const tid=Number(requireRequestTenant(req)),uid=String(req.user.id),assigned=String(c.assignedTo||''),status=String(c.status||'Lead').toLowerCase();if(Number(c.tenantId)!==tid||['customer','lost','do not call','dnc','closed','duplicate','deleted'].includes(status)||(assigned&&assigned!==uid)||(String(c.verificationStatus||'')==='Sales Ready'&&assigned!==uid))return res.status(403).json({error:'Lead is outside your permitted research queue.'});}const b=req.body||{};
  for(const k of ['businessName','contactName','phone','email','website','industry','city','zip','notes','source','verificationSource']) if(b[k]!==undefined)c[k]=String(b[k]||'');
  if(req.user.role==='lead_researcher'&&b.assignedTo!==undefined&&String(b.assignedTo)!==String(req.user.id))return res.status(403).json({error:'Researchers may verify and submit leads, but only owner/manager may reassign them.'});
  if(['owner','manager'].includes(req.user.role)&&b.assignedTo!==undefined){const uid=String(b.assignedTo||'');const u=uid?(db.users||[]).find(x=>x.id===uid&&x.active!==false&&['lead_researcher','caller'].includes(x.role)):null;if(uid&&!u)return res.status(400).json({error:'Select an active lead researcher or sales manager/caller.'});c.assignedTo=uid;c.assignedToName=u?.name||'';}
  if(b.verificationStatus!==undefined)c.verificationStatus=['Needs Verification','Verified','Owner Review','Sales Ready'].includes(String(b.verificationStatus))?String(b.verificationStatus):'Needs Verification';
  normalizeLeadQuality(c);
  if(c.verificationStatus==='Verified'&&c.leadTemperature==='Hot')c.verificationStatus='Sales Ready';
  if(c.verificationStatus==='Sales Ready'&&c.leadTemperature==='Cold')c.verificationStatus='Needs Verification';
  c.updatedAt=now();
  audit(req.user,'lead_verification_update',`Updated lead verification for ${c.businessName||c.phone||c.id}`,{customerId:c.id,verificationStatus:c.verificationStatus,leadTemperature:c.leadTemperature,assignedTo:c.assignedTo||''});
  await saveData();
  res.json(c);
});
