app.post('/api/v9/call-report/:id/approve',auth,ownerOnly,async(req,res)=>{const r=(db.callReports||[]).find(x=>x.id===req.params.id);if(!r)return res.status(404).json({error:'Call report not found.'});const c=db.customers.find(x=>x.id===r.customerId);if(!c)return res.status(404).json({error:'Lead not found.'});if(r.contactName)c.contactName=r.contactName;if(r.outcome==='Interested'||r.outcome==='Appointment Requested'||r.orderReady)c.status=r.appointmentRequested?'Qualified':'Contacted';if(r.callbackAt)c.followUp=r.callbackAt.slice(0,10);if(r.callbackAt){const m=megaData();if(!m.nextActions.some(x=>x.callReportId===r.id&&x.type==='Callback Follow-up'&&x.status!=='Completed')){m.nextActions.unshift({id:id('next'),callReportId:r.id,customerId:c.id,customerName:c.businessName||c.contactName||'Lead',title:`Callback — ${c.businessName||c.contactName||'Lead'}`,type:'Callback Follow-up',priority:'High',status:'Open',dueAt:new Date(r.callbackAt).toISOString(),ownerId:r.callerId||'',notes:'Callback requested during sales call. Review the approved call report before calling.',createdAt:now(),updatedAt:now()});m.automationEvents.unshift({id:id('evt'),type:'callback_followup_created',customerId:c.id,message:`Created callback follow-up for ${c.businessName||c.contactName||'Lead'}`,createdAt:now()});await megaSave(m)}}const chunks=[r.need&&`Need: ${r.need}`,r.pain&&`Pain: ${r.pain}`,r.requirements&&`Requirements: ${r.requirements}`,r.quantity&&`Quantity: ${r.quantity}`,r.timeline&&`Timeline: ${r.timeline}`,r.websiteDemoUrl&&`Website Demo: ${r.websiteDemoUrl}`,r.notes&&r.notes].filter(Boolean);if(chunks.length)c.notes=chunks.join('\n');if(r.websiteDemoUrl){const v=v9data();v.websiteDemos[c.id]={...(v.websiteDemos[c.id]||{}),customerId:c.id,businessName:c.businessName||c.contactName||'Lead',url:r.websiteDemoUrl,status:'Sent',sentAt:now(),sentVia:'caller',updatedAt:now()};await v9save(v)}r.status='Approved';r.reviewedAt=now();r.reviewedBy=req.user.id;audit(req.user,'v9_call_report_approved',`Approved call report for ${c.businessName||c.contactName}`,{callReportId:r.id,customerId:c.id});await saveData();res.json({ok:true,customer:c,report:r})})
