app.post('/api/v10/leads/submit',auth,async(req,res)=>{
  try{
    if(!canSubmitResearchLeads(req.user))return res.status(403).json({error:'Lead research access required.'});
    const b=req.body||{},first=(...v)=>v.map(x=>String(x??'').trim()).find(Boolean)||'';
    const business=first(b.businessName,b.business_name,b.company),phone=first(b.phone),email=first(b.email);
    if(!business&&!phone&&!email)return res.status(400).json({error:'Business name, phone or email is required.'});

    // V55.18 — Lorna production write path: check both the in-memory CRM and
    // the canonical MySQL store so a second app process cannot create a duplicate.
    const normPhone=phone.replace(/\D/g,'');
    const normEmail=email.toLowerCase();
    const normBusiness=business.toLowerCase();
    const localDup=db.customers.some(c=>
      (normPhone&&String(c.phone||'').replace(/\D/g,'')===normPhone)||
      (normEmail&&String(c.email||'').toLowerCase()===normEmail)||
      (normBusiness&&String(c.businessName||'').toLowerCase()===normBusiness)
    );
    if(localDup)return res.status(409).json({error:'Possible duplicate lead already exists.',duplicate:true});

    if(mysqlPool){
      const [rows]=await mysqlPool.query(
        `SELECT id FROM sbc_customers WHERE
          (? <> '' AND REPLACE(REPLACE(REPLACE(REPLACE(phone,'-',''),' ',''),'(',''),')','') = ?)
          OR (? <> '' AND LOWER(email)=LOWER(?))
          OR (? <> '' AND LOWER(business_name)=LOWER(?))
          LIMIT 1`,
        [normPhone,normPhone,normEmail,email,normBusiness,business]
      );
      if(rows.length)return res.status(409).json({error:'Possible duplicate lead already exists in the central CRM.',duplicate:true});
    }

    const createdAt=now();
    const tenantId=requireRequestTenant(req);
    const c={id:id('cust'),tenantId,businessName:business,contactName:first(b.contactName,b.contact_name),phone,email,status:'Lead',source:first(b.source)||'Lead Research',followUp:'',notes:first(b.notes)||'Submitted by lead research.',website:first(b.website),websiteStatus:first(b.websiteStatus,b.website_status)||(!b.website?'No Website':''),address:first(b.address),industry:first(b.industry),dealValue:Number(b.dealValue||0),assignedTo:'',createdAt,updatedAt:createdAt,researcherId:req.user.id,researcherName:req.user.name||req.user.username||'Lead Research'};

    // The central CRM write happens before reporting success. This is deliberately
    // independent of the large snapshot writer: one employee lead must not depend
    // on unrelated settings/orders/fulfillment rows being writable at that moment.
    if(mysqlPool){
      await mysqlPool.query(
        `INSERT INTO sbc_customers
          (id,tenant_id,business_name,contact_name,phone,email,status,source,follow_up,notes,website,industry,website_status,assigned_to,account_notes_json,created_at,updated_at)
         VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`,
        [c.id,c.businessName,c.contactName,c.phone,c.email,c.status,c.source,null,c.notes,c.website,c.industry,c.websiteStatus,c.assignedTo,'[]',sqlDateTime(c.createdAt),sqlDateTime(c.updatedAt)]
      );
    }

    // Only after the canonical write succeeds do we mutate the live CRM object.
    db.customers.unshift(c);
    assignLeadAutomatically(c);
    enqueueLeadAssist(c.id,'lead_submission','high');
    try{SUPERNOVA_V2.appendWrite('lead.created',{event:'lead.created',businessName:c.businessName,contactName:c.contactName,phone:c.phone,email:c.email,source:c.source,customerId:c.id,researcherId:c.researcherId},req.user?.tenantId||'1')}catch{}
    addActivity('customer',`Added ${c.businessName||c.contactName||c.phone} from ${c.researcherName}`,{customerId:c.id,source:c.source,researcherId:c.researcherId,researcherName:c.researcherName});
    audit(req.user,'lead_submitted',`Submitted lead ${business||phone}`,{customerId:c.id,leadAssistQueued:true,source:c.source,researcherId:c.researcherId});

    // The direct lead write above is durable. Queue the broader snapshot as a
    // secondary synchronization task; a failure here must not turn a saved lead
    // into a false error or roll back the canonical CRM record.
    saveData().catch(e=>console.warn('[SBC LEAD] secondary CRM snapshot sync:',e?.message||e));

    let persistence={local:true,mysql:Boolean(mysqlPool),verified:true,writeMode:mysqlPool?'direct-relational':'local-fallback'};
    if(mysqlPool){
      const [rows]=await mysqlPool.query('SELECT id FROM sbc_customers WHERE id=? LIMIT 1',[c.id]);
      persistence.verified=Boolean(rows.length);
      if(!rows.length)return res.status(503).json({error:'The central CRM write could not be verified. Please try Save Lead again.',retryable:true,requestId:req.requestId||null});
    }
    res.status(201).json({...c,persistence,leadAssist:{status:'QUEUED',message:'Lead saved to the central SBC CRM and queued for automatic verification.'}});
  }catch(e){
    console.error('[SBC LEAD SUBMIT] failed:',e);
    res.status(500).json({error:`Lead could not be saved: ${String(e?.message||'central CRM write failed')}`.slice(0,500),retryable:true,requestId:req.requestId||null});
  }
});


// ===================== SBC MEGA OPERATIONS =====================

function salesCaller(){return (db.users||[]).find(u=>u.role==='caller'&&u.active!==false)}
function assignLeadAutomatically(c){const m=megaData();if(m.settings.autoAssignSales===false||c.assignedTo)return;const u=salesCaller();if(!u)return;c.assignedTo=u.id;c.assignedToName=u.name;m.nextActions.unshift({id:id('next'),customerId:c.id,customerName:c.businessName||c.contactName||'Lead',title:'Call new qualified lead',type:'Call',priority:'High',status:'Open',dueAt:new Date(Date.now()+2*3600000).toISOString(),ownerId:u.id,notes:'Auto-assigned by SBC Lead Engine.',createdAt:now(),updatedAt:now()});megaSave(m);audit({id:'system',name:'SBC Automation',role:'system'},'lead_auto_assigned',`Assigned ${c.businessName||c.contactName||c.phone} to ${u.name}`,{customerId:c.id,userId:u.id})}
function ensureCommissionForSale(sale){
  const m=megaData();
  const saleId=String(sale?.quoteId||sale?.orderId||'');
  const sourceType=sale?.orderId?'sales_order':'quote';
  if(!saleId)return null;
  if(m.approvals.some(x=>x.type==='commission'&&((sourceType==='sales_order'&&x.orderId===saleId)||(sourceType==='quote'&&x.quoteId===saleId))))return null;
  const repId=String(sale?.salesRepId||sale?.assignedTo||''); if(!repId)return null;
  const rep=(db.users||[]).find(u=>u.id===repId); if(!rep)return null;
  const price=Math.max(0,Number(sale?.total??sale?.price??0)); if(price<=0)return null;
  const items=Array.isArray(sale?.items)?sale.items:[];
  const pkg=items.find(i=>i.packageId||i.id==='quickstart'||i.id==='starter'||i.id==='essentials'||i.id==='professional'||i.id==='growth')||items[0]||{};
  const packageId=String(pkg.packageId||pkg.id||'');
  const comp=compFor(repId);
  const rate=Math.max(0,Math.min(0.25,commissionRateForSale(price,packageId,comp)));
  const commission=Math.round(price*rate*100)/100;
  const baseDate=sale?.paidAt||sale?.updatedAt||now();
  const eligibleAt=commissionEligibleAt(baseDate,comp);
  const record={id:id('comm'),type:'commission',status:'Pending Owner Approval',sourceType,quoteId:sale?.quoteId||'',orderId:sale?.orderId||'',customerId:sale?.customerId||'',customerName:sale?.customerName||'',employeeId:repId,employeeName:rep.name||'',packageId,packageName:pkg.name||sale?.product||'',saleAmount:price,commissionRate:rate,commissionAmount:commission,highValueBonus:0,totalPotential:commission,eligibleAt,returnWindowDays:Number(comp.returnWindowDays??14),commissionPayCycleDays:Number(comp.commissionPayCycleDays??30),createdAt:now(),updatedAt:now()};
  m.approvals.unshift(record);
  createMegaEvent('commission_created',`Commission created for ${rep.name||'sales rep'} · ${sale?.customerName||'Customer'}`,{commissionId:record.id,orderId:record.orderId,quoteId:record.quoteId,amount:commission,eligibleAt});
  megaSave(m);
  return record;
}

function processMegaAutomation(){try{const m=megaData(),nowMs=Date.now();const staleDays=Number(m.settings.staleLeadDays||2);for(const c of db.customers||[]){if(['Customer','Lost'].includes(c.status))continue;const last=new Date(c.updatedAt||c.createdAt||0).getTime();if(last&&nowMs-last>staleDays*864e5&&!m.nextActions.some(x=>x.customerId===c.id&&x.type==='Stale Lead'&&x.status!=='Completed'))m.nextActions.unshift({id:id('next'),customerId:c.id,customerName:c.businessName||c.contactName||'Lead',title:'Review stale lead',type:'Stale Lead',priority:'High',status:'Open',dueAt:now(),ownerId:c.assignedTo||'',notes:`No meaningful activity for ${staleDays}+ days.`,createdAt:now(),updatedAt:now()})}for(const r of db.renewals||[]){if(r.status==='Paid')continue;const days=Math.ceil((new Date(r.dueDate)-new Date(nowMs))/864e5);if([60,30,14,7].includes(days)&&!m.nextActions.some(x=>x.renewalId===r.id&&x.reminderDays===days)){m.nextActions.unshift({id:id('next'),renewalId:r.id,customerId:r.customerId,customerName:r.customerName,title:`Renewal reminder — ${r.service}`,type:'Renewal',priority:days<=14?'High':'Normal',status:'Open',dueAt:now(),ownerId:'',notes:`Renewal due in ${days} days.`,reminderDays:days,createdAt:now(),updatedAt:now()})}}
for(const q of db.quotes||[]){if(!['Sent','Quoted'].includes(q.status)||!q.customerId)continue;const age=nowMs-new Date(q.updatedAt||q.createdAt||0).getTime();if(age>24*3600000&&!m.nextActions.some(x=>x.quoteId===q.id&&x.type==='Quote Follow-up'&&x.status!=='Completed')){m.nextActions.unshift({id:id('next'),quoteId:q.id,customerId:q.customerId,customerName:q.customerName,title:`Follow up on ${q.quoteNumber}`,type:'Quote Follow-up',priority:'High',status:'Open',dueAt:now(),ownerId:'',notes:'Quote has been sent/quoted for more than 24 hours without a closed outcome.',createdAt:now(),updatedAt:now()})}}
for(const a of db.appointments||[]){if(['Cancelled','Completed'].includes(a.status))continue;const start=new Date(a.startAt).getTime();const hours=(start-nowMs)/3600000;if(hours>0&&hours<=24&&!m.nextActions.some(x=>x.appointmentId===a.id&&x.type==='Appointment Reminder'&&x.status!=='Completed')){m.nextActions.unshift({id:id('next'),appointmentId:a.id,customerId:a.customerId,customerName:a.customerName,title:`Appointment reminder — ${a.title}`,type:'Appointment Reminder',priority:'High',status:'Open',dueAt:now(),ownerId:'',notes:`Appointment scheduled for ${new Date(a.startAt).toLocaleString()}.`,createdAt:now(),updatedAt:now()})}}m.automationEvents.unshift({id:id('evt'),type:'automation_tick',message:'Mega automation health check completed',createdAt:now()});m.automationEvents=m.automationEvents.slice(0,500);megaSave(m)}catch(e){const m=megaData();m.automationFailures.unshift({id:id('fail'),status:'Open',message:e.message,createdAt:now()});m.automationFailures=m.automationFailures.slice(0,100);megaSave(m)}}
function megaVisible(req){const m=megaData(),r=req.user.role;if(r==='owner'||r==='manager')return m;return {...m,nextActions:m.nextActions.filter(x=>!x.ownerId||x.ownerId===req.user.id),projects:m.projects.filter(x=>!x.assignedTo||x.assignedTo===req.user.id),tickets:m.tickets.filter(x=>!x.assignedTo||x.assignedTo===req.user.id)};}
