function nextOpsState(){ db.nextOperations=NEXTOPS.ensure(db.nextOperations&&typeof db.nextOperations==='object'?db.nextOperations:{}); return db.nextOperations; }
function broadcastNextOps(payload){ try { const wss=global.__SBC_WSS; if(!wss)return; const msg=JSON.stringify(payload); for(const client of wss.clients||[]) if(client.readyState===1) client.send(msg); } catch(e){ console.warn('Broadcast:',e.message); } }
async function saveNextOps(){ await saveData(); }
function nextOpsGuard(req,res,roles=['owner','manager','caller','fulfillment']){ if(!req.user?.id) return res.status(401).json({error:'SBC login required.'}); if(!roles.includes(String(req.user.role||''))) return res.status(403).json({error:'This operations capability is restricted to authorized SBC team roles.'}); return true; }

