function leadAssistProviderConfig(){
  const twSid=secretValue('TWILIO_ACCOUNT_SID','SBC_TWILIO_ACCOUNT_SID');
  const twToken=secretValue('TWILIO_AUTH_TOKEN','SBC_TWILIO_AUTH_TOKEN');
  return {googleApiKey:secretValue('GOOGLE_MAPS_API_KEY','GOOGLE_PLACES_API_KEY','SBC_GOOGLE_MAPS_API_KEY'),hunterApiKey:secretValue('HUNTER_API_KEY','SBC_HUNTER_API_KEY'),apolloApiKey:secretValue('APOLLO_API_KEY','SBC_APOLLO_API_KEY'),twilio:{accountSid:twSid,authToken:twToken}};
}
function leadAssistQueue(){db.leadAssistQueue=Array.isArray(db.leadAssistQueue)?db.leadAssistQueue:[];return db.leadAssistQueue;}
function enqueueLeadAssist(customerId,reason='lead_submitted',priority='normal'){
  const q=leadAssistQueue(), existing=q.find(x=>String(x.customerId)===String(customerId)&&['QUEUED','PROCESSING'].includes(x.status));
  if(existing){existing.priority=priority==='high'?'high':existing.priority;existing.updatedAt=now();return existing;}
  const item={id:id('laq'),customerId:String(customerId),reason,status:'QUEUED',priority,attempts:0,createdAt:now(),updatedAt:now()};q.unshift(item);db.leadAssistQueue=q.slice(0,5000);return item;
}
async function processLeadAssistQueue(limit=5,scopedTenantId=null){
  const q=leadAssistQueue();const work=q.filter(x=>x.status==='QUEUED'&&(scopedTenantId===null||(db.customers||[]).some(c=>String(c.id)===String(x.customerId)&&Number(c.tenantId)===scopedTenantId))).sort((a,b)=>(a.priority==='high'?0:1)-(b.priority==='high'?0:1)||new Date(a.createdAt)-new Date(b.createdAt)).slice(0,Math.max(1,Math.min(10,limit)));const out=[];
  for(const job of work){const c=(db.customers||[]).find(x=>String(x.id)===String(job.customerId));if(!c){job.status='SKIPPED';job.error='Lead no longer exists.';continue;}job.status='PROCESSING';job.attempts=Number(job.attempts||0)+1;job.updatedAt=now();
    try{
      const publicResearch=await LEAD_INTELLIGENCE.enrichBusiness(c);
      const cfg=leadAssistProviderConfig();
      const result=await LEAD_ASSIST.run(c,{publicResearch,...cfg});
      const before={businessName:c.businessName,contactName:c.contactName,email:c.email,phone:c.phone,website:c.website,address:c.address,city:c.city,industry:c.industry};
      const m=result.merged||{};
      for(const k of ['businessName','contactName','email','phone','website','address','city','industry']) if(!c[k]&&m[k]) c[k]=m[k];
      c.leadResearch={status:'ENRICHED',checkedAt:result.checkedAt,reachable:publicResearch.reachable,emailFound:Boolean(result.merged?.email),phoneFound:Boolean(result.merged?.phone),emails:result.emailCandidates||publicResearch.emails||[],phones:publicResearch.phones||[],socials:publicResearch.socials||[],addresses:publicResearch.addresses||[],industryHints:publicResearch.industryHints||[],sourceUrls:publicResearch.sourceUrls||[],pages:publicResearch.pages||[],providerEvidence:result.providers||{},emailVerifications:result.emailVerifications||[],autoVerify:result.autoVerify,confidence:result.score?.confidence,score:result.score?.score,note:result.note};
      c.leadAssist={status:result.autoVerify?'AUTO_VERIFIED':'NEEDS_HUMAN_REVIEW',score:result.score,hardChecks:result.hard,checkedAt:result.checkedAt,providerEvidence:result.providers||{},emailVerifications:result.emailVerifications||[],suggestedChanges:Object.fromEntries(Object.entries(m).filter(([k,v])=>v&&before[k]!==v)),reason:result.autoVerify?'Evidence and contactability thresholds passed.':'System found useful evidence but kept the lead for human confirmation.'};
      c.verificationSource='SBC Lead Assist Waterfall V55.16';c.updatedAt=now();
      const verification=await revenueVerifyLeadRecord(c);
      if(result.autoVerify&&verification.passed){c.verificationStatus='Sales Ready';c.leadAssist.status='AUTO_VERIFIED';}else if(c.verificationStatus!=='Sales Ready')c.verificationStatus='Owner Review';
      job.status='COMPLETE';job.result={verificationStatus:c.verificationStatus,autoVerify:result.autoVerify,score:result.score};job.updatedAt=now();out.push({customerId:c.id,businessName:c.businessName,status:job.status,leadAssist:c.leadAssist,verification});
      audit({id:'system',name:'SBC Lead Assist',role:'system'},'lead_assist_completed',`Lead Assist reviewed ${c.businessName||c.contactName||c.id}`,{customerId:c.id,reason:job.reason,autoVerify:result.autoVerify,score:result.score,verificationStatus:c.verificationStatus,before,after:{email:c.email,phone:c.phone,website:c.website,address:c.address,contactName:c.contactName}});
    }catch(e){job.status=job.attempts>=3?'FAILED':'QUEUED';job.error=String(e.message||e).slice(0,500);job.updatedAt=now();out.push({customerId:c.id,businessName:c.businessName,status:job.status,error:job.error});}
  }
  if(work.length)await saveData();return {processed:work.length,results:out,pending:q.filter(x=>x.status==='QUEUED'&&(scopedTenantId===null||(db.customers||[]).some(c=>String(c.id)===String(x.customerId)&&Number(c.tenantId)===scopedTenantId))).length};
}
