app.post('/api/lead-assist/run',auth,SBC_V6662_LEAD_TENANT,async(req,res)=>{if(!['owner','manager','lead_researcher'].includes(req.user.role))return res.status(403).json({error:'Lead Assist access requires owner, manager or lead researcher access.'});try{const max=Math.max(1,Math.min(10,Number(req.body?.limit||5)));const rows=(db.customers||[]).filter(c=>Number(c.tenantId)===req.sbcV6662TenantId).filter(c=>!['Customer','Lost','DNC'].includes(String(c.status||''))).filter(c=>c.leadAssist?.status!=='AUTO_VERIFIED').slice(0,max);for(const c of rows)enqueueLeadAssist(c.id,'manual_lead_assist_run',req.user.role==='owner'?'high':'normal');const result=await processLeadAssistQueue(max,req.sbcV6662TenantId);res.json({ok:true,...result});}catch(e){res.status(400).json({ok:false,error:e.message})}});
