app.post('/api/lead-assist/:customerId/review',auth,SBC_V6662_LEAD_TENANT,async(req,res)=>{if(!['owner','manager','lead_researcher'].includes(req.user.role))return res.status(403).json({error:'Lead Assist review access denied.'});const c=(db.customers||[]).find(x=>String(x.id)===String(req.params.customerId)&&Number(x.tenantId)===req.sbcV6662TenantId);if(!c)return res.status(404).json({error:'Lead not found.'});const allowed=['approve','reject','requeue'];const action=String(req.body?.action||'').toLowerCase();if(!allowed.includes(action))return res.status(400).json({error:'Action must be approve, reject or requeue.'});if(action==='approve'){c.leadAssist={...(c.leadAssist||{}),status:'HUMAN_APPROVED',approvedBy:req.user.id,approvedAt:now()};const v=await revenueVerifyLeadRecord(c);if(v.passed)c.verificationStatus='Sales Ready';else c.verificationStatus='Needs Verification';}else if(action==='reject'){c.leadAssist={...(c.leadAssist||{}),status:'HUMAN_REJECTED',rejectedBy:req.user.id,rejectedAt:now()};c.verificationStatus='Needs Verification';}else{c.leadAssist={...(c.leadAssist||{}),status:'QUEUED',requeuedBy:req.user.id,requeuedAt:now()};enqueueLeadAssist(c.id,'human_requeue','high');}c.updatedAt=now();await saveData();audit(req.user,'lead_assist_human_review',`Lead Assist ${action} for ${c.businessName||c.id}`,{customerId:c.id,action,verificationStatus:c.verificationStatus});res.json({ok:true,customer:c});});
app.post('/api/lead-intelligence/enrich/:customerId',auth,SBC_V6662_LEAD_TENANT,async(req,res)=>{
  if(!['owner','manager','lead_researcher'].includes(req.user.role))return res.status(403).json({error:'Lead enrichment access requires owner, manager or lead researcher access.'});
  const c=(db.customers||[]).find(x=>String(x.id)===String(req.params.customerId)&&Number(x.tenantId)===req.sbcV6662TenantId);
  if(!c)return res.status(404).json({error:'Lead not found.'});
  if(req.user.role==='lead_researcher'&&c.assignedTo&&String(c.assignedTo)!==String(req.user.id))return res.status(403).json({error:'This lead is assigned to another researcher.'});
  try{
    const result=await LEAD_INTELLIGENCE.enrichBusiness(c);
    const before={email:c.email||'',phone:c.phone||'',website:c.website||'',contactName:c.contactName||'',city:c.city||'',industry:c.industry||'',address:c.address||''};
    if(!c.email&&result.email)c.email=String(result.email).trim().toLowerCase();
    if(!c.phone&&result.phone)c.phone=String(result.phone).trim();
    if(!c.website&&result.website)c.website=String(result.website).trim();
    if(!c.address&&result.addresses?.[0])c.address=result.addresses[0];
    if(!c.industry&&result.industryHints?.[0])c.industry=result.industryHints[0];
    c.leadResearch={
      status:'ENRICHED',checkedAt:result.checkedAt,reachable:result.reachable,emailFound:Boolean(result.emails?.length),phoneFound:Boolean(result.phones?.length),
      emails:result.emails||[],phones:result.phones||[],socials:result.socials||[],addresses:result.addresses||[],industryHints:result.industryHints||[],sourceUrls:result.sourceUrls||[],pages:result.pages||[],
      note:'Public-source enrichment only. Email/domain checks do not prove mailbox ownership or human identity.'
    };
    c.verificationSource=c.verificationSource||'SBC Public Web Research';
    c.updatedAt=now();
    const verification=await revenueVerifyLeadRecord(c);
    await saveData();
    audit(req.user,'lead_public_enrichment',`Enriched ${c.businessName||c.contactName||c.id}`,{customerId:c.id,before,after:{email:c.email||'',phone:c.phone||'',website:c.website||'',contactName:c.contactName||'',city:c.city||'',industry:c.industry||'',address:c.address||''},sourceUrls:result.sourceUrls||[],verificationStatus:c.verificationStatus});
    res.json({ok:true,customer:c,enrichment:result,verification});
  }catch(e){res.status(400).json({ok:false,error:e.message||'Lead enrichment failed.'});}
});
app.post('/api/lead-intelligence/enrich-batch',auth,SBC_V6662_LEAD_TENANT,async(req,res)=>{
  if(!['owner','manager','lead_researcher'].includes(req.user.role))return res.status(403).json({error:'Lead enrichment access requires owner, manager or lead researcher access.'});
  const max=Math.max(1,Math.min(10,Number(req.body?.limit||10)));
  let rows=(db.customers||[]).filter(c=>Number(c.tenantId)===req.sbcV6662TenantId).filter(c=>!['Customer','Lost','DNC'].includes(String(c.status||'')));
  if(req.user.role==='lead_researcher')rows=rows.filter(c=>!c.assignedTo||String(c.assignedTo)===String(req.user.id));
  rows=rows.filter(c=>String(c.leadResearch?.status||'')!=='ENRICHED').slice(0,max);
  const results=[];
  for(const c of rows){
    try{
      const result=await LEAD_INTELLIGENCE.enrichBusiness(c);
      if(!c.email&&result.email)c.email=String(result.email).trim().toLowerCase();
      if(!c.phone&&result.phone)c.phone=String(result.phone).trim();
      if(!c.website&&result.website)c.website=String(result.website).trim();
      if(!c.address&&result.addresses?.[0])c.address=result.addresses[0];
      if(!c.industry&&result.industryHints?.[0])c.industry=result.industryHints[0];
      c.leadResearch={status:'ENRICHED',checkedAt:result.checkedAt,reachable:result.reachable,emailFound:Boolean(result.emails?.length),phoneFound:Boolean(result.phones?.length),emails:result.emails||[],phones:result.phones||[],socials:result.socials||[],addresses:result.addresses||[],industryHints:result.industryHints||[],sourceUrls:result.sourceUrls||[],pages:result.pages||[],note:'Public-source enrichment only. Email/domain checks do not prove mailbox ownership or human identity.'};
      c.verificationSource=c.verificationSource||'SBC Public Web Research'; c.updatedAt=now();
      const verification=await revenueVerifyLeadRecord(c); results.push({customerId:c.id,businessName:c.businessName,email:c.email||'',phone:c.phone||'',website:c.website||'',verificationStatus:c.verificationStatus,verification});
    }catch(e){results.push({customerId:c.id,businessName:c.businessName,error:e.message})}
  }
  if(results.length)await saveData();
  audit(req.user,'lead_public_enrichment_batch',`Enriched ${results.length} existing leads`,{count:results.length,limit:max});
  res.json({ok:true,processed:results.length,remaining:(db.customers||[]).filter(c=>!['Customer','Lost','DNC'].includes(String(c.status||''))&&!c.leadResearch?.status).length,results});
});
