function acquisitionRecordFor(customerId){
  db.acquisition=db.acquisition||{opportunities:[],outreachDrafts:[]};
  return db.acquisition.opportunities.find(x=>String(x.customerId)===String(customerId));
}
async function persistAcquisitionOpportunity(o){
  db.acquisition=db.acquisition||{opportunities:[],outreachDrafts:[]};
  const i=db.acquisition.opportunities.findIndex(x=>x.id===o.id);if(i>=0)db.acquisition.opportunities[i]=o;else db.acquisition.opportunities.unshift(o);
  db.acquisition.opportunities=db.acquisition.opportunities.slice(0,5000);
  await saveData();
  if(mysqlPool){await mysqlPool.query(`INSERT INTO sbc_acquisition_opportunities(id,tenant_id,customer_id,score,tier,status,analysis_json,demo_id,demo_url,outreach_draft_count,last_action,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE score=VALUES(score),tier=VALUES(tier),status=VALUES(status),analysis_json=VALUES(analysis_json),demo_id=VALUES(demo_id),demo_url=VALUES(demo_url),outreach_draft_count=VALUES(outreach_draft_count),last_action=VALUES(last_action),updated_at=VALUES(updated_at)`,[o.id,TENANT_DEFAULT_ID,o.customerId,o.score,o.tier,o.status,JSON.stringify(o.analysis||{}),o.demoId||'',o.demoUrl||'',Number(o.outreachDraftCount||0),o.lastAction||'',sqlDateTime(o.createdAt),sqlDateTime(o.updatedAt)]).catch(e=>console.warn('[ACQUISITION] MySQL persist:',e.message));}
  return o;
}
async function persistAcquisitionDraft(d){
  db.acquisition=db.acquisition||{opportunities:[],outreachDrafts:[]};db.acquisition.outreachDrafts.unshift(d);db.acquisition.outreachDrafts=db.acquisition.outreachDrafts.slice(0,5000);await saveData();
  if(mysqlPool){await mysqlPool.query(`INSERT INTO sbc_acquisition_outreach(id,tenant_id,opportunity_id,customer_id,channel,subject,body,status,created_at) VALUES (?,?,?,?,?,?,?,?,?)`,[d.id,TENANT_DEFAULT_ID,d.opportunityId,d.customerId,d.channel,d.subject||'',d.body,d.status,sqlDateTime(d.createdAt)]).catch(e=>console.warn('[ACQUISITION] outreach persist:',e.message));}
  return d;
}
