app.post('/api/public/demo-checkout/:slug',async(req,res)=>{
  try{
    const d=megaData().websiteDemos.find(x=>x.slug===req.params.slug&&!x.archived);
    if(!d)return res.status(404).json({ok:false,error:'Demo not found.'});
    const c=(db.customers||[]).find(x=>String(x.id)===String(d.customerId));
    if(!c)return res.status(404).json({ok:false,error:'Demo customer not found.'});
    const tenantId=Number(c.tenantId);if(!Number.isSafeInteger(tenantId)||tenantId<1)return res.status(403).json({ok:false,error:'TENANT_CONTEXT_REQUIRED'});
    const allowed=new Set(['starter','essentials','professional','growth','quickstart']);
    const packageId=String(req.body?.packageId||'starter');
    if(!allowed.has(packageId))return res.status(400).json({ok:false,error:'Unsupported package.'});
    const pkg=CATALOG.packages.find(x=>x.id===packageId); if(!pkg||Number(pkg.price)<=0)return res.status(400).json({ok:false,error:'Package unavailable.'});
    const gate=V567_NINE_NINE.ownerGate(pkg.price); if(!gate.automationAllowed)return res.status(409).json({ok:false,error:'Owner approval required for this amount.'});
    let order=(db.orders||[]).find(o=>String(o.customerId)===String(c.id)&&String(o.product)===String(pkg.name)&&String(o.paymentStatus||'').toUpperCase()!=='PAID'&&String(o.status||'').toUpperCase()!=='CANCELLED');
    if(!order){order={id:id('ord'),tenantId,customerId:c.id,customerName:c.businessName||c.contactName||'Customer',product:pkg.name,quantity:1,status:'New',cost:0,price:Number(pkg.price),notes:JSON.stringify({source:'public-demo-checkout',demoId:d.id,packageId,autopilot:true}),createdAt:now(),updatedAt:now()};db.orders.unshift(order);addActivity('public_demo_checkout_order_created',`Created checkout order from demo for ${order.customerName}`,{orderId:order.id,demoId:d.id,packageId});await saveData();}
    const link=await createSquarePaymentLinkForOrder(order,{user:{id:'public-demo',name:'SBC Public Demo'}});
    REVENUE_EVENT_BROKER_V56160.publish('checkout_created',{tenantId,entityType:'customer',entityId:c.id,payload:{customerId:c.id,orderId:order.id,packageId,paymentUrl:link.url}}).catch(()=>{});
    res.json({ok:true,orderId:order.id,packageId,paymentUrl:link.url});
  }catch(e){res.status(400).json({ok:false,error:String(e.message||e)});}
});
