function isMgr(req){return ['owner','manager'].includes(req.user.role)}


// ===== V30.3 ENTERPRISE FOUNDATION — KIM SUPER-OWNER OVERSIGHT + DURABLE ARCHITECTURE =====
// Kim now has a deterministic background control loop in addition to the conversational AI.
// The loop performs only reversible, operational work. Protected financial/security actions
// remain evidence-gated or owner-controlled so automation cannot silently create a security hole.
const KIM_CONTROL_PLANE={version:BUILD_VERSION,intervalMs:60000,maxEvents:500};
const KIM_SYSTEM_ACTOR={id:'kim_system',name:'Kim',username:'kim',role:'system'};
// Kim is the operational co-owner when operating through Romeo's authenticated owner session.
// She may perform reversible/operational work across the Command Center, including fulfillment.
// Irreversible/destructive actions remain owner-only even when Kim is acting as co-owner.
function kimCoOwnerSession(req){return String(req.user?.role||'')==='owner';}
function kimProtectedAction(name){return ['delete_lead','delete_customer','delete_order','delete_database','change_owner_credentials','change_owner_security','refund_payment','override_payment_status','destroy_production_data'].includes(String(name));}

let kimControlBusy=false;
let kimControlTimer=null;
function kimControlState(){
  db.settings=db.settings&&typeof db.settings==='object'?db.settings:{};
  db.settings.kimControlPlane=db.settings.kimControlPlane&&typeof db.settings.kimControlPlane==='object'?db.settings.kimControlPlane:{};
  return db.settings.kimControlPlane;
}
async function kimWebsiteDiagnostics(){
  const urls=[String(db.settings?.website||'https://sbcmia.com'),String(db.settings?.websites||'https://sbcwebsites.com')].filter(Boolean);
  const out=[];
  for(const url of urls){
    const started=Date.now();
    try{
      const r=await fetch(url,{redirect:'follow',signal:AbortSignal.timeout(12000),headers:{'User-Agent':'SBC-Kim-Health/30.0'}});
      const text=await r.text();
      const lower=text.toLowerCase();
      out.push({url,status:r.status,ok:r.ok,latencyMs:Date.now()-started,https:String(url).startsWith('https://'),hasViewport:/<meta[^>]+name=["']viewport["']/i.test(text),hasSbcBrand:/successful by choice|sbc/i.test(text),hasAccount:/my sbc account|customer portal/i.test(lower),has99:/\$99/.test(text),hasPackages:/\$199|\$349|\$699/.test(text),hasLeadBridge:/api\/web-lead|web-lead/i.test(text),hasPortalBridge:/sbc_portal|portal/i.test(text),contentLength:text.length});
    }catch(e){out.push({url,status:0,ok:false,latencyMs:Date.now()-started,error:String(e.message||e).slice(0,300)});}
  }
  return {checkedAt:now(),sites:out};
}

function kimControlHealth(){
  const m=megaData(), nowMs=Date.now();
  const active=(db.customers||[]).filter(c=>!['Customer','Lost'].includes(c.status));
  const failures=(m.automationFailures||[]).filter(x=>x.status!=='Resolved');
  const pendingWebhooks=squareWebhookRecords().filter(x=>!x.processedAt&&['RECEIVED','RETRY'].includes(x.status)).length;
  return {
    staleLeads:active.filter(c=>c.followUp&&new Date(c.followUp).getTime()<nowMs-Number(m.settings.staleLeadDays||2)*864e5).length,
    overdueActions:reconciledOverdueActions(),
    waitingCustomer:(m.projects||[]).filter(x=>x.waitingOn==='Customer').length,
    waitingSbc:(m.projects||[]).filter(x=>x.waitingOn==='SBC').length,
    openTickets:(m.tickets||[]).filter(x=>x.status!=='Resolved').length,
    automationFailures:failures.length,
    pendingApprovals:(m.approvals||[]).filter(x=>x.status==='Pending Owner Approval').length,
    pendingSquareWebhooks:pendingWebhooks,
    activeProjects:(m.projects||[]).filter(x=>!['Completed','Cancelled'].includes(x.status)).length,
    activeLeads:active.length,
    customers:(db.customers||[]).filter(c=>c.status==='Customer').length,
    orders:(db.orders||[]).length,
    uptimeSeconds:Math.floor(process.uptime()),architectureVersion:ARCHITECTURE_VERSION,enterprise:enterpriseReadiness(),tenantId:TENANT_DEFAULT_ID
  };
}
async function kimRunControlPlane(reason='scheduled'){
  if(kimControlBusy)return {ok:true,skipped:true,reason:'A Kim control cycle is already running.'};
  kimControlBusy=true;
  const started=Date.now(), actions=[];
  try{
    const repaired=kimRepairCollectionShape();
    if(repaired.length)actions.push(`Repaired missing collections: ${repaired.join(', ')}`);
    let normalized=0,notes=0;
    for(const c of db.customers||[]){
      const before=JSON.stringify({verificationStatus:c.verificationStatus,leadTemperature:c.leadTemperature});
      if(!Array.isArray(c.accountNotes)){c.accountNotes=[];notes++;}
      normalizeLeadQuality(c);
      if(JSON.stringify({verificationStatus:c.verificationStatus,leadTemperature:c.leadTemperature})!==before)normalized++;
    }
    if(normalized)actions.push(`Normalized ${normalized} lead-quality records.`);
    if(notes)actions.push(`Restored account-note containers on ${notes} customer records.`);
    try{await syncAllSalesQueues();actions.push('Reconciled active sales queues.')}catch(e){actions.push(`Sales queue reconciliation deferred: ${e.message}`);}
    try{processMegaAutomation();actions.push('Ran stale-lead, quote, appointment and renewal automation.')}catch(e){actions.push(`Mega automation deferred: ${e.message}`);}
    try{await kimRunAutonomousOperations(`control-plane:${reason}`);actions.push('Ran Kim autonomous production operations.')}catch(e){actions.push(`Kim production cycle deferred: ${e.message}`);}
    try{await processPendingSquareWebhooks();actions.push('Processed pending verified Square webhook receipts.')}catch(e){actions.push(`Square recovery deferred: ${e.message}`);}
    const health=kimControlHealth();
    let websites=null; try{websites=await kimWebsiteDiagnostics(); actions.push('Checked live public website endpoints.')}catch(e){actions.push(`Website health check deferred: ${e.message}`);}
    let steward=null; try{steward=KIM_STEWARD.inspect(__dirname); actions.push(`System Steward inspected ${steward.scan.fileCount} application files (${steward.scan.findings.length} findings).`);}catch(e){actions.push(`System Steward inspection deferred: ${e.message}`);}
    const state=kimControlState();
    state.version=KIM_CONTROL_PLANE.version;state.lastRunAt=now();state.lastDurationMs=Date.now()-started;state.lastReason=String(reason);state.lastResult='OK';state.lastActions=actions.slice(0,30);state.health=health;state.websiteHealth=websites;state.steward=steward;state.nextRunAt=new Date(Date.now()+KIM_CONTROL_PLANE.intervalMs).toISOString();
    state.protectedBoundaries=['credentials','secrets','catalog/pricing','refunds','payment-status overrides','owner security','permanent deletion','irreversible database operations'];
    state.autonomy='routine operational work runs automatically; protected actions remain evidence-gated or owner-controlled';
    const m=megaData();m.automationEvents.unshift({id:id('evt'),type:'kim_control_cycle',message:`Kim autonomous control cycle completed (${reason})`,meta:{actions,health},createdAt:now()});m.automationEvents=m.automationEvents.slice(0,KIM_CONTROL_PLANE.maxEvents);db.megaOpsStore=m;
    await saveData();
    return {ok:true,version:KIM_CONTROL_PLANE.version,reason,actions,health,websiteHealth:websites,lastRunAt:state.lastRunAt,durationMs:state.lastDurationMs};
  }catch(e){
    const state=kimControlState();state.lastRunAt=now();state.lastDurationMs=Date.now()-started;state.lastReason=String(reason);state.lastResult='DEGRADED';state.lastError=String(e.message||e).slice(0,1000);state.health=kimControlHealth();
    try{await saveData()}catch{}
    return {ok:false,version:KIM_CONTROL_PLANE.version,reason,error:String(e.message||e).slice(0,1000),health:state.health};
  }finally{kimControlBusy=false;}
}
async function enterpriseWorkerCycle(){try{await publishOutbox();await processReadyFulfillmentJobs();}catch(e){jsonLog('error','enterprise_worker_cycle',{error:String(e.message||e)});architectureMetrics.errors++;}}
function startKimControlPlane(){
  if(kimControlTimer)clearInterval(kimControlTimer);
  setTimeout(()=>enterpriseWorkerCycle().catch(()=>{}),8000);
  setTimeout(async()=>{try{const st=kimControlState();if(!st.initialStewardSnapshot){const snap=KIM_STEWARD.snapshot(__dirname,'Initial Kim System Steward baseline for V55.5.0');st.initialStewardSnapshot=snap.snapshotId;await saveData();}}catch(e){console.warn('[KIM STEWARD] baseline snapshot:',e.message)} kimRunControlPlane('startup').catch(e=>console.error('[KIM CONTROL] startup:',e.message));},5000);
  kimControlTimer=setInterval(()=>{kimRunControlPlane('scheduled').catch(e=>console.error('[KIM CONTROL] scheduled:',e.message));enterpriseWorkerCycle().catch(()=>{});},KIM_CONTROL_PLANE.intervalMs);
}

