// Customer accounts are separate from employee/admin sessions. Passwords are scrypt-hashed;
// portal tokens are signed and expire after 30 days. Pricing/catalog mutations are never exposed here.
function findOrCreatePortalCustomer(body){
  const email=String(body.email||'').trim().toLowerCase();
  let c=(db.customers||[]).find(x=>Number(x.tenantId)===Number(body.tenantId)&&email && String(x.email||'').trim().toLowerCase()===email);
  if(!c){c={id:id('cust'),tenantId:Number(body.tenantId),businessName:String(body.businessName||'').trim(),contactName:String(body.contactName||'').trim(),phone:String(body.phone||'').trim(),email,website:String(body.website||'').trim(),address:String(body.address||'').trim(),city:String(body.city||'').trim(),region:String(body.region||'').trim(),postalCode:String(body.postalCode||'').trim(),industry:String(body.industry||'').trim(),status:'Lead',source:'SBC Website Portal',notes:'Customer created through SBC website customer portal.',followUp:'',assignedTo:'',createdAt:now(),updatedAt:now()};db.customers.unshift(c);addActivity('customer',`Website portal account created for ${c.businessName||c.contactName}`,{customerId:c.id,portal:true});}
  return c;
}
app.post('/api/portal/register',rateLimit(),async(req,res)=>{
  if(!sbcPortalSessionsConfigured())return res.status(503).json({ok:false,code:'SBC_PORTAL_SESSION_SECRET_REQUIRED'});
  let websiteTenant;try{websiteTenant=sbcVerifiedWebsiteTenant(req)}catch(e){return res.status(403).json({ok:false,code:e.code||'SITE_BRIDGE_UNAUTHORIZED'});}
  const b=req.body||{},email=String(b.email||'').trim().toLowerCase(),password=String(b.password||'');
  if(!/^\S+@\S+\.\S+$/.test(email))return res.status(400).json({error:'Enter a valid email address.'});
  if(password.length<8)return res.status(400).json({error:'Password must be at least 8 characters.'});
  if(!String(b.contactName||'').trim())return res.status(400).json({error:'Your name is required.'});
  const existingAccount=(db.customerAccounts||[]).find(a=>String(a.email||'').toLowerCase()===email&&a.active!==false);if(existingAccount?.passwordHash)return res.status(409).json({error:'An SBC customer account already exists for this email. Please log in.'});
  const tenantId=websiteTenant;
  // A self-registered email must not claim an existing CRM lead's data without verification.
  if((db.customers||[]).some(x=>Number(x.tenantId)===tenantId&&String(x.email||'').trim().toLowerCase()===email))return res.status(409).json({ok:false,error:'An SBC customer record exists. Contact SBC to activate your account securely.'});
  const c=findOrCreatePortalCustomer({...b,email,tenantId});
  c.contactName=String(b.contactName||c.contactName).trim(); c.phone=String(b.phone||c.phone||'').trim(); c.businessName=String(b.businessName||c.businessName||'').trim(); c.website=String(b.website||c.website||'').trim(); c.address=String(b.address||c.address||'').trim(); c.city=String(b.city||c.city||'').trim(); c.region=String(b.region||c.region||'').trim(); c.postalCode=String(b.postalCode||c.postalCode||'').trim(); c.industry=String(b.industry||c.industry||'').trim(); c.updatedAt=now();
  const account=existingAccount||{id:id('acct'),customerId:c.id,email,passwordHash:'',active:true,createdAt:now(),lastLoginAt:''};account.customerId=c.id;account.email=email;account.passwordHash=hashPassword(password);account.active=true;account.lastLoginAt=now();db.customerAccounts=db.customerAccounts||[];if(!existingAccount)db.customerAccounts.push(account);
  db.customerMessages=db.customerMessages||[];db.customerMessages.push({id:id('msg'),customerId:c.id,senderType:'system',senderName:'SBC',body:'Welcome to your SBC Customer Portal. Your account is ready. You can view your services, orders, messages and business profile here.',createdAt:now(),readAt:''});
  await saveData();res.status(201).json({ok:true,token:makePortalToken(account),customer:portalSafeCustomer(c)});
});
