// ===== V27.6.0 OPERATIONS HARDENING LAYER =====
// Controlled upgrade: adds security visibility, duplicate protection, pipeline stages,
// performance telemetry, lead cleansing and a single owner/manager operations surface.
const SBC_ROLE_PERMISSIONS={
  owner:['dashboard','customers','leads:create','leads:edit','leads:delete','leads:import','leads:verify','sales','quotes','payments','fulfillment','customers:message','team:manage','team:metrics','audit:read','settings:manage','kim:operate'],
  manager:['dashboard','customers','leads:create','leads:edit','leads:import','leads:verify','sales','quotes','fulfillment','customers:message','team:metrics','audit:read','kim:operate'],
  caller:['dashboard','customers:read-assigned','call:work','call:report','customers:message-assigned','kim:operate'],
  lead_researcher:['dashboard','customers:read-assigned','leads:create','leads:import','leads:verify','leads:cleanse','kim:operate'],
  fulfillment:['dashboard','fulfillment','customers:read','customers:message','kim:operate'],
  demo:['dashboard','customers:read','leads:read','fulfillment:read','payments:read','kim:read']
};
function hasPermission(req,permission){const role=req.user?.role||'';return role==='owner'||(SBC_ROLE_PERMISSIONS[role]||[]).includes(permission)}
function requirePermission(permission){return (req,res,next)=>hasPermission(req,permission)?next():res.status(403).json({error:`Permission denied: ${permission}.`})}
function normPhoneKey(v){const d=String(v||'').replace(/\D/g,'');return d.length>=7?d:''}
function normEmailKey(v){return String(v||'').trim().toLowerCase()}
function normBusinessKey(v){return String(v||'').trim().toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()}
function leadDuplicateMatches(candidate,excludeId=''){
  const phone=normPhoneKey(candidate.phone),email=normEmailKey(candidate.email),business=normBusinessKey(candidate.businessName),city=normBusinessKey(candidate.city);
  if(!phone&&!email&&!business)return [];
  return (db.customers||[]).filter(c=>String(c.id)!==String(excludeId)).map(c=>{
    const reasons=[];
    if(phone&&normPhoneKey(c.phone)===phone)reasons.push('phone');
    if(email&&normEmailKey(c.email)===email)reasons.push('email');
    if(business&&normBusinessKey(c.businessName)===business&&(!city||!c.city||normBusinessKey(c.city)===city))reasons.push('business');
    return reasons.length?{customer:c,reasons}:null;
  }).filter(Boolean).sort((a,b)=>b.reasons.length-a.reasons.length);
}
function pipelineStage(c){
  const explicit=String(c?.pipelineStage||'').trim();
  const allowed=['New Lead','Verified','Sales Ready','Contacted','Qualified','Proposal','Won','Fulfillment','Customer','Lost'];
  if(allowed.includes(explicit))return explicit;
  const status=String(c?.status||'Lead');
  if(status==='Customer')return 'Customer';
  if(['Won','Paid','Closed Sale'].includes(status))return 'Won';
  if(['Proposal','Quoted'].includes(status))return 'Proposal';
  if(['Qualified'].includes(status))return 'Qualified';
  if(['Contacted'].includes(status))return 'Contacted';
  if(['Sales Ready'].includes(status))return 'Sales Ready';
  if(c?.verificationStatus==='Sales Ready')return 'Sales Ready';
  if(c?.verificationStatus==='Verified')return 'Verified';
  if(status==='Lost')return 'Lost';
  return 'New Lead';
}
function pipelineStatusFor(stage){return ({'New Lead':'Lead','Verified':'Lead','Sales Ready':'Lead','Contacted':'Contacted','Qualified':'Qualified','Proposal':'Proposal','Won':'Customer','Fulfillment':'Customer','Customer':'Customer','Lost':'Lost'})[stage]||'Lead'}
function cleanLeadRecord(c){
  if(!c)return {changed:false};
  const before=JSON.stringify([c.businessName,c.contactName,c.phone,c.email,c.website,c.industry,c.city,c.zip,c.websiteStatus]);
  const clean=(v)=>String(v??'').trim();
  c.businessName=clean(c.businessName);
  c.contactName=clean(c.contactName);
  const rawPhone=clean(c.phone),digits=rawPhone.replace(/\D/g,'');
  if(digits.length===10)c.phone=`(${digits.slice(0,3)}) ${digits.slice(3,6)}-${digits.slice(6)}`;
  else if(digits.length===11&&digits.startsWith('1'))c.phone=`+1 ${digits.slice(1,4)}-${digits.slice(4,7)}-${digits.slice(7)}`;
  c.email=clean(c.email).toLowerCase();
  c.website=clean(c.website);
  if(c.website&&!/^https?:\/\//i.test(c.website))c.website='https://'+c.website;
  c.industry=clean(c.industry); c.city=clean(c.city); c.zip=clean(c.zip);
  if(!c.websiteStatus)c.websiteStatus=c.website?'Website Present':'No Website';
  normalizeLeadQuality(c);
  c.pipelineStage=pipelineStage(c);
  const after=JSON.stringify([c.businessName,c.contactName,c.phone,c.email,c.website,c.industry,c.city,c.zip,c.websiteStatus]);
  if(before!==after){c.updatedAt=now();return {changed:true}}return {changed:false};
}
function opsVisibleCustomers(req){
  const role=req.user?.role;
  if(role==='owner'||role==='manager')return db.customers||[];
  if(role==='lead_researcher'||role==='caller')return (db.customers||[]).filter(c=>!c.assignedTo||c.assignedTo===req.user.id);
  if(role==='fulfillment')return (db.customers||[]).filter(c=>c.status==='Customer'||c.assignedTo===req.user.id);
  return [];
}
function opsPerformance(req){
  const users=(db.users||[]).filter(u=>u.active!==false&&u.role!=='owner');
  const nowMs=Date.now(),from7=nowMs-7*86400000,from30=nowMs-30*86400000;
  const ts=x=>{const t=Date.parse(x||'');return Number.isFinite(t)?t:0};
  const minutesFor=e=>{if(!e?.clockIn)return 0;let end=e.clockOut?ts(e.clockOut):nowMs,start=ts(e.clockIn);if(!start)return 0;let m=Math.max(0,Math.round((end-start)/60000));for(const b of (e.breaks||[])){if(b.start&&b.end)m-=Math.max(0,Math.round((ts(b.end)-ts(b.start))/60000));}if(e.activeBreak?.start)m-=Math.max(0,Math.round((nowMs-ts(e.activeBreak.start))/60000));return Math.max(0,m)};
  const calc=(u,from)=>{
    const hours=(v9data().timeEntries||[]).filter(e=>e.userId===u.id&&ts(e.clockIn)>=from).reduce((a,e)=>a+minutesFor(e),0)/60;
    const leads=(db.customers||[]).filter(c=>(c.researcherId===u.id||c.createdBy===u.id)&&ts(c.createdAt)>=from);
    const calls=(db.callReports||[]).filter(r=>r.callerId===u.id&&ts(r.createdAt)>=from);
    const approved=calls.filter(r=>r.status==='Approved'||r.autoApproved);
    const sales=approved.filter(r=>['Closed Sale','Sale','Won'].includes(String(r.outcome||''))).length;
    const appointments=approved.filter(r=>r.appointmentRequested||r.outcome==='Appointment Requested').length;
    const wonOrders=(db.orders||[]).filter(o=>(o.salesRepId===u.id||o.assignedTo===u.id)&&['Paid','In Progress','Ready','Delivered','Completed'].includes(String(o.status||''))&&ts(o.createdAt)>=from).length;
    const quality=leads.filter(c=>c.leadTemperature==='Hot'||c.verificationStatus==='Sales Ready').length;
    return {hours:Number(hours.toFixed(2)),leads:leads.length,qualityReady:quality,calls:approved.length,appointments,sales,wonOrders,openTasks:(db.tasks||[]).filter(t=>t.assignedTo===u.id&&t.status!=='Completed').length};
  };
  const fromToday=new Date(); fromToday.setHours(0,0,0,0); const todayMs=fromToday.getTime(); return users.map(u=>({id:u.id,name:u.name,role:u.role,today:calc(u,todayMs),week:calc(u,from7),month:calc(u,from30)}));
}

function isoDay(tsValue){
  const d=new Date(tsValue||Date.now());
  if(Number.isNaN(d.getTime())) return '';
  return d.toISOString().slice(0,10);
}
function opsDailyMetrics(req, day=isoDay(Date.now())){
  const users=(db.users||[]).filter(u=>u.active!==false&&u.role!=='owner');
  const inDay=x=>isoDay(x)===day;
  const timeEntries=v9data().timeEntries||[];
  const metricsFor=u=>{
    const leads=(db.customers||[]).filter(c=>(c.researcherId===u.id||c.createdBy===u.id||c.assignedTo===u.id)&&inDay(c.createdAt));
    const verified=leads.filter(c=>c.verificationStatus==='Verified'||c.verificationStatus==='Sales Ready'||c.leadTemperature==='Hot').length;
    const calls=(db.callReports||[]).filter(r=>r.callerId===u.id&&inDay(r.createdAt));
    const approved=calls.filter(r=>r.status==='Approved'||r.autoApproved);
    const sales=approved.filter(r=>['Closed Sale','Sale','Won'].includes(String(r.outcome||''))).length;
    const orders=(db.orders||[]).filter(o=>(o.salesRepId===u.id||o.assignedTo===u.id)&&inDay(o.createdAt));
    const revenue=orders.filter(o=>['Paid','In Progress','Ready','Delivered','Completed'].includes(String(o.status||''))).reduce((a,o)=>a+Number(o.price||0),0);
    const completedTasks=(db.tasks||[]).filter(t=>t.assignedTo===u.id&&t.status==='Completed'&&inDay(t.updatedAt||t.completedAt||t.createdAt)).length;
    const messages=(db.customerMessages||[]).filter(m=>(m.senderId===u.id||m.createdBy===u.id)&&inDay(m.createdAt)).length;
    const minutes=timeEntries.filter(e=>e.userId===u.id&&inDay(e.clockIn)).reduce((a,e)=>a+minutesFor(e),0);
    return {id:u.id,name:u.name,role:u.role,leadsCreated:leads.length,leadsVerified:verified,calls:approved.length,sales,orders:orders.length,revenue:Number(revenue.toFixed(2)),tasksCompleted:completedTasks,messages,hours:Number((minutes/60).toFixed(2))};
  };
  return {date:day,generatedAt:now(),scope:req.user?.role==='owner'?'all active non-owner staff':'authorized management view',team:users.map(metricsFor),totals:users.map(metricsFor).reduce((a,m)=>{for(const k of ['leadsCreated','leadsVerified','calls','sales','orders','revenue','tasksCompleted','messages','hours'])a[k]=(a[k]||0)+(m[k]||0);return a;},{}),source:'durable Command Center records (not PM2 log estimates)'};
}
function runProductionSafetyHarness(){
  const results=[];
  const pass=(name,detail)=>results.push({name,status:'PASS',detail});
  const fail=(name,detail)=>results.push({name,status:'FAIL',detail});
  try{
    const probe={businessName:'  Chaos  Test LLC  ',contactName:'Test Owner',phone:'305-555-0101',email:'TEST@EXAMPLE.COM',website:'example.com',industry:'Testing',city:'Miami'};
    const clone=JSON.parse(JSON.stringify(probe)); cleanLeadRecord(clone);
    if(clone.phone==='(305) 555-0101'&&clone.email==='test@example.com'&&clone.website==='https://example.com')pass('lead_input_normalization','Phone, email and website normalization behaved as expected.'); else fail('lead_input_normalization','Normalization output differed from the expected safe shape.');
  }catch(e){fail('lead_input_normalization',e.message)}
  try{
    const dup=leadDuplicateMatches({businessName:'',phone:'3055550101',email:''});
    if(Array.isArray(dup))pass('duplicate_detection','Duplicate matching completed without mutating the lead pool.'); else fail('duplicate_detection','Duplicate matcher did not return an array.');
  }catch(e){fail('duplicate_detection',e.message)}
  try{
    const token=makePortalToken({id:'chaos-account',customerId:'chaos-customer'});
    const tampered=token.slice(0,-1)+(token.endsWith('a')?'b':'a');
    if(!parsePortalTokenForHarness(tampered))pass('portal_token_tamper','Tampered customer portal token was rejected.'); else fail('portal_token_tamper','Tampered customer portal token was accepted.');
  }catch(e){fail('portal_token_tamper',e.message)}
  try{
    const token=makeCustomerIntakeToken('chaos-order');
    const tampered=token.slice(0,-1)+(token.endsWith('a')?'b':'a');
    if(!parseCustomerIntakeToken(tampered))pass('intake_token_tamper','Tampered customer-intake token was rejected.'); else fail('intake_token_tamper','Tampered customer-intake token was accepted.');
  }catch(e){fail('intake_token_tamper',e.message)}
  try{
    const lr=SBC_ROLE_PERMISSIONS.lead_researcher||[];
    const forbidden=['settings:manage','payments','team:manage','leads:delete'];
    if(forbidden.every(x=>!lr.includes(x))&&lr.includes('leads:verify')&&lr.includes('customers:read-assigned'))pass('lead_researcher_rbac','Lead Researcher permissions remain least-privilege: research/verification only, no settings, payments, team administration or deletion.'); else fail('lead_researcher_rbac','Lead Researcher permission matrix contains an unexpected privileged capability.');
  }catch(e){fail('lead_researcher_rbac',e.message)}
  try{
    const invalid=pipelineStage({pipelineStage:'NOT-A-REAL-STAGE',status:'Lead'});
    if(invalid==='New Lead')pass('pipeline_fallback','Invalid pipeline stages fall back safely to New Lead.'); else fail('pipeline_fallback','Invalid pipeline stage did not fall back safely.');
  }catch(e){fail('pipeline_fallback',e.message)}
  try{
    const matrix=SBC_ROLE_PERMISSIONS||{};
    if(matrix.owner?.includes('settings:manage')&&matrix.manager&&!matrix.manager.includes('settings:manage'))pass('owner_boundary','Owner-only settings administration remains separated from manager permissions.'); else fail('owner_boundary','Owner/manager boundary is not as expected.');
  }catch(e){fail('owner_boundary',e.message)}
  const failed=results.filter(x=>x.status==='FAIL');
  return {ok:failed.length===0,mode:'controlled_non_destructive_failure_injection',generatedAt:now(),mutations:0,results,summary:{passed:results.length-failed.length,failed:failed.length},note:'This harness exercises defensive paths against synthetic data only. It does not attack the live website, send traffic spikes, charge Square, alter credentials, delete records or modify production business data.'};
}
function parsePortalTokenForHarness(token){
  try{const [payload,sig]=String(token||'').split('.');if(!payload||!sig||portalSign(payload)!==sig)return null;const data=JSON.parse(fromB64u(payload));return data&&data.exp&&Date.now()<=Number(data.exp)?data:null}catch{return null}
}

function opsOverview(req){
  const visible=opsVisibleCustomers(req);visible.forEach(normalizeLeadQuality);
  const all=db.customers||[];
  const stageNames=['New Lead','Verified','Sales Ready','Contacted','Qualified','Proposal','Won','Fulfillment','Customer','Lost'];
  const stageCounts=Object.fromEntries(stageNames.map(s=>[s,0]));
  visible.forEach(c=>stageCounts[pipelineStage(c)]++);
  const dupMap=new Map();
  visible.forEach(c=>{const keys=[];const p=normPhoneKey(c.phone),e=normEmailKey(c.email),b=normBusinessKey(c.businessName),city=normBusinessKey(c.city);if(p)keys.push('p:'+p);if(e)keys.push('e:'+e);if(b)keys.push('b:'+b+'|'+city);keys.forEach(k=>{if(!dupMap.has(k))dupMap.set(k,[]);dupMap.get(k).push(c.id)})});
  const dupGroups=[...dupMap.entries()].filter(([,ids])=>new Set(ids).size>1).map(([key,ids])=>({key,ids:[...new Set(ids)]}));
  const quality=visible.reduce((a,c)=>{const q=leadQuality(c);a.total++;a.score+=q.score;if(q.temperature==='Hot')a.hot++;else if(q.temperature==='Warm')a.warm++;else a.cold++;if(c.missingContactFields)a.incomplete++;return a},{total:0,score:0,hot:0,warm:0,cold:0,incomplete:0});
  quality.averageScore=quality.total?Math.round(quality.score/quality.total):0;
  const permissions=SBC_ROLE_PERMISSIONS[req.user?.role]||[];
  const auditRows=(db.auditLog||[]).slice(0,25);
  return {generatedAt:now(),user:{id:req.user?.id,name:req.user?.name,role:req.user?.role},permissions,permissionMatrix:SBC_ROLE_PERMISSIONS,counts:{all:all.length,visible:visible.length,duplicates:dupGroups.length,duplicateRecords:dupGroups.reduce((n,g)=>n+g.ids.length,0),quality},pipeline:stageCounts,duplicateGroups:dupGroups.slice(0,100),performance:['owner','manager'].includes(req.user?.role)?opsPerformance(req):[],audit:auditRows,cleanse:{available:hasPermission(req,'leads:cleanse')||['owner','manager'].includes(req.user?.role),scope:req.user?.role==='owner'||req.user?.role==='manager'?'Full lead pool':'Assigned / visible leads'}};
}
