app.post('/api/ops/pipeline/:id',auth,async(req,res)=>{
  const c=(db.customers||[]).find(x=>String(x.id)===String(req.params.id));if(!c)return res.status(404).json({error:'Lead not found.'});
  const role=req.user.role;if(role==='caller'&&c.assignedTo&&c.assignedTo!==req.user.id)return res.status(403).json({error:'This lead is not assigned to you.'});
  if(role==='lead_researcher'&&c.assignedTo&&c.assignedTo!==req.user.id)return res.status(403).json({error:'This lead is not assigned to you.'});
  if(!['owner','manager','caller','lead_researcher'].includes(role))return res.status(403).json({error:'Pipeline access is not available for this role.'});
  const stage=String(req.body?.stage||'');const allowed=['New Lead','Verified','Sales Ready','Contacted','Qualified','Proposal','Won','Fulfillment','Customer','Lost'];if(!allowed.includes(stage))return res.status(400).json({error:'Invalid pipeline stage.'});
  if(role==='caller'&&!['Contacted','Qualified','Proposal','Won','Lost'].includes(stage))return res.status(403).json({error:'Sales callers can advance sales-stage outcomes on assigned leads only.'});
  if(role==='lead_researcher'&&!['New Lead','Verified','Sales Ready'].includes(stage))return res.status(403).json({error:'Lead researchers can manage research/verification stages only.'});
  const old=pipelineStage(c);c.pipelineStage=stage;c.status=pipelineStatusFor(stage);if(stage==='Verified')c.verificationStatus='Verified';if(stage==='Sales Ready'){c.verificationStatus='Sales Ready';}if(stage==='Lost')c.verificationStatus=c.verificationStatus||'Verified';c.updatedAt=now();audit(req.user,'pipeline_stage_changed',`Moved ${c.businessName||c.contactName||c.id} from ${old} to ${stage}`,{customerId:c.id,from:old,to:stage});addActivity('pipeline',`Pipeline: ${c.businessName||c.contactName||c.id} → ${stage}`,{customerId:c.id,stage,userId:req.user.id});await saveData();res.json(c);
});

