function sbcProductionSnapshot(req){
  const m=megaData(), customers=db.customers||[], tasks=db.tasks||[], quotes=db.quotes||[], orders=db.orders||[], renewals=db.renewals||[], users=db.users||[];
  const openOrders=orders.filter(o=>!['Delivered','Cancelled'].includes(String(o.status||'')));
  const activeProjects=(m.projects||[]).filter(x=>!['Completed','Cancelled'].includes(String(x.status||'')));
  const openTickets=(m.tickets||[]).filter(x=>x.status!=='Resolved');
  const pendingApprovals=(m.approvals||[]).filter(x=>x.status==='Pending Owner Approval');
  const overdueTasks=tasks.filter(t=>t.status!=='Completed'&&t.dueAt&&new Date(t.dueAt)<new Date()).length;
  const overdueActions=reconciledOverdueActions();
  const leadCount=customers.filter(c=>c.status==='Lead').length;
  const salesReady=customers.filter(c=>['Lead','Qualified','Sales Ready'].includes(c.status)).length;
  const quoted=quotes.filter(q=>['Draft','Sent'].includes(q.status)).length;
  const won=quotes.filter(q=>['Won','Paid'].includes(q.status)).length;
  const paid=quotes.filter(q=>q.status==='Paid').length;
  const revenue=quotes.filter(q=>['Won','Paid'].includes(q.status)).reduce((a,q)=>a+Number(q.total||0),0);
  const hardening=opsOverview(req);return {generatedAt:now(),version:BUILD_VERSION,user:{id:req.user?.id,name:req.user?.name,role:req.user?.role},workflow:{research:leadCount,salesReady,quoted,won,paid,fulfillment:openOrders.length,activeProjects:activeProjects.length,renewals30:renewals.filter(r=>r.status!=='Paid'&&r.dueDate>=today()&&r.dueDate<=new Date(Date.now()+30*864e5).toISOString().slice(0,10)).length},attention:{overdueTasks,overdueActions,openTickets,pendingApprovals,automationFailures:(m.automationFailures||[]).filter(x=>x.status!=='Resolved').length},team:{active:users.filter(u=>u.active!==false).length,certified:users.filter(u=>u.certified).length,onboardingPending:(db.onboarding||[]).filter(x=>x.status!=='Approved').length},money:{pipeline:quotes.filter(q=>!['Won','Paid','Lost'].includes(q.status)).reduce((a,q)=>a+Number(q.total||0),0),revenue},system:{automationEnabled:db.settings?.automationEnabled!==false,openProjects:activeProjects.length,openOrders:openOrders.length},hardening:{pipeline:hardening.pipeline,quality:hardening.counts.quality,duplicates:hardening.counts.duplicates,permissions:hardening.permissions}};
}
function sbcEmployeeScorecard(req,userId){
  const u=(db.users||[]).find(x=>x.id===String(userId)); if(!u)return null;
  const customers=db.customers||[], tasks=db.tasks||[], quotes=db.quotes||[], reports=db.callReports||[], orders=db.orders||[];
  const mine=c=>c.assignedTo===u.id, myLeads=customers.filter(mine), myTasks=tasks.filter(mine), myQuotes=quotes.filter(q=>q.assignedTo===u.id||q.ownerId===u.id), myReports=reports.filter(r=>r.callerId===u.id), myOrders=orders.filter(o=>o.assignedTo===u.id);
  const completedTasks=myTasks.filter(t=>t.status==='Completed').length, openTasks=myTasks.filter(t=>t.status!=='Completed').length;
  const won=myQuotes.filter(q=>['Won','Paid'].includes(q.status)), revenue=won.reduce((a,q)=>a+Number(q.total||0),0);
  return {user:{id:u.id,name:u.name,role:u.role,active:u.active!==false,certified:Boolean(u.certified)},work:{leads:myLeads.length,openTasks,completedTasks,openOrders:myOrders.filter(o=>!['Delivered','Cancelled'].includes(o.status)).length},sales:{quotes:myQuotes.length,won:won.length,revenue,callReports:myReports.length},quality:{overdueTasks:myTasks.filter(t=>t.status!=='Completed'&&t.dueAt&&new Date(t.dueAt)<new Date()).length,missingLeadData:myLeads.filter(c=>!c.businessName||!c.phone).length},coaching: u.aiProfile||{}};
}
