if(name==='send_customer_portal_message'){const c=(db.customers||[]).find(x=>x.id===String(args.customerId||''));if(!c)return {error:'Customer not found.'};const body=String(args.message||'').trim();if(!body)return {error:'Message is empty.'};const m={id:id('msg'),customerId:c.id,senderType:'staff',senderName:req.user.name||'Kim / SBC',body:body.slice(0,4000),createdAt:now(),readAt:''};db.customerMessages=db.customerMessages||[];db.customerMessages.push(m);db.customerMessages=db.customerMessages.slice(-5000);addActivity('portal_message',`Kim/SBC messaged ${c.businessName||c.contactName} through the customer portal`,{customerId:c.id,messageId:m.id,staffId:req.user.id,ai:true});await saveData();return {ok:true,message:portalMessageSafe(m)};}
if(name==='prepare_customer_portal_invite'){const c=(db.customers||[]).find(x=>x.id===String(args.customerId||''));if(!c)return {error:'Customer not found.'};if(!c.email)return {error:'Customer has no email address.'};let a=(db.customerAccounts||[]).find(x=>x.customerId===c.id);if(!a){a={id:id('acct'),customerId:c.id,email:String(c.email).trim().toLowerCase(),passwordHash:'',active:true,createdAt:now(),lastLoginAt:''};db.customerAccounts=db.customerAccounts||[];db.customerAccounts.push(a);await saveData();}return {ok:true,portalUrl:`https://sbcmia.com/?portal=login&email=${encodeURIComponent(a.email)}`,email:a.email,accountExists:Boolean(a.passwordHash)};}
