  if(req.user.role!=='owner' && (!roleScopedKim || !teamSafeKim.has(String(name||''))))throw new Error('This Kim operation is outside your role. Kim can still coach, explain training, and provide role-scoped operational assistance.');
  if(name==='kim_live_runtime_check')return await kimLiveRuntimeCheck(req);
