app.post('/api/voice/log',auth,async(req,res)=>{const prior=sbcVoiceLogCommitTailV6615;let release;sbcVoiceLogCommitTailV6615=new Promise(resolve=>{release=resolve});await prior;/* SBC_V6615_CALL_LOG_MYSQL_DURABILITY: serialized writes with best-effort in-memory rollback */const previousLogs=(db.callLogs||[]).map(row=>({...row}));const previousActivity=(db.activities||[]).map(row=>({...row}));const previousAudit=(db.auditLog||[]).map(row=>({...row}));try{const b=req.body||{};const tenantId=requireRequestTenant(req);const customerId=String(b.customerId||'').trim().slice(0,120);if(!customerId)return res.status(400).json({ok:false,error:'customerId is required to log an SBC call.'});const customer=(db.customers||[]).find(c=>String(c.id)===customerId&&Number(c.tenantId??c.tenant_id)===Number(tenantId));if(!customer)return res.status(404).json({ok:false,error:'Customer not found in this workspace.'});const sessionId=String(b.sessionId||'').trim().slice(0,100);let log=sessionId?(db.callLogs||[]).find(x=>String(x.sessionId||'')===sessionId&&String(x.userId)===String(req.user.id)&&Number(x.tenantId||tenantId)===Number(tenantId)&&String(x.customerId)===customerId):null;const isNew=!log;const priorStatus=String(log?.status||'');const allowedStatus=new Set(['connecting','in-progress','completed','ended','failed','busy','no-answer','canceled','unknown']);const wantedStatus=String(b.status||'completed').toLowerCase().slice(0,32);const status=allowedStatus.has(wantedStatus)?wantedStatus:'completed';const allowedOutcome=new Set(['Pending','Interested','Follow-up requested','Appointment booked','No answer','Left voicemail','Not interested','Do Not Call','Order ready','Bad number']);const outcome=allowedOutcome.has(String(b.outcome||''))?String(b.outcome):String(log?.outcome||'Pending');const stamp=now();const terminal=new Set(['completed','ended','failed','busy','no-answer','canceled']);const notes=Object.prototype.hasOwnProperty.call(b,'notes')?String(b.notes||'').slice(0,12000):String(log?.notes||'');const nextAction=Object.prototype.hasOwnProperty.call(b,'nextAction')?String(b.nextAction||'').slice(0,1000):String(log?.nextAction||'');const followUpAt=Object.prototype.hasOwnProperty.call(b,'followUpAt')?String(b.followUpAt||'').slice(0,40):String(log?.followUpAt||'');const durationSec=Math.max(0,Math.min(86400,Number.isFinite(Number(b.durationSec))?Math.round(Number(b.durationSec)):Number(log?.durationSec||0)));if(isNew){log={id:id('calllog'),sessionId:sessionId,tenantId:Number(tenantId),userId:req.user.id,userName:req.user.name||req.user.username||'SBC Team',customerId,to:normalizeDialNumber(b.to),direction:'outbound',callSid:String(b.callSid||'').slice(0,120),status,durationSec,startedAt:String(b.startedAt||now()).slice(0,40),endedAt:terminal.has(status)?String(b.endedAt||stamp).slice(0,40):'',createdAt:stamp,updatedAt:stamp,notes,outcome,nextAction,followUpAt};db.callLogs=db.callLogs||[];db.callLogs.unshift(log);db.callLogs=db.callLogs.slice(0,1000)}else{log.tenantId=Number(tenantId);log.status=status;log.durationSec=durationSec;log.notes=notes;log.outcome=outcome;log.nextAction=nextAction;log.followUpAt=followUpAt;log.updatedAt=stamp;if(b.to)log.to=normalizeDialNumber(b.to);if(b.callSid)log.callSid=String(b.callSid).slice(0,120);if(b.startedAt&&!log.startedAt)log.startedAt=String(b.startedAt).slice(0,40);if(terminal.has(status))log.endedAt=String(b.endedAt||stamp).slice(0,40)}const finalChanged=terminal.has(status)&&priorStatus!==status;if(finalChanged){audit(req.user,'voice_call','Outbound SBC business call '+status,{callLogId:log.id,customerId,callSid:log.callSid,to:log.to,durationSec:log.durationSec,outcome:log.outcome,notesLength:log.notes.length});addActivity('call',String(req.user.name||req.user.username||'SBC Team')+' logged an SBC business call',{customerId,callLogId:log.id,callSid:log.callSid,status,durationSec:log.durationSec,outcome:log.outcome,nextAction:log.nextAction,followUpAt:log.followUpAt})}await saveData();if(!mysqlPool)throw Object.assign(new Error('VOICE_LOG_MYSQL_NOT_AVAILABLE'),{code:'VOICE_LOG_NOT_DURABLE'});const [durabilityRows]=await mysqlPool.query("SELECT JSON_CONTAINS(payload,JSON_OBJECT('id',?,'tenantId',?,'status',?,'notes',?,'outcome',?),'$.callLogs') AS confirmed FROM sbc_workspace WHERE id=1",[log.id,Number(tenantId),log.status,log.notes,log.outcome]);if(Number(durabilityRows?.[0]?.confirmed)!==1)throw Object.assign(new Error('VOICE_LOG_MYSQL_NOT_DURABLE'),{code:'VOICE_LOG_NOT_DURABLE'});res.status(isNew?201:200).json({ok:true,durable:true,id:log.id,sessionId:log.sessionId,status:log.status,updatedAt:log.updatedAt})}catch(e){db.callLogs=previousLogs;db.activities=previousActivity;db.auditLog=previousAudit;const code=e?.statusCode===423?423:503;res.status(code).json({ok:false,durable:false,error:e.code==='VOICE_LOG_NOT_DURABLE'?'VOICE_LOG_NOT_DURABLE':(e.message||'Unable to save the SBC call log.')})}finally{release()}});

