    const detailRequested=/\b(details?|detailed|diagnos(?:e|is|tic)|investigat(?:e|ion)|report|evidence|verify|verification|why|what happened|root cause|explain)\b/i.test(message);
    const aiMaxOutputTokens=detailRequested?1400:900;
    const aiStartedAt=Date.now();
    const isLiveRuntimeCheck=/live read-only check.*current production runtime|current production runtime only|do not run a full health audit/i.test(message);
