function safeTimingEqualHex(a,b){try{const aa=Buffer.from(String(a||'').replace(/^sha256=/i,''),'hex'),bb=Buffer.from(String(b||'').replace(/^sha256=/i,''),'hex');return aa.length===bb.length&&aa.length>0&&crypto.timingSafeEqual(aa,bb)}catch{return false}}
function vendorWebhookValid(provider,raw,signature){const envKey=provider==='4over4'?'FOUROVER4_WEBHOOK_SECRET':'VISTAPRINT_WEBHOOK_SECRET';const secret=process.env[envKey]||'';if(!secret)return false;const expected=crypto.createHmac('sha256',secret).update(raw).digest('hex');return safeTimingEqualHex(signature,expected)}


