app.post('/api/print/preflight',auth,async(req,res)=>{
  const b=req.body||{};const dpi=Number(b.dpi||b.resolutionDpi||0);const color=String(b.colorSpace||b.profile||'').trim().toUpperCase();const bleed=Number(b.bleedInches||b.bleed||0);const width=Number(b.widthInches||b.width||0);const height=Number(b.heightInches||b.height||0);const format=String(b.format||b.fileType||'').toLowerCase();const warnings=[];
  if(dpi&&dpi<300)warnings.push('Resolution is below the recommended 300 DPI.');
  if(color&&color!=='CMYK')warnings.push('Asset metadata is not marked CMYK; verify print color conversion before production.');
  if(bleed<0.125)warnings.push('Bleed is below 0.125 in. Confirm vendor requirements.');
  if(!width||!height)warnings.push('Physical dimensions were not supplied; size could not be fully validated.');
  if(format&&['jpg','jpeg','png','pdf','svg','tif','tiff'].indexOf(format.replace('.',''))<0)warnings.push('File format is outside the standard SBC preflight list.');
  res.json({ok:warnings.length===0,preflight:{dpi,colorSpace:color||'unknown',bleedInches:bleed,widthInches:width,heightInches:height,format:format||'unknown',warnings,checkedAt:now()}});
});
app.post('/api/print/svg-analyze',auth,(req,res)=>{const svg=String(req.body?.svg||'');if(svg.length>2000000)return res.status(413).json({error:'SVG payload too large.'});if(!svg.trim().startsWith('<'))return res.status(400).json({error:'SVG markup required.'});const tags=(svg.match(/<\/?(?:path|rect|circle|ellipse|line|polyline|polygon|g|text|image)\b/gi)||[]).length;const paths=(svg.match(/<path\b/gi)||[]).length;res.json({ok:true,nodes:tags,pathNodes:paths,complexity:tags>5000?'high':tags>1000?'medium':'low'});});
