// Public Square webhook endpoint. It does not use SBC session auth; authenticity is enforced with Square HMAC.
async function processPendingSquareWebhooks(){
  const events=squareWebhookRecords();
  const pending=events.filter(x=>(x.status==='RECEIVED'||x.status==='RETRY')&&!x.processedAt&&Number(x.attempts||0)<10).slice(0,25);
  for(const rec of pending){
    try{
      const event=rec.payload&&typeof rec.payload==='object'?rec.payload:null;
      if(!event)throw new Error('Stored Square webhook payload is unavailable.');
      const result=event.type==='payment.updated'||event.type==='payment.created'
        ?await handleSquarePaymentEvent(event,process.env.SBC_PUBLIC_URL||'')
        :{ignored:true,type:event.type};
      rec.status='PROCESSED';rec.processedAt=now();rec.result=result;rec.lastError='';
      await saveData();
    }catch(e){
      rec.status='RETRY';rec.lastError=String(e.message||'Processing error').slice(0,1000);rec.attempts=Number(rec.attempts||0)+1;rec.lastAttemptAt=now();
      try{await saveData()}catch(saveErr){console.error('[SBC] Could not persist Square retry state:',saveErr.message)}
    }
  }
}

MONETIZATION_QUEUE.configure(async job=>{
  if(job.eventType==='square.webhook'){
    const event=job.payload?.event;
    if(!event)throw new Error('Square webhook event missing from monetization queue.');
    const result=event.type==='payment.updated'||event.type==='payment.created'?await handleSquarePaymentEvent(event,process.env.SBC_PUBLIC_URL||''):{ignored:true,type:event.type};
    const rec=squareWebhookRecords().find(x=>x.eventId===String(event.event_id||''));
    if(rec){rec.status='PROCESSED';rec.processedAt=now();rec.result=result;rec.lastError='';await saveData();}
    return result;
  }
  throw new Error(`Unsupported monetization queue event: ${job.eventType}`);
});

// V55.2 — Inbound Revenue Gasket. External providers must present the shared inbound webhook secret.
function inboundWebhookAuthorized(req){
  const supplied=String(req.get('x-sbc-inbound-secret')||req.get('x-sbc-webhook-secret')||'');
  return verifySecret(supplied,process.env.SBC_INBOUND_WEBHOOK_SECRET||'');
}
