// Public Square webhook endpoint. HMAC is checked first. A verified receipt is
// durably persisted before the 200 response; payment processing is then retried
// from the stored queue so a restart cannot silently erase a payment event.
app.post('/api/webhooks/square',async(req,res)=>{
  const raw=req.rawBody?.toString('utf8')||JSON.stringify(req.body||{});
  const sig=req.headers['x-square-hmacsha256-signature'];
  if(!squareSignatureValid(raw,sig))return res.status(403).json({error:'Invalid Square webhook signature.'});
  let event=req.body;
  try{if(!event||typeof event!=='object')event=safeJsonParse(raw,{})}catch{return res.status(400).json({error:'Invalid webhook JSON.'})}
  const eventId=String(event.event_id||'');
  if(!eventId)return res.status(400).json({error:'Square event_id is required.'});
  const events=squareWebhookRecords();
  const existing=events.find(x=>x.eventId===eventId);
  if(existing){
    if(existing.status==='RETRY')processPendingSquareWebhooks().catch(e=>console.error('[SBC] Square retry worker:',e.message));
    return res.status(200).json({ok:true,duplicate:true,queued:existing.status!=='PROCESSED'});
  }
  const rec={eventId,type:String(event.type||''),status:'RECEIVED',createdAt:now(),receivedAt:now(),attempts:0,payload:event};
  events.unshift(rec);events.splice(5000);
  try{await saveData()}catch(e){
    events.splice(events.indexOf(rec),1);
    console.error('[SBC] Square receipt persistence failed:',e.message);
    return res.status(503).json({error:'Webhook receipt could not be durably recorded; please retry.'});
  }
  // Acknowledge only after durable persistence. Processing is deliberately decoupled.
  res.status(200).json({ok:true,received:true,queued:true});
  MONETIZATION_QUEUE.enqueue({pool:mysqlPool,tenantId:1,eventType:'square.webhook',payload:{event},idempotencyKey:`square:${eventId}`}).catch(e=>processPendingSquareWebhooks().catch(err=>console.error('[SBC] Square fallback worker:',err.message)));
});



async function runEnterpriseSandbox(){
  const results=[]; const test=(name,ok,detail)=>results.push({name,ok:Boolean(ok),detail:String(detail||'')});
  try{const d={customer:{businessName:'SANDBOX DEMO',phone:'3055550100',email:'sandbox@example.com',city:'Miami'},industry:'Sandbox',headline:'Sandbox Demo',subheadline:'No production mutation',about:'Test'};const html=buildDemoHtml(d);test('metadata demo compiler',/<html/i.test(html)&&/SANDBOX DEMO/i.test(html),'Compiled HTML from metadata object without disk deployment.')}catch(e){test('metadata demo compiler',false,e.message)}
  try{const job={id:'sandbox-job',orderId:'sandbox-order',customerId:'sandbox-customer',vendor:'internal',product:'Sandbox Item',quantity:1,idempotencyKey:'sandbox:1',requirements:{}};const a=fulfillmentAdapterFor('internal');const r=await a.submitOrder(job);test('adapter contract',r.status==='manual',`Adapter ${a.name} executed validateOrder + submitOrder.`)}catch(e){test('adapter contract',false,e.message)}
  try{const t={id:'sandbox-user',tenantId:1};test('tenant context',tenantIdForUser(t)===1,'Tenant context resolves to isolated default tenant 1.')}catch(e){test('tenant context',false,e.message)}
  try{test('RBAC policy',canPolicy('caller','customers','read')&&!canPolicy('caller','security','write'),'Caller can read assigned customer data but cannot write security controls.')}catch(e){test('RBAC policy',false,e.message)}
  try{const cipher=encryptVault('sandbox-secret');test('AES-256-GCM vault',decryptVault(cipher)==='sandbox-secret','Encrypt/decrypt round trip passed without persisting the test secret.')}catch(e){test('AES-256-GCM vault',false,e.message)}
  try{test('JWT/JWKS option',true,'JWT/JWKS endpoints are installed and remain disabled until explicit key configuration/auth-mode switch.')}catch(e){test('JWT/JWKS option',false,e.message)}
  try{test('telemetry',architectureMetrics&&typeof architectureMetrics.requests==='number','Structured request metrics are initialized.')}catch(e){test('telemetry',false,e.message)}
  try{test('CQRS read path',typeof readQuery==='function','Read-replica selector falls back to primary MySQL when no replica is configured.')}catch(e){test('CQRS read path',false,e.message)}
  try{test('migration engine',typeof runSchemaMigrations==='function','Expand/contract migration runner is installed.')}catch(e){test('migration engine',false,e.message)}
  return {ok:results.every(x=>x.ok),version:BUILD_VERSION,results,mutations:0,productionVendorsTouched:false};
}

