function verifyPrintWebhook(req,vendor){const name=vendor==='4over4'?'FOUROVER4_WEBHOOK_SECRET':'VISTAPRINT_WEBHOOK_SECRET';const secret=secretValue(name,name);if(!secret)return {ok:false,reason:'webhook secret not configured'};const supplied=String(req.headers['x-sbc-signature']||req.headers['x-signature']||'').replace(/^sha256=/,'');const raw=req.rawBody||Buffer.from(JSON.stringify(req.body||{}));const expected=crypto.createHmac('sha256',secret).update(raw).digest('hex');if(!supplied||supplied.length!==expected.length)return {ok:false,reason:'invalid signature'};return {ok:crypto.timingSafeEqual(Buffer.from(supplied),Buffer.from(expected)),reason:'invalid signature'}}
