const v440Presence = new Map();
const v440SeenNonces = new Map();
const v440Canary = V440.memoryCanary();
function v440RecordSecurity(req,event,meta={}){ try{ audit(req?.user||null,'v440_security',event,{ip:String(req?.ip||'').slice(0,64),...meta}); }catch{} }
function v440RequireChallenge(req,res,next){
  const token=String(req.headers['x-sbc-command-challenge']||req.body?.commandChallenge||'');
  if(!V440.verifyChallenge(token))return res.status(401).json({ok:false,error:'Ephemeral command challenge required.'});
  next();
}
function v440ReplayGuard(req,res,next){
  const n=String(req.headers['x-sbc-request-nonce']||'');
  if(!n)return res.status(400).json({ok:false,error:'One-time request nonce required.'});
  const now=Date.now();
  for(const [k,t] of v440SeenNonces){if(now-t>120000)v440SeenNonces.delete(k);}
  if(v440SeenNonces.has(n))return res.status(409).json({ok:false,error:'Replay rejected.'});
  v440SeenNonces.set(n,now); next();
}
