// ===== V26.2.0 STARTER LEAD PACK =====
function parseStarterCsv(text){
  const rows=[]; let row=[], field='', quoted=false;
  for(let i=0;i<text.length;i++){
    const ch=text[i], nx=text[i+1];
    if(quoted){ if(ch==='"'&&nx==='"'){field+='"';i++;} else if(ch==='"'){quoted=false;} else field+=ch; }
    else if(ch==='"') quoted=true;
    else if(ch===','){row.push(field);field='';}
    else if(ch==='\n'){row.push(field);rows.push(row);row=[];field='';}
    else if(ch!=='\r') field+=ch;
  }
  if(field.length||row.length){row.push(field);rows.push(row);}
  return rows;
}

function normalizeLeadKey(v){return String(v||'').trim().toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();}
function leadQuality(c){
  let score=0;
  if(c.businessName)score+=20;
  if(c.phone)score+=20;
  if(c.contactName)score+=15;
  if(c.email)score+=15;
  if(c.website)score+=10;
  if(c.industry)score+=5;
  if(c.source)score+=5;
  if(c.sbcOpportunity || String(c.notes||'').toLowerCase().includes('sbc opportunity:'))score+=5;
  if(c.city || String(c.notes||'').toLowerCase().includes('city:'))score+=3;
  if(c.zip || String(c.notes||'').toLowerCase().includes('zip:'))score+=2;
  let temperature=score>=75?'Hot':score>=50?'Warm':'Cold';
  return {score,temperature};
}
function isActiveSalesLead(c){const excluded=new Set(['Customer','Lost','Do Not Call','Closed','Duplicate','Not Qualified']);if(!c||isSbcSyntheticTestRecord(c)||excluded.has(String(c?.status||'Lead')))return false;const q=leadQuality(c);return q.temperature==='Hot'||q.temperature==='Warm';}
function auditLeadPool({dedupe=true,rate=true}={}){
  db.customers=Array.isArray(db.customers)?db.customers:[];
  let removedDuplicates=0;
  const seen=new Map(), kept=[];
  const rank=c=>Object.values(c||{}).filter(v=>String(v||'').trim()).length + (c.phone?5:0)+(c.email?5:0)+(c.contactName?4:0)+(c.website?3:0);
  for(const c of db.customers){
    const source=String(c.source||'').toLowerCase();
    const city=normalizeLeadKey(c.city||((String(c.notes||'').match(/City:\s*([^\n]+)/i)||[])[1]||''));
    const key=`${normalizeLeadKey(c.businessName)}|${city}`;
    const isStarter=source.includes('starter lead pack');
    const dedupeKey=isStarter?key:'';
    if(dedupe && isStarter && seen.has(dedupeKey)){
      const prior=seen.get(dedupeKey);
      const better=rank(c)>rank(prior)?c:prior;
      const weaker=better===c?prior:c;
      for(const k of ['contactName','phone','email','website','industry','address','city','zip','sbcOpportunity','verificationStatus']){
        if(!better[k]&&weaker[k])better[k]=weaker[k];
      }
      if(better===c){const idx=kept.indexOf(prior);if(idx>=0)kept[idx]=c;seen.set(dedupeKey,c);}
      removedDuplicates++;continue;
    }
    if(dedupe && isStarter)seen.set(dedupeKey,c);
    kept.push(c);
  }
  db.customers=kept;
  let hot=0,warm=0,cold=0,activeSalesLeads=0;
  for(const c of db.customers){
    if(!rate)continue;
    const q=leadQuality(c);c.leadScore=q.score;c.leadTemperature=q.temperature;
    c.missingContactFields=['contactName','phone','email','website','industry','city','zip'].filter(k=>!c[k]).join(',');
    if(isActiveSalesLead(c)){
      activeSalesLeads++;
      if(q.temperature==='Hot')hot++;else if(q.temperature==='Warm')warm++;else cold++;
    }
  }
  return {total:db.customers.length,activeSalesLeads,removedDuplicates,hot,warm,cold};
}
function seedStarterLeadPack(){
  const files=[
    {path:path.join(__dirname,'starter-leads','SBC-250-Verified-Lead-Prospects.csv'),sourceDefault:'SBC Starter Lead Pack',kind:'starter'},
    {path:path.join(__dirname,'starter-leads','SBC-Lorna-Lead-Backup-2026-10-06.csv'),sourceDefault:'Lorna Lead Backup 2026-10-06',kind:'lorna'},
    {path:path.join(__dirname,'starter-leads','SBC-Lorna-Barbershop-Batch-2026-10-09.csv'),sourceDefault:'Lorna Lead Backup 2026-10-09',kind:'lorna-cold-pending-verification'},
    {path:path.join(__dirname,'starter-leads','SBC-Jonathan-Barbershop-Backup-2026-10-09.csv'),sourceDefault:'Jonathan Lead Backup Worksheet 2026-10-09',kind:'owner-backup-cold-pending-verification'}
  ];
  let added=0,skipped=0,total=0,missing=0;
  db.customers=Array.isArray(db.customers)?db.customers:[];
  for(const spec of files){
    if(!fs.existsSync(spec.path)){missing++;continue;}
    try{
      const rows=parseStarterCsv(fs.readFileSync(spec.path,'utf8').replace(/^\uFEFF/,''));
      if(rows.length<2)continue;
      const headers=rows[0].map(x=>String(x||'').trim());
      const idx=Object.fromEntries(headers.map((h,i)=>[h,i]));
      for(const r of rows.slice(1)){
        total++;
        const get=(...names)=>{for(const n of names){if(Object.prototype.hasOwnProperty.call(idx,n))return String(r[idx[n]]||'').trim();}return '';};
        const business=get('Business Name','businessName','Business');
        if(!business){skipped++;continue;}
        const city=get('City','city'), zip=get('ZIP','Zip','zip');
        const industry=get('Industry','Type / Industry','Type');
        const opportunity=get('SBC Opportunity');
        const verification=get('Verification','For Jonathan’s Verification','For Jonathan\'s Verification');
        const source=get('Source')||spec.sourceDefault;
        const contactName=get('Contact Name','contactName','Contact','Owner');
        const phone=get('Phone','Phone Number','phone');
        const email=get('Email','email');
        const website=get('Website','website');
        const websiteStatus=get('Website Status','websiteStatus')|| (website?'Has website':'No website');
        const research=get('Research Notes','Research Note','Notes','researchNotes');
        const sourceUrl=get('Source URL','Source URL / Evidence','Evidence URL');
        const normalizedBusiness=business.toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
        const normalizedPhone=phone.replace(/\D/g,'');
        const normalizedEmail=email.toLowerCase().trim();
        const normalizedWebsite=website.toLowerCase().replace(/\/$/,'').trim();
        const exists=(db.customers||[]).some(c=>{
          const cb=String(c.businessName||'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
          if(cb!==normalizedBusiness)return false;
          // For the new Lorna barbershop batch, a normalized business-name match alone
          // is sufficient to prevent importing the same prospect twice.
          if(spec.kind==='lorna-cold-pending-verification')return true;
          if(spec.kind==='owner-backup-cold-pending-verification')return true;
          const cp=String(c.phone||'').replace(/\D/g,'');
          const ce=String(c.email||'').toLowerCase().trim();
          const cw=String(c.website||'').toLowerCase().replace(/\/$/,'').trim();
          return (normalizedPhone&&cp===normalizedPhone)||(normalizedEmail&&ce===normalizedEmail)||(normalizedWebsite&&cw===normalizedWebsite)||(city&&String(c.city||'').trim().toLowerCase()===city.toLowerCase());
        });
        if(exists){skipped++;continue;}
        const noteParts=[
          city&&`City: ${city}`,
          zip&&`ZIP: ${zip}`,
          opportunity&&`SBC Opportunity: ${opportunity}`,
          verification&&`Verification: ${verification}`,
          source&&`Source: ${source}`,
          sourceUrl&&`Source URL: ${sourceUrl}`,
          research&&`Research Notes: ${research}`
        ].filter(Boolean);
        db.customers.push({
          id:id('cust'),tenantId:TENANT_DEFAULT_ID,businessName:business,contactName,phone,email,status:'Lead',source:source||spec.sourceDefault,followUp:'',
          notes:noteParts.join('\n'),createdAt:now(),updatedAt:now(),website,websiteStatus,industry,assignedTo:'',salesQueueState:'research',city,zip,
          sbcOpportunity:opportunity,verificationStatus:verification||'PENDING_OWNER_VERIFICATION',leadTemperature:'Cold',leadScore:0
        });
        added++;
      }
    }catch(e){console.warn(`Starter lead pack seed failed for ${spec.path}:`,e.message);}
  }
  return {added,skipped,total,missing};
}

