// V37.0.0 — Kim Automation Fabric. Guarded autonomous operations with durable mission persistence.
function kim370Gate(req,cap='kim370.read'){ return requireCapability(cap)(req, {status:()=>({json:()=>{}})}, ()=>true); }
async function kim370PersistMission(m){
  if(!mysqlPool)return;
  await mysqlPool.query(`INSERT INTO sbc_kim_automation_missions (id,tenant_id,mission_type,priority,title,detail,status,meta_json,created_at,updated_at,completed_at) VALUES (?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),meta_json=VALUES(meta_json),updated_at=VALUES(updated_at),completed_at=VALUES(completed_at)`,[m.id,1,m.type,m.priority,m.title,m.detail,m.status,JSON.stringify(m.meta||{}),sqlDateTime(m.createdAt),sqlDateTime(m.updatedAt),m.completedAt?sqlDateTime(m.completedAt):null]);
}
async function kim370LoadMissions(){
  if(!mysqlPool)return;
  const [rows]=await mysqlPool.query(`SELECT id,mission_type AS type,priority,title,detail,status,meta_json,created_at AS createdAt,updated_at AS updatedAt,completed_at AS completedAt FROM sbc_kim_automation_missions ORDER BY created_at DESC LIMIT 500`);
  for(const r of rows){try{r.meta=safeJsonParse(r.meta_json, {})}catch{r.meta={}}delete r.meta_json;const i=V370.state.missions.findIndex(x=>x.id===r.id);if(i<0)V370.state.missions.push(r);else V370.state.missions[i]=r;}
  V370.state.missions.sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)));
}
function kim370Context(){
  const orders=db.orders||[], customers=db.customers||[], quotes=db.quotes||[];
  const overdue=orders.filter(o=>{const t=new Date(o.createdAt||o.created_at||0).getTime();return t&&Date.now()-t>4*60*60*1000&&!['Fulfilled','Cancelled','Dispatched'].includes(String(o.status||''));}).length;
  const unpaid=orders.filter(o=>!['Paid','Fulfilled','Cancelled','Refunded'].includes(String(o.paymentStatus||o.status||'')) && Number(o.price||o.total||0)>0).length;
  const failed=orders.filter(o=>['failed','declined','payment_failed'].includes(String(o.paymentStatus||'').toLowerCase())).length;
  const leads=customers.filter(c=>String(c.status||'').toLowerCase()==='lead');
  const backupReady=Boolean((DATA_FILE&&fs.existsSync(DATA_FILE))||mysqlPool);
  return {mysqlPool,redisReady,eventBusReady:Boolean(amqpChannel||mysqlPool),openaiConfigured:Boolean(process.env.OPENAI_API_KEY),providerReady:[gatewayStatus(GATEWAY_DEFINITIONS.find(g=>g.id==='four_over_four')),gatewayStatus(GATEWAY_DEFINITIONS.find(g=>g.id==='vistaprint'))].filter(x=>x.status==='READY').length,backupReady,backupVerified:backupReady,overdueOrders:overdue,unverifiedLeads:leads.filter(x=>!x.verified).length,openFollowups:quotes.filter(q=>q.nextFollowupAt&&new Date(q.nextFollowupAt)<new Date()).length,unpaidOrders:unpaid,failedPayments:failed};
}
app.get('/api/kim/v370/summary',auth,requireCapability('kim370.read'),async(req,res)=>{await kim370LoadMissions();const c=kim370Context();V370.tick(c);res.json({ok:true,...V370.summary(c)});});
