// V38.0.0 — Kim Growth & Outbound Autopilot. Generates, stages and audits growth missions while fail-closing external sends.
async function kim380PersistMission(m){
  if(!mysqlPool)return;
  await mysqlPool.query(`INSERT INTO sbc_kim_growth_missions (id,tenant_id,automation_id,automation_name,title,domain,mode,status,input_hash,input_json,created_by,created_at,updated_at,completed_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),updated_at=VALUES(updated_at),completed_at=VALUES(completed_at)`,[m.id,1,m.automationId,m.automation,m.title,m.domain,m.mode,m.status,m.inputHash,JSON.stringify(m.inputSummary||{}),String(m.createdBy||'Kim'),sqlDateTime(m.createdAt),sqlDateTime(m.updatedAt),m.completedAt?sqlDateTime(m.completedAt):null]);
}
async function kim380Load(){
  if(!mysqlPool)return;
  const [rows]=await mysqlPool.query(`SELECT id,automation_id AS automationId,automation_name AS automation,title,domain,mode,status,input_hash AS inputHash,input_json,created_by AS createdBy,created_at AS createdAt,updated_at AS updatedAt,completed_at AS completedAt FROM sbc_kim_growth_missions ORDER BY created_at DESC LIMIT 1000`);
  for(const r of rows){try{r.inputSummary=JSON.parse(r.input_json||'{}')}catch{r.inputSummary={}}delete r.input_json;const i=V380.state.missions.findIndex(x=>x.id===r.id);if(i<0)V380.state.missions.push(r);else V380.state.missions[i]=r;}
  V380.state.missions.sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)));
}
