// V39.2.0 — Kim Commercial Readiness: GBP, KYB, provider, AI, lead-mesh, workforce and notary readiness.

// ===== V40.0.0 KIM FULFILLMENT CONTROL PLANE =====
// Turns a paid order into an auditable fulfillment state machine. External vendor
// submission is fail-closed until an authorized provider is explicitly marked READY.
const V400_PAYMENT_EVIDENCE=require('./enterprise/v6640-payment-evidence.cjs');
function v400Orders(){return Array.isArray(db.orders)?db.orders:[];}
function v400Can(req){return hasCapability(req,'fulfillment.manage');}
function v400VendorReady(provider){
  const p=String(provider||'').toLowerCase();
  if(p==='internal')return true;
  const map={four_over_four:['FOUROVER4_API_KEY','FOUROVER4_ORDER_ENDPOINT'],vistaprint:['VISTAPRINT_API_KEY','VISTAPRINT_ORDER_ENDPOINT'],godaddy:['GODADDY_PAT']};
  const reqs=map[p]||[];
  return reqs.length>0&&reqs.every(k=>Boolean(process.env[k]||secretCache?.has?.(k)));
}
function v400ApplyOrderStage(id,stage){
  const o=v400Orders().find(x=>String(x.id)===String(id)); if(!o)return;
  if(!V400_PAYMENT_EVIDENCE.confirmedPaid(o))throw Object.assign(new Error('PAYMENT_EVIDENCE_REQUIRED'),{code:'PAYMENT_EVIDENCE_REQUIRED'});
  const map={PAID:['Paid','Ready for Fulfillment'],INTAKE:['Paid','Fulfillment Intake'],ASSET_REQUIRED:['Paid','Awaiting Assets'],PREFLIGHT:['Paid','Preflight'],PROOF_PENDING:['Paid','Proof Pending'],PROOF_APPROVED:['Paid','Proof Approved'],PRODUCTION_READY:['Paid','Ready for Production'],VENDOR_STAGED:['Paid','Vendor Staged'],VENDOR_SUBMITTED:['In Progress','Submitted to Vendor'],IN_PRODUCTION:['In Progress','In Production'],SHIPPED:['Dispatched','Shipped'],DELIVERED:['Delivered','Delivered'],FULFILLED:['Delivered','Fulfilled'],BLOCKED:['Paid','Fulfillment Blocked']};
  const vals=map[stage]||['Paid',stage]; o.status=vals[0];o.fulfillmentStatus=vals[1];o.updatedAt=now();saveData().catch(()=>{});
}
// SBC_V6641_FULFILLMENT_PAYMENT_EVIDENCE: authorize and verify BEFORE V400 order changes.
app.use('/api/kim400/orders/:id',auth,(req,res,next)=>{
  if(req.method==='GET'||req.method==='HEAD')return next();
  const o=v400Orders().find(x=>String(x.id)===String(req.params.id));
  if(!o)return res.status(404).json({ok:false,error:'Order not found.'});
  if(!V400_PAYMENT_EVIDENCE.confirmedPaid(o))
    return res.status(409).json({ok:false,code:'PAYMENT_EVIDENCE_REQUIRED',error:'Confirmed payment required before fulfillment.'});
  next();
});
app.get('/api/fulfillment/provider-center',auth,requireCapability('fulfillment.manage'),(req,res)=>res.json({ok:true,version:BUILD_VERSION,providers:fulfillmentProviderCenter(),capabilities:vendorCapabilities()}));
app.post('/api/kim400/orders/:id/vendor/manual-submit',auth,requireCapability('fulfillment.manage'),async(req,res)=>{try{const provider=String(req.body?.provider||'').trim();if(!['four_over_four','4over4','vistaprint','godaddy','internal'].includes(provider.toLowerCase()))return res.status(400).json({error:'Unsupported fulfillment provider.'});const normalized=provider.toLowerCase()==='4over4'||provider==='four_over_four'?'four_over_four':provider.toLowerCase();const order=V400.get(req.params.id,v400Orders());if(!order)return res.status(404).json({error:'Fulfillment order not found.'});if(!['PRODUCTION_READY','VENDOR_STAGED'].includes(order.stage))return res.status(409).json({error:`Order must be production-ready before manual vendor handoff. Current stage: ${order.stage}.`});const staged=V400.markVendorReady(req.params.id,normalized,req.user);const vendorOrderId=String(req.body?.vendorOrderId||'').trim();const vendor=V400.submitVendor(req.params.id,vendorOrderId||`MANUAL-${Date.now()}`,req.user);v400ApplyOrderStage(req.params.id,'VENDOR_SUBMITTED');audit(req.user,'fulfillment_manual_vendor_handoff',`Manual ${normalized} fulfillment handoff recorded for ${req.params.id}`,{orderId:req.params.id,provider:normalized,vendorOrderId:vendor.orderId});res.json({ok:true,manual:true,provider:normalized,vendor,staged});}catch(e){res.status(400).json({error:e.message})}});
app.post('/api/kim400/orders/:id/vendor/record',auth,requireCapability('fulfillment.manage'),async(req,res)=>{try{const provider=String(req.body?.provider||'').trim();const vendorOrderId=String(req.body?.vendorOrderId||'').trim();if(!provider||!vendorOrderId)return res.status(400).json({error:'Provider and vendor order number are required.'});const order=V400.get(req.params.id,v400Orders());if(!order)return res.status(404).json({error:'Fulfillment order not found.'});if(!['VENDOR_STAGED','VENDOR_SUBMITTED','IN_PRODUCTION','SHIPPED'].includes(order.stage))return res.status(409).json({error:`Vendor record cannot be attached at ${order.stage}.`});const vendor=V400.markVendorReady(req.params.id,provider,req.user);vendor.orderId=vendorOrderId;vendor.status='SUBMITTED';V400.state.orders[String(req.params.id)].vendor=vendor;V400.state.orders[String(req.params.id)].updatedAt=now();V400.state.orders[String(req.params.id)].history.unshift({id:id('fh'),from:order.stage,to:order.stage,actor:req.user.name||'Owner',at:now(),meta:{manualVendorRecord:true,provider,vendorOrderId}});V400.state.orders[String(req.params.id)].stage='VENDOR_SUBMITTED';V400.state.orders[String(req.params.id)].checklist.vendor=true;v400ApplyOrderStage(req.params.id,'VENDOR_SUBMITTED');audit(req.user,'fulfillment_vendor_recorded',`Recorded ${provider} vendor order ${vendorOrderId}`,{orderId:req.params.id,provider,vendorOrderId});res.json({ok:true,order:V400.get(req.params.id,v400Orders())});}catch(e){res.status(400).json({error:e.message})}});
app.get('/api/kim400/summary',auth,requireCapability('fulfillment.manage'),(req,res)=>{try{res.json({ok:true,...V400.summary(v400Orders())});}catch(e){res.status(500).json({error:e.message})}});
