app.post('/api/kim431/lead-mesh/stream',auth,requireCapability('kim410.operate'),async(req,res)=>{try{if(!mysqlPool)return res.status(503).json({ok:false,error:'MySQL is required for live lead-mesh ingestion.'});const file=String(req.body?.file||path.join(__dirname,'starter-leads','SBC-250-Verified-Lead-Prospects.csv'));let inserted=0,duplicates=0,sourceRows=0,batches=0,rowNumber=1;const source='SBC-250-Verified-Lead-Prospects.csv';const result=await V431Leads.streamFile(file,async(rows,meta)=>{batches++;const mapped=rows.map(r=>V431Leads.mapLead(r,source));sourceRows+=mapped.length;for(const lead of mapped){const [out]=await mysqlPool.query('INSERT IGNORE INTO sbc_lead_mesh(batch_id,`row_number`,business_name,contact_name,email,phone,phone_normalized,website,industry,address,source,status,dedupe_key,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[`stream_${V431Leads.batchHash(mapped).slice(0,16)}`,rowNumber++,lead.businessName,lead.contactName,lead.email,lead.phone,lead.phoneNormalized,lead.website,lead.industry,lead.address,lead.source,lead.status,lead.dedupeKey,sqlDateTime(now()),sqlDateTime(now())]);if(Number(out.affectedRows||0))inserted++;else duplicates++;}});audit(req.user,'kim431_lead_mesh_stream','Kim streamed B2B prospect source into active lead mesh',{file,sourceRows,inserted,duplicates,batches});res.json({ok:true,file,sourceRows,inserted,duplicates,batches,total:result.rows});}catch(e){res.status(400).json({ok:false,error:e.message})}});
