async function kim391PersistMission(m){if(!mysqlPool)return;await mysqlPool.query(`INSERT INTO sbc_kim_commercial_readiness_missions (id,tenant_id,capability_id,capability_name,title,domain,mode,status,created_by,input_hash,created_at,updated_at,completed_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),updated_at=VALUES(updated_at),completed_at=VALUES(completed_at)`,[m.id,1,m.capabilityId,m.capability,m.title,m.domain,m.mode,m.status,String(m.createdBy||'Kim'),m.inputHash,sqlDateTime(m.createdAt),sqlDateTime(m.updatedAt),m.completedAt?sqlDateTime(m.completedAt):null]);}
async function kim391Load(){if(!mysqlPool)return;const [rows]=await mysqlPool.query(`SELECT id,capability_id AS capabilityId,capability_name AS capability,title,domain,mode,status,created_by AS createdBy,input_hash AS inputHash,created_at AS createdAt,updated_at AS updatedAt,completed_at AS completedAt FROM sbc_kim_commercial_readiness_missions ORDER BY created_at DESC LIMIT 2000`);V391.state.missions=rows;}
