app.post('/api/kim/v340/orders/:id/stage',auth,async(req,res)=>{if(!v340Gate(req))return res.status(403).json({error:'Kim fulfillment access required.'});try{const o=(db.orders||[]).find(x=>String(x.id)===String(req.params.id));if(!o)return res.status(404).json({error:'Order not found.'});const stage=String(req.body?.stage||'');const result=V340.transition(o,stage,req.user.name||req.user.username||'Kim');o.fulfillmentStage=stage;o.updatedAt=now();if(stage==='Processing'&&req.body?.vendorConfirmed===true){result.locked=true;result.vendorConfirmedAt=now();V340.save();}if(stage==='Dispatched')o.status='Dispatched';await saveData();audit(req.user,'v340_stage_change',`Order ${o.id} moved to ${stage}`,{orderId:o.id,stage});res.json({ok:true,order:o,telemetry:V340.telemetry(o)});}catch(e){res.status(400).json({error:e.message});}});
app.post('/api/kim/v340/orders/bulk-stage',auth,async(req,res)=>{if(!v340Gate(req))return res.status(403).json({error:'Kim fulfillment access required.'});try{const ids=Array.isArray(req.body?.orderIds)?req.body.orderIds:[];const stage=String(req.body?.stage||'');const changed=[];for(const idv of ids){const o=(db.orders||[]).find(x=>String(x.id)===String(idv));if(!o)continue;V340.transition(o,stage,req.user.name||req.user.username||'Kim');o.fulfillmentStage=stage;o.updatedAt=now();if(stage==='Dispatched')o.status='Dispatched';changed.push(o.id);}await saveData();res.json({ok:true,changed,stage});}catch(e){res.status(400).json({error:e.message});}});
