const V435_CIRCUIT=new V435.PartnerCircuitBreaker(['4over4','vistaprint'],{threshold:Number(process.env.SBC_VENDOR_FAILURE_THRESHOLD||3),cooldownMs:Number(process.env.SBC_VENDOR_CIRCUIT_COOLDOWN_MS||30000)});
async function v435CircuitLoad(){if(!redisReady||!redisClient)return;try{const raw=await redisClient.get('sbc:v435:partner-circuit');if(raw)V435_CIRCUIT.restore(JSON.parse(raw));}catch(e){console.warn('[SBC V43.5] circuit state load:',e.message)}}
async function v435CircuitSave(){if(!redisReady||!redisClient)return;try{await redisClient.set('sbc:v435:partner-circuit',JSON.stringify(V435_CIRCUIT.snapshot()),{EX:86400});}catch(e){console.warn('[SBC V43.5] circuit state save:',e.message)}}
