const V437_PRESENTATION_SECRET=()=>process.env.SBC_PRESENTATION_SIGNING_SECRET||process.env.SBC_TENANT_CONTEXT_KEY||process.env.SBC_SESSION_SECRET;
function v437Portals(){const m=megaData();return m.presentationPortals;}
function v437PortalUrl(req,token){const base=String(process.env.SBC_PUBLIC_URL||`${req.protocol}://${req.get('host')}`).replace(/\/$/,'');return `${base}/presentation/${encodeURIComponent(token)}`;}
function v437PortalFind(token){return v437Portals().find(x=>String(x.token)===String(token));}
function v437PublicHtml(token){const safe=String(token).replace(/[^A-Za-z0-9_-]/g,'');return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SBC Client Presentation</title><style>body{font-family:Inter,Arial,sans-serif;background:#f5f7fb;margin:0;color:#14213d}.wrap{max-width:860px;margin:8vh auto;padding:24px}.card{background:#fff;border-radius:18px;padding:28px;box-shadow:0 10px 35px rgba(0,0,0,.08)}input,button{font:inherit;padding:12px;border-radius:10px;border:1px solid #d7dce5}button{background:#0b5cff;color:#fff;border:0;font-weight:700;cursor:pointer}.hidden{display:none}.item{padding:12px 0;border-bottom:1px solid #eee}.muted{color:#667085}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}textarea{width:100%;min-height:100px;padding:12px;border-radius:10px;border:1px solid #d7dce5;box-sizing:border-box}</style></head><body><div class="wrap"><div class="card"><h1>Successful By Choice</h1><p class="muted">Secure Client Presentation</p><div id="login"><p>This presentation is password protected.</p><input id="pw" type="password" placeholder="Presentation password"><button onclick="openPortal()">Open Presentation</button><p id="err"></p></div><div id="content" class="hidden"></div></div></div><script>const token=${JSON.stringify(safe)};let access='';async function openPortal(){const password=document.getElementById('pw').value;const r=await fetch('/api/public/presentation/'+encodeURIComponent(token)+'/access',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password})});const d=await r.json();if(!r.ok||!d.ok){document.getElementById('err').textContent=d.reason||d.error||'Unable to open presentation.';return}access=d.accessToken;document.getElementById('login').classList.add('hidden');const p=d.presentation;document.getElementById('content').classList.remove('hidden');document.getElementById('content').innerHTML='<h2>'+esc(p.title)+'</h2><h3>'+esc(p.asset.businessName)+'</h3><p>'+esc(p.asset.headline)+'</p><p>'+esc(p.asset.summary)+'</p>'+p.asset.items.map(i=>'<div class="item"><b>'+esc(i.name)+'</b> · '+Number(i.quantity||0)+'<br><span class="muted">'+esc(i.description)+'</span></div>').join('')+'<div class="actions"><button onclick="act(\'approve\')">Approve Presentation</button><button onclick="requestRevision()">Request Changes</button></div><p id="status"></p>';}async function act(type,note=''){const r=await fetch('/api/public/presentation/'+encodeURIComponent(token)+'/event',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+access},body:JSON.stringify({type,note})});const d=await r.json();document.getElementById('status').textContent=d.ok?(type==='approve'?'Presentation approved. Thank you!':'Revision request received.'):(d.reason||d.error||'Unable to record action.');}function requestRevision(){const n=prompt('What would you like changed?');if(n)act('revision',n)}function esc(v){return String(v??'').replace(/[&<>\"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[m]))}</script></body></html>`;}
