async function seedLeadMeshToMySQL(){
  if(!mysqlPool)return {skipped:true,reason:'mysql_unavailable'};
  try{
    const result=V350.importCSV();
    let inserted=0;
    for(const r of (result.records||[])){
      const [out]=await mysqlPool.query('INSERT IGNORE INTO sbc_lead_mesh(batch_id,`row_number`,business_name,contact_name,email,phone,phone_normalized,website,industry,address,source,status,dedupe_key,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[r.batchId,r.rowNumber,r.businessName,r.contactName,r.email,r.phone,r.phoneNormalized,r.website,r.industry,r.address,r.source,r.status,r.dedupeKey,sqlDateTime(now()),sqlDateTime(now())]);
      inserted+=Number(out.affectedRows||0);
    }
    result.inserted=inserted;
    result.skipped=Math.max(0,(result.rows||0)-inserted);
    console.log(`[SBC V35] Lead mesh startup import: ${inserted} inserted, ${result.skipped} skipped.`);
    return result;
  }catch(e){
    const message=String(e?.message||e);
    if(/Lead source not found:/i.test(message)){
      const staged={status:'STAGED',reason:'starter_source_not_installed',source:'starter-leads/SBC-250-Verified-Lead-Prospects.csv',rows:0,inserted:0,skipped:0};
      console.log('[SBC V35] Lead mesh startup import: STAGED — starter prospect source is not installed; existing CRM leads are preserved.');
      return staged;
    }
    console.warn('[SBC V35] Lead mesh startup import:',message);
    return {error:message};
  }
}

