// V58.3 STOREFRONT CHECKOUT EVENT INGESTION
// This endpoint records paid checkout events and queues Agent OS work.
// Provider signature verification should be wired to the existing provider adapter.
app.post('/api/webhooks/storefront/checkout', async (req, res) => {
  try {
    const pool = mysqlPool;
    if (!pool) return res.status(503).json({ ok:false, error:'database_unavailable' });

    const provider=String(req.body?.provider||'').trim().toLowerCase();
    const signature=String(req.headers['x-webhook-signature']||req.headers['x-square-signature']||req.headers['stripe-signature']||'');
    const rawBody=req.rawBody||Buffer.from(JSON.stringify(req.body||{}));
    let verified=false;
    if(provider==='stripe'){try{verified=Boolean(CASH_FABRIC.merchant.verifyStripeSignature(rawBody,signature)?.ok);}catch{verified=false;}}
    else if(provider==='square'){
      const key=String(process.env.SQUARE_WEBHOOK_SIGNATURE_KEY||'');
      const target=String(process.env.SBC_STOREFRONT_WEBHOOK_URL||process.env.SQUARE_STOREFRONT_WEBHOOK_URL||(process.env.SBC_PUBLIC_URL?String(process.env.SBC_PUBLIC_URL).replace(/\/$/,'')+'/api/webhooks/storefront/checkout':'')).trim();
      if(key&&target&&signature){const expected=crypto.createHmac('sha256',key).update(target).update(rawBody).digest('base64');const a=Buffer.from(signature.trim()),b=Buffer.from(expected);verified=a.length===b.length&&a.length>0&&crypto.timingSafeEqual(a,b);}
    }else{
      const secret=String(secretValue('SBC_STOREFRONT_WEBHOOK_SECRET','SBC_STOREFRONT_WEBHOOK_SECRET')||'');
      if(secret&&signature){const expected=crypto.createHmac('sha256',secret).update(rawBody).digest('hex');const a=Buffer.from(signature.replace(/^sha256=/,'').trim()),b=Buffer.from(expected);verified=a.length===b.length&&a.length>0&&crypto.timingSafeEqual(a,b);}
    }
    if(!verified)return res.status(401).json({ok:false,error:'invalid_or_unconfigured_webhook_signature'});
    const handler = new StorefrontCheckoutEventHandler({pool,signatureVerifier:async()=>true});

    const result = await handler.handle(req.body, {
      rawBody: req.rawBody || JSON.stringify(req.body),
      signature: req.headers['x-webhook-signature'] || req.headers['x-square-signature'] || req.headers['stripe-signature']
    });

    const statusCode = result.status === 'REJECTED_SIGNATURE' ? 401
      : result.status === 'FROZEN_GLOBAL_KILL_SWITCH' ? 423
      : 200;
    if(result.accepted!==false){try{await SBC_GOD_EVENTS.publish('checkout.received',{tenantId:1,aggregateType:'order',aggregateId:String(result.orderId||result.order?.id||''),payload:{status:result.status||'',providerEventId:result.providerEventId||'',orderId:result.orderId||result.order?.id||''},idempotencyKey:`checkout:${String(result.providerEventId||result.eventId||result.orderId||crypto.randomUUID())}`});}catch(eventError){console.warn('[SBC GOD EVENT FABRIC] checkout event deferred:',eventError.message);}}
    return res.status(statusCode).json({ ok: result.accepted !== false, ...result });
  } catch (error) {
    console.error('[V58.3 checkout webhook]', error);
    try { global.__SBC_UNATTENDED_NOTIFICATIONS?.sendCriticalAlert('square-checkout-webhook', `Square checkout webhook processing failed: ${String(error?.message||error).slice(0,300)}. Review webhook logs before retrying.`).catch(()=>{}); } catch {}
    return res.status(500).json({ ok:false, error:'checkout_event_failed' });
  }
});

